## ✅ Step 2: `upload.js` — API Layer

```javascript
// src/api/upload.js
import { createChunker } from '../utils/chunker.js';
import { ref, onMounted, onUnmounted } from 'vue';

export function useUpload(file, chunkSize = 5 * 1024 * 1024) {
  const chunks = ref([]);
  const totalSize = ref(0);
  const totalChunks = ref(0);
  const fileHash = ref('');
  const uploadedChunks = ref(new Set());
  const failedChunks = ref(new Set());
  const progress = ref(0);
  const status = ref('idle');
  const error = ref(null);

  const uploadChunk = async (chunk, chunkIndex) => {
    if (uploadedChunks.value.has(chunk.id) || failedChunks.value.has(chunk.id)) {
      return true;
    }

    const formData = new FormData();
    formData.append('chunk', chunk.blob);
    formData.append('chunkIndex', chunkIndex);
    formData.append('fileHash', fileHash.value);
    formData.append('chunkSize', chunkSize);

    try {
      const res = await fetch('/api/upload/chunk', {
        method: 'POST',
        body: formData,
      });
      if (!res.ok) {
        throw new Error('Upload failed');
      }
      uploadedChunks.value.add(chunk.id);
      chunk.uploaded = true;
      return true;
    } catch (err) {
      chunk.failed = true;
      failedChunks.value.add(chunk.id);
      chunk.retries++;
      chunk.retryDelay = Math.min(3000, chunk.retryDelay * 2);
      error.value = err;
      return false;
    }
  };

  const resumeChunk = async (chunk, chunkIndex) => {
    if (uploadedChunks.value.has(chunk.id)) return true;
    if (failedChunks.value.has(chunk.id)) return false;

    const formData = new FormData();
    formData.append('chunk', chunk.blob);
    formData.append('chunkIndex', chunkIndex);
    formData.append('fileHash', fileHash.value);
    formData.append('chunkSize', chunkSize);

    try {
      const res = await fetch('/api/upload/chunk', {
        method: 'POST',
        body: formData,
      });
      if (!res.ok) {
        throw new Error('Resume failed');
      }
      uploadedChunks.value.add(chunk.id);
      chunk.uploaded = true;
      return true;
    } catch (err) {
      chunk.failed = true;
      failedChunks.value.add(chunk.id);
      chunk.retries++;
      chunk.retryDelay = Math.min(3000, chunk.retryDelay * 2);
      error.value = err;
      return false;
    }
  };

  const uploadAll = async () => {
    if (!file) return;
    status.value = 'uploading';
    error.value = null;
    const chunker = createChunker(file, chunkSize);
    chunks.value = chunker.chunks;
    totalSize.value = chunker.totalSize;
    totalChunks.value = chunker.totalChunks;
    fileHash.value = chunker.fileHash;

    const uploadPromises = chunks.value.map((chunk, i) => {
      return new Promise((resolve) => {
        const tryUpload = () => {
          if (uploadedChunks.value.has(chunk.id)) {
            resolve(true);
            return;
          }
          if (failedChunks.value.has(chunk.id)) {
            resolve(false);
            return;
          }
          if (chunk.failed) {
            setTimeout(() => {
              if (chunk.retries < 3) {
                tryUpload();
              } else {
                resolve(false);
              }
            }, chunk.retryDelay);
            return;
          }
          if (chunk.uploaded) {
            resolve(true);
            return;
          }
          uploadChunk(chunk, i).then(resolve);
        };
        tryUpload();
      });
    });

    const results = await Promise.all(uploadPromises);

    if (results.every(Boolean)) {
      status.value = 'success';
      progress.value = 100;
    } else {
      status.value = 'failed';
    }
  };

  const resumeAll = async () => {
    if (!file) return;
    status.value = 'resuming';
    error.value = null;
    const chunker = createChunker(file, chunkSize);
    chunks.value = chunker.chunks;
    totalSize.value = chunker.totalSize;
    totalChunks.value = chunker.totalChunks;
    fileHash.value = chunker.fileHash;

    const uploadPromises = chunks.value.map((chunk, i) => {
      return new Promise((resolve) => {
        const tryUpload = () => {
          if (uploadedChunks.value.has(chunk.id)) {
            resolve(true);
            return;
          }
          if (failedChunks.value.has(chunk.id)) {
            resolve(false);
            return;
          }
          if (chunk.failed) {
            setTimeout(() => {
              if (chunk.retries < 3) {
                tryUpload();
              } else {
                resolve(false);
              }
            }, chunk.retryDelay);
            return;
          }
          if (chunk.uploaded) {
            resolve(true);
            return;
          }
          resumeChunk(chunk, i).then(resolve);
        };
        tryUpload();
      });
    });

    const results = await Promise.all(uploadPromises);

    if (results.every(Boolean)) {
      status.value = 'success';
      progress.value = 100;
    } else {
      status.value = 'failed';
    }
  };

  const reset = () => {
    chunks.value = [];
    totalSize.value = 0;
    totalChunks.value = 0;
    fileHash.value = '';
    uploadedChunks.value = new Set();
    failedChunks.value = new Set();
    progress.value = 0;
    status.value = 'idle';
    error.value = null;
  };

  return {
    chunks,
    totalSize,
    totalChunks,
    fileHash,
    uploadedChunks,
    failedChunks,
    progress,
    status,
    error,
    uploadAll,
    resumeAll,
    reset,
  };
}
```

