## ✅ Step 4: Backend API (Node.js + Express)

Create `server.js`:

```javascript
// server.js
const express = require('express');
const multer = require('multer');
const crypto = require('crypto');
const fs = require('fs').promises;
const path = require('path');
const app = express();

const storage = multer.memoryStorage();
const upload = multer({ storage });

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Store chunks in a directory (or Redis/DB in production)
const CHUNK_DIR = './chunks';
if (!fs.existsSync(CHUNK_DIR)) fs.mkdir(CHUNK_DIR, { recursive: true });

app.post('/api/upload/chunk', upload.single('chunk'), async (req, res) => {
  const { chunkIndex, fileHash, chunkSize } = req.body;
  const chunk = req.file;
  const chunkPath = path.join(CHUNK_DIR, `${fileHash}-${chunkIndex}.bin`);

  try {
    await fs.writeFile(chunkPath, chunk.buffer);
    res.status(200).json({ ok: true });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

app.post('/api/upload/complete', async (req, res) => {
  const { fileHash } = req.body;
  const chunksDir = path.join(CHUNK_DIR, fileHash);
  const files = await fs.readdir(chunksDir);
  const totalSize = files.reduce((sum, f) => sum + parseInt(f.replace(/.*(\d+).bin$/, '$1')), 0);

  const outputFile = path.join(CHUNK_DIR, `${fileHash}.bin`);
  try {
    await fs.writeFile(outputFile, await fs.readFile(chunksDir + '/0.bin'));
    await fs.rm(chunksDir, { recursive: true, force: true });
    res.status(200).json({ ok: true, size: totalSize });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

