### 2. `YUV420PToImage.java`

```java
import org.opencv.core.*;
import org.opencv.imgproc.Imgproc;
import org.opencv.imgcodecs.Imgcodecs;

public class YUV420PToImage {
    public static BufferedImage toBufferedImage(Mat yuvMat) {
        if (yuvMat.empty()) return null;
        if (yuvMat.channels() != 3) {
            // Convert YUV420P to BGR
            Mat bgr = new Mat();
            Imgproc.cvtColor(yuvMat, bgr, Imgproc.COLOR_YUV2BGR_I420);
            return matToBufferedImage(bgr);
        } else {
            return matToBufferedImage(yuvMat);
        }
    }

    public static BufferedImage matToBufferedImage(Mat mat) {
        if (mat.empty()) return null;
        if (mat.channels() == 3) {
            return matToBufferedImage3Channel(mat);
        } else if (mat.channels() == 1) {
            return matToBufferedImage1Channel(mat);
        }
        return null;
    }

    private static BufferedImage matToBufferedImage3Channel(Mat mat) {
        int type = BufferedImage.TYPE_3BYTE_BGR;
        BufferedImage image = new BufferedImage(mat.cols(), mat.rows(), type);
        byte[] data = new byte[mat.cols() * mat.rows() * 3];
        mat.get(0, 0, data);
        image.getRaster().setDataElements(0, 0, mat.cols(), mat.rows(), data);
        return image;
    }

    private static BufferedImage matToBufferedImage1Channel(Mat mat) {
        int type = BufferedImage.TYPE_BYTE_GRAY;
        BufferedImage image = new BufferedImage(mat.cols(), mat.rows(), type);
        byte[] data = new byte[mat.cols() * mat.rows()];
        mat.get(0, 0, data);
        image.getRaster().setDataElements(0, 0, mat.cols(), mat.rows(), data);
        return image;
    }
}
