import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.awt.image.BufferedImage;
import org.opencv.core.*;
import org.opencv.imgcodecs.Imgcodecs;

public class Main {
    private static final String CAMERA_IP = "192.168.1.64"; // Replace with your camera IP
    private static final String USERNAME = "admin";
    private static final String PASSWORD = "123456";

    private HikvisionCamera camera;
    private CameraPanel panel;
    private Timer timer;
    private boolean running = false;

    public Main() {
        camera = new HikvisionCamera(CAMERA_IP, USERNAME, PASSWORD);
        if (!camera.isConnected()) {
            JOptionPane.showMessageDialog(null, "Failed to connect to camera.", "Error", JOptionPane.ERROR_MESSAGE);
            System.exit(1);
        }

        panel = new CameraPanel();
        panel.setPreferredSize(new Dimension(640, 480));

        JFrame frame = new JFrame("Hikvision Live Stream");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setLayout(new BorderLayout());

        JPanel controls = new JPanel();
        controls.setLayout(new FlowLayout());

        JButton startBtn = new JButton("Start");
        startBtn.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                if (!running) {
                    startStreaming();
                    startBtn.setText("Pause");
                } else {
                    stopStreaming();
                    startBtn.setText("Start");
                }
            }
        });

        JButton stopBtn = new JButton("Stop");
        stopBtn.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                stopStreaming();
            }
        });

        controls.add(startBtn);
        controls.add(stopBtn);

        frame.add(panel, BorderLayout.CENTER);
        frame.add(controls, BorderLayout.SOUTH);

        frame.pack();
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
    }

    private void startStreaming() {
        running = true;
        timer = new Timer(33, new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                Mat frame = new Mat();
                if (camera.captureFrame(frame)) {
                    BufferedImage img = YUV420PToImage.toBufferedImage(frame);
                    if (img != null) {
                        panel.setImage(img);
                    }
                } else {
                    panel.clear();
                }
            }
        });
        timer.start();
    }

    private void stopStreaming() {
        running = false;
        if (timer != null) {
            timer.stop();
            timer = null;
        }
        camera.disconnect();
    }

    public static void main(String[] args) {
        // Initialize OpenCV
        System.loadLibrary(Core.NATIVE_LIBRARY_NAME);

