Here's a **3D Starship Physics Game** that runs in the browser using **Three.js** and **Cannon.js** (physics engine). The player pilots a spacecraft through a starfield, where planets exert gravitational attraction. The goal is to navigate between stars while managing speed — slow down to be captured by a planet, speed up to escape.

---

### 🌌 Features:
- 3D universe with stars and planets.
- Player spacecraft with thrust and braking.
- Realistic gravity from planets (Newtonian).
- Collision detection with planets.
- Score based on distance traveled.
- Pause/resume.
- Keyboard controls.

---

### 📦 Dependencies:
Install via CDN (no build required):

```html
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/cannon.js/0.6.2/cannon.min.js"></script>
```

---

### 🎮 Controls:
- **W / Up Arrow** → Thrust forward
- **S / Down Arrow** → Brake / reverse
- **A / Left Arrow** → Rotate left
- **D / Right Arrow** → Rotate right
- **Space** → Pause
- **Mouse drag** → Aim camera (optional)

---

### 🧩 Code:

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Starship: Gravity Pilot</title>
<style>
  body { margin: 0; overflow: hidden; background: #000; color: #fff; font-family: monospace; }
  canvas { display: block; }
  #hud { position: absolute; top: 10px; left: 10px; color: #fff; font-size: 14px; pointer-events: none; }
  #hud .stat { display: inline-block; margin-right: 15px; }
  #hud .stat b { color: #0f0; }
  #hud .stat span { color: #ccc; }
  #hud .danger { color: #f00; }
  #hud .safe { color: #0f0; }
  #pause { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); color: #fff; font-size: 48px; text-align: center; pointer-events: none; }
</style>
</head>
<body>
<div id="hud">
  <div class="stat"><b>Speed:</b><span id="speed">0.0 km/s</span></div>
  <div class="stat"><b>Altitude:</b><span id="alt">0 km</span></div>
  <div class="stat"><b>Score:</b><span id="score">0</span></div>
  <div class="stat"><b>Planet:</b><span id="planet">None</span></div>
</div>
<div id="pause">PAUSED</div>
<script>
// ---------- CONFIG ----------
const GRAVITY = 6.67430e-11; // m^3 / kg s^2
const PLAYER_MASS = 1000;
const PLANET_MASS = 1e24;
const STAR_COUNT = 20;
const PLANET_COUNT = 6;

// ---------- STATE ----------
const state = {
  running: true,
  paused: false,
  score: 0,
  speed: 0,
  altitude: 0,
  currentPlanet: null,
  planets: [],
  stars: [],
  cameraTarget: new THREE.Vector3(),
  cameraSpeed: 0.01,
};

// ---------- THREE.JS SETUP ----------
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x050302, 0.015);
scene.background = new THREE.Color(0x050302);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 10000);
camera.position.set(0, 5, 10);
camera.lookAt(0, 0, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// Lighting
const hemi = new THREE.HemisphereLight(0x88bbff, 0x112233, 0.5);
scene.add(hemi);

const sun = new THREE.DirectionalLight(0xffffff, 1.2);
sun.position.set(100, 80, 50);
scene.add(sun);

const spot = new THREE.SpotLight(0xffaa44, 0.8);
spot.position.set(20, 30, 10);
spot.angle = 0.6;
scene.add(spot);

// ---------- CANNON.JS WORLD ----------
const world = new CANNON.World();
world.gravity.set(0, 0, 0);
world.broadphase = new CANNON.NaiveBroadphase();
world.solver.iterations = 20;
world.quadTree = new CANNON.QuadTree();

// ---------- PLAYER ----------
const playerBody = new CANNON.Body({ mass: PLAYER_MASS });
playerBody.position.set(0, 1, 0);
playerBody.quaternion.setFromAxisAngle(new CANNON.Vec3(0, 1, 0), 0);
world.addBody(playerBody);

const playerMesh = new THREE.Mesh(
  new THREE.SphereGeometry(0.5, 32, 32),
  new THREE.MeshBasicMaterial({ color: 0xff6600, wireframe: false })
);
scene.add(playerMesh);

// ---------- PLANETS ----------
function makePlanet(pos, radius, color, name) {
  const body = new CANNON.Body({ mass: PLANET_MASS });
  body.position.copy(pos);
  world.addBody(body);

  const geom = new CANNON.Sphere(radius);
  const shape = new CANNON.SphereShape(radius);
  body.addShape(shape);

  const mesh = new THREE.Mesh(
    new THREE.SphereGeometry(radius * 2, 32, 32),
    new THREE.MeshStandardMaterial({ color, emissive: color, roughness: 0.8, metalness: 0.2 })
  );
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  scene.add(mesh);

  return { body, mesh, radius, name };
}

// Generate planets
const planetPositions = [
  [8, 0, 0],
  [-8, 0, 0],
  [0, 8, 0],
  [0, -8, 0],
  [4, 4, 4],
  [-4, -4, -4],
];
const planetColors = ['#ff6600', '#0088ff', '#ffcc00', '#00ffaa', '#ff00ff', '#88ff00'];

state.planets = planetPositions.map((p, i) => makePlanet(p, 1.5 + i * 0.5, planetColors[i], `Planet ${i + 1}`));

// ---------- STARS ----------
function makeStar(pos, size, color) {
  const geo = new THREE.SphereGeometry(size, 6, 6);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.8 });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.copy(pos);
  scene.add(mesh);
  return mesh;
}

state.stars = [];
for (let i = 0; i < STAR_COUNT; i++) {
  const r = 30 + Math.random() * 30;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  const x = r * Math.sin(phi) * Math.cos(theta);
  const y = r * Math.sin(phi) * Math.sin(theta);
  const z = r * Math.cos(phi);
  state.stars.push(makeStar(new THREE.Vector3(x, y, z), 0.05 + Math.random() * 0.03, 0xffffff));
}

// ---------- CAMERA TARGET ----------
state.cameraTarget.copy(playerBody.position);

// ---------- INPUT ----------
const keys = {};
window.addEventListener('keydown', (e) => {
  keys[e.code] = true;
  if (e.code === 'Space') togglePause();
});
window.addEventListener('keyup', (e) => { keys[e.code] = false; });

// ---------- UPDATE ----------
function updatePhysics(dt) {
  if (!state.running || state.paused) return;

  const playerPos = playerBody.position;
  const playerVel = playerBody.velocity;

  // Compute current gravitational force from planets
  let totalForce = new CANNON.Vec3();
  for (const p of state.planets) {
    const r = new CANNON.Vec3();
    r.subVectors(p.body.position, playerPos);
    const d = r.length();
    if (d < 0.001) d = 0.001;
    const forceMag = GRAVITY * p.body.mass * PLAYER_MASS / (d * d);
    const forceDir = r.clone().normalize().scale(forceMag);
    totalForce.add(forceDir);
  }

  // Thrust
  let thrust = 0;
  if (keys['KeyW'] || keys['ArrowUp']) thrust += 10000;
  if (keys['KeyS'] || keys['ArrowDown']) thrust -= 10000;

  // Rotation (in world space)
  const rotSpeed = 100;
  const rotDir = new CANNON.Vec3();
  if (keys['KeyA'] || keys['ArrowLeft']) rotDir.set(0, 1, 0);
  if (keys['KeyD'] || keys['ArrowRight']) rotDir.set(0, -1, 0);
  if (rotDir.lengthSq() > 0) {
    playerBody.angularVelocity.setLength(rotSpeed * rotDir.length());
  }

  // Apply forces
  playerBody.applyForce(totalForce, playerPos);
  playerBody.applyTorque(new CANNON.Vec3(0, 0, 0));

  // Thrust vector (forward direction in local space)
  const forward = new CANNON.Vec3(0, 0, -1);
  playerBody.quaternion.vmult(forward, forward);
  playerBody.applyForce(forward.clone().scale(thrust), playerPos);

  // Update HUD
  const speedKm = playerVel.length() * 0.001;
  state.speed = speedKm;
  state.altitude = playerPos.length();

  const closest = state.planets.reduce((a, b) => {
    const d1 = playerPos.distanceTo(b.body.position);
    const d2 = playerPos.distanceTo(a.body.position);
    return d1 < d2 ? b : a;
  }, state.planets[0]);
  state.currentPlanet = closest;
}

function updateCamera(dt) {
  if (!state.running || state.paused) return;

  const target = state.cameraTarget;
  const playerPos = playerBody.position;

  // Smooth camera target toward player
  target.lerp(playerPos, state.cameraSpeed);

  camera.position.lerp(target, 0.05);
  camera.lookAt(playerPos);

  // Move camera slightly up for a better view
  const up = new THREE.Vector3(0, 1, 0);
  const camDir = new THREE.Vector3().subVectors(playerPos, camera.position).normalize();
  const right = new THREE.Vector3().crossVectors(camDir, up).normalize();
  const newCamPos = playerPos.clone().add(camDir.clone().multiplyScalar(8)).add(right.clone().multiplyScalar(2));
  camera.position.lerp(newCamPos, 0.1);

  // Camera look-at
  camera.lookAt(playerPos);
}

function updateHUD() {
  document.getElementById('speed').textContent = state.speed.toFixed(2) + ' km/s';
  document.getElementById('alt').textContent = state.altitude.toFixed(1) + ' km';
  document.getElementById('score').textContent = Math.round(state.score);
  const p = state.currentPlanet;
  document.getElementById('planet').textContent = p ? p.name : 'None';
  const danger = p && state.altitude < 2000;
  document.getElementById('planet').style.color = danger ? 'red' : 'white';
  document.getElementById('planet').style.fontWeight = danger ? 'bold' : 'normal';
}

function togglePause() {
  state.paused = !state.paused;
  document.getElementById('pause').textContent = state.paused ? 'PAUSED' : 'GO';
  document.getElementById('pause').style.opacity = state.paused ? '1' : '0.3';
}

// ---------- RENDER ----------
function animate() {
  requestAnimationFrame(animate);
  const dt = 0.016; // ~60 fps
  updatePhysics(dt);
  updateCamera(dt);
  updateHUD();
  renderer.render(scene, camera);
}

// ---------- RESIZE ----------
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ---------- START ----------
animate();
</script>
</body>
</html>
```

---

### ✅ How to Play:

1. **Thrust forward** (W / Up) to escape planets.
2. **Brake** (S / Down) to slow down and be captured.
3. **Rotate** (A / D) to aim your thrust direction.
4. **Pause** with Space.
5. **Score** increases with distance traveled (altitude).

---

### 🧠 Physics Notes:

- Uses **Newtonian gravity** with `F = G * m1 * m2 / r^2`.
- Planets are **massive spheres** with `CANNON.SphereShape`.
- Player body is a small sphere with `CANNON.Body`.
- Camera follows the player with a slight offset for better visibility.
- HUD shows speed, altitude, closest planet, and score.

