.modal { background: var(--bg-elev); border: 1px solid var(--border); border-radius: var(--radius); max-width: 520px; width: 100%; max-height: 90vh; overflow: auto; position: relative; }
.modal-header { padding: 16px 20px; border-bottom: 1px solid var(--border); display: flex; align-items: center; justify-content: space-between; }
.modal-header h3 { margin: 0; }
.modal-body { padding: 20px; }
.modal-body textarea { width: 100%; min-height: 140px; resize: vertical; }
.modal-footer { padding: 16px 20px; border-top: 1px solid var(--border); display: flex; justify-content: flex-end; gap: 10px; }

/* ---------- Toast ---------- */
.toast-container { position: fixed; top: 20px; right: 20px; display: flex; flex-direction: column; gap: 10px; z-index: 200; pointer-events: none; }
.toast { background: var(--bg-elev); border: 1px solid var(--border); border-left: 3px solid var(--accent); border-radius: var(--radius-sm); padding: 12px 16px; min-width: 260px; max-width: 360px; box-shadow: var(--shadow); pointer-events: auto; animation: slideIn 0.3s ease; }
.toast.error { border-left-color: var(--danger); }
.toast.success { border-left-color: var(--success); }
@keyframes slideIn { from { transform: translateX(120%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }

/* ---------- Pagination ---------- */
.pagination { display: flex; justify-content: center; align-items: center; gap: 6px; margin-top: 24px; }
.page-btn { min-width: 36px; height: 36px; padding: 0 10px; border-radius: var(--radius-sm); border: 1px solid var(--border); background: var(--bg-elev); color: var(--text); font-size: 14px; font-weight: 500; transition: all var(--transition); }
.page-btn:hover:not(:disabled) { background: var(--bg-elev-2); border-color: var(--accent); color: var(--accent); }
.page-btn.active { background: var(--accent); color: #fff; border-color: var(--accent); }
.page-btn:disabled { opacity: 0.4; cursor: not-allowed; }

/* ---------- Toast ---------- */
.toast-container { position: fixed; top: 20px; right: 20px; display: flex; flex-direction: column; gap: 10px; z-index: 200; pointer-events: none; }
.toast { background: var(--bg-elev); border: 1px solid var(--border); border-left: 3px solid var(--accent); border-radius: var(--radius-sm); padding: 12px 16px; min-width: 260px; max-width: 360px; box-shadow: var(--shadow); pointer-events: auto; animation: slideIn 0.3s ease; }
.toast.error { border-left-color: var(--danger); }
.toast.success { border-left-color: var(--success); }
.toast.info { border-left-color: var(--accent-2); }
.toast.fade-out { animation: slideOut 0.3s ease forwards; }
@keyframes slideOut { to { transform: translateX(120%); opacity: 0; } }

/* ---------- Responsive ---------- */
@media (max-width: 900px) {
  .layout { grid-template-columns: 1fr; }
  .sidebar { position: static; }
  #app { padding: 16px; }
}
@media (max-width: 520px) {
  .card { padding: 16px; }
  .page-header { flex-direction: column; align-items: flex-start; }
  .pagination { flex-wrap: wrap; }
  .toast-container { left: 16px; right: 16px; }
  .toast { min-width: 0; max-width: none; }
}
</style>
</head>
<body>

<div id="app">
