<script>
// ---------- Mock Data ----------
const ARTICLES = [
  { id: 1, title: 'The Quiet Art of Slow Design', excerpt: 'In a world obsessed with speed and scale, the discipline of slowing down has become one of the most radical acts a designer can take.', author: 'Alex Morgan', date: '2025-03-14', readTime: '5 min', tags: ['Design', 'Essay'] },
  { id: 2, title: 'Design Systems That Actually Scale', excerpt: 'A practical guide to building components that grow with your team, not against it.', author: 'Alex Morgan', date: '2025-03-02', readTime: '8 min', tags: ['Engineering', 'Systems'] },
  { id: 3, title: 'Minimal CSS in 2025', excerpt: 'Less is more — but only if you know what to keep and what to cut.', author: 'Alex Morgan', date: '2025-02-18', readTime: '6 min', tags: ['CSS', 'Frontend'] },
  { id: 4, title: 'Why I Stopped Using Frameworks', excerpt: 'A case for building small, focused tools instead of big, opinionated ones.', author: 'Alex Morgan', date: '2025-02-04', readTime: '7 min', tags: ['JavaScript', 'Philosophy'] },
  { id: 5, title: 'Dark Mode Done Right', excerpt: 'Beyond a color palette — the hidden details that make dark themes feel native.', author: 'Alex Morgan', date: '2025-01-22', readTime: '4 min', tags: ['UX', 'Dark Mode'] },
  { id: 6, title: 'The Case for Handwritten Code', excerpt: 'When typing by hand is faster than pasting from a template.', author: 'Alex Morgan', date: '2025-01-10', readTime: '3 min', tags: ['Writing', 'Process'] },
];

const PHOTOS = [
  { id: 1, title: 'Sunset over the hills', date: '2025-03-10', tags: ['Nature', 'Travel'] },
  { id: 2, title: 'Coffee in the morning', date: '2025-03-05', tags: ['Life', 'Still Life'] },
  { id: 3, title: 'Bookshelf at home', date: '2025-02-28', tags: ['Home', 'Reading'] },
  { id: 4, title: 'Mountain trail hike', date: '2025-02-20', tags: ['Adventure', 'Nature'] },
  { id: 5, title: 'Neon cityscape', date: '2025-02-12', tags: ['Urban', 'Photography'] },
  { id: 6, title: 'Desert at dusk', date: '2025-02-01', tags: ['Nature', 'Travel'] },
];

const SOCIAL = [
  { id: 1, name: 'Priya Shah', handle: '@priya', status: 'online' },
  { id: 2, name: 'Jordan Lee', handle: '@jordan', status: 'online' },
  { id: 3, name: 'Sofia Ramirez', handle: '@sofia', status: 'offline' },
  { id: 4, name: 'Marcus Chen', handle: '@marcus', status: 'online' },
  { id: 5, name: 'Hana Ito', handle: '@hana', status: 'online' },
  { id: 6, name: 'Diego Alvarez', handle: '@diego', status: 'offline' },
  { id: 7, name: 'Amara Okafor', handle: '@amara', status: 'online' },
  { id: 8, name: 'Leo Park', handle: '@leo', status: 'offline' },
];

const MESSAGES = [
  { id: 1, sender: 'Priya Shah', handle: '@priya', avatar: 'https://i.pravatar.cc/64?img=12', status: 'online', unread: 2, lastMessage: 'Hey! Did you see the new design system post?', time: '2 hours ago', color: 'var(--accent)' },
  { id: 2, sender: 'Jordan Lee', handle: '@jordan', avatar: 'https://i.pravatar.cc/64?img=32', status: 'online', unread: 0, lastMessage: 'Thanks for the article — loved the section on minimal CSS.', time: '5 hours ago', color: 'var(--accent-2)' },
  { id: 3, sender: 'Marcus Chen', handle: '@marcus', avatar: 'https://i.pravatar.cc/64?img=47', status: 'offline', unread: 1, lastMessage: 'Can we talk about the photography series?', time: 'Yesterday', color: 'var(--success)' },
];

const SAMPLE_PHOTO_URLS = [
  'https://picsum.photos/seed/lumen1/800/600',
  'https://picsum.photos/seed/lumen2/800/600',
  'https://picsum.photos/seed/lumen3/800/600',
  'https://picsum.photos/seed/lumen4/800/600',
  'https://picsum.photos/seed/lumen5/800/600',
  'https://picsum.photos/seed/lumen6/800/600',
];

// ---------- State ----------
const state = {
  view: 'home',
  user: null,
  messages: MESSAGES,
  currentConversation: null,
  page: 1,
  pageSize: 3,
};

// ---------- Helpers ----------
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

function formatDate(iso) {
  const d = new Date(iso);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

function formatTime(iso) {
  const d = new Date(iso);
  return d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
}

function toast(message, type = 'info') {
  const container = $('#toastContainer');
  const el = document.createElement('div');
  el.className = `toast ${type}`;
  el.textContent = message;
  container.appendChild(el);
  setTimeout(() => {
    el.classList.add('fade-out');
    setTimeout(() => el.remove(), 300);
  }, 3000);
}

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));
}

// ---------- Rendering ----------
function renderArticles() {
  const list = $('#articleList');
  const start = (state.page - 1) * state.pageSize;
  const pageItems = ARTICLES.slice(start, start + state.pageSize);
  if (pageItems.length === 0) {
    list.innerHTML = '<p class="empty"><i class="fa-solid fa-newspaper"></i> No articles yet. Check back soon.</p>';
    return;
  }
  list.innerHTML = pageItems.map(a => `
    <article class="article">
      <h2>${escapeHtml(a.title)}</h2>
      <p class="card-meta"><i class="fa-solid fa-user"></i> ${escapeHtml(a.author)} · <i class="fa-solid fa-calendar"></i> ${formatDate(a.date)} · <i class="fa-solid fa-clock"></i> ${a.readTime}</p>
      <p>${escapeHtml(a.excerpt)}</p>
      <div style="display:flex;gap:10px;justify-content:space-between;margin-top:12px;">
        <span>${a.tags.join(' · ')}</span>
        <button class="btn btn-ghost btn-sm" style="padding:6px 12px;">Read</button>
      </div>
    </article>
  `).join('');
  renderPagination();
}

function renderPagination() {
  const total = Math.ceil(ARTICLES.length / state.pageSize);
  if (total <= 1) return;
  const wrap = document.createElement('div');
  wrap.className = 'pagination';
  wrap.innerHTML = `
    <button class="page-btn" data-page="prev" ${state.page === 1 ? 'disabled' : ''}><i class="fa-solid fa-chevron-left"></i></button>
    ${Array.from({ length: total }, (_, i) => `
      <button class="page-btn ${i + 1 === state.page ? 'active' : ''}" data-page="${i + 1}">${i + 1}</button>
    `).join('')}
    <button class="page-btn" data-page="next" ${state.page === total ? 'disabled' : ''}><i class="fa-solid fa-chevron-right"></i></button>
  `;
  wrap.addEventListener('click', e => {
    const btn = e.target.closest('.page-btn');
    if (!btn) return;
    const p = btn.dataset.page;
    if (p === 'prev') state.page = Math.max(1, state.page - 1);
    else if (p === 'next') state.page = Math.min(total, state.page + 1);
    else state.page = Number(p);
    renderArticles();
  });
  $('#articleList').parentElement.insertBefore(wrap, $('#articleList').nextElementSibling);
}

function renderPhotos() {
  const grid = $('#photoGrid');
  if (PHOTOS.length === 0) {
    grid.innerHTML = '<p class="empty"><i class="fa-solid fa-camera"></i> No photos yet.</p>';
    return;
  }
  grid.innerHTML = PHOTOS.map((p, i) => `
    <div class="photo" tabindex="0" style="background-image:url('${SAMPLE_PHOTO_URLS[i % SAMPLE_PHOTO_URLS.length]}');">
      <span class="photo-tag">${p.tags.join(', ')}</span>
    </div>
  `).join('');
}

function renderSocial() {
  const list = $('#socialList');
  if (SOCIAL.length === 0) {
    list.innerHTML = '<p class="empty"><i class="fa-solid fa-users"></i> No friends yet.</p>';
    return;
  }
  list.innerHTML = SOCIAL.map(s => `
    <div class="social-item" data-handle="${s.handle}" tabindex="0">
      <div class="avatar-sm" style="background: linear-gradient(135deg,#8b5cf6,#ec4899); color:#fff;">
        <i class="fa-solid fa-user"></i>
      </div>
      <div>
        <div class="name">${escapeHtml(s.name)}</div>
        <div class="handle">${escapeHtml(s.handle)}</div>
      </div>
      <span class="status ${s.status}">${s.status === 'online' ? 'Online' : 'Offline'}</span>
    </div>
  `).join('');
}

function renderMessages() {
  const list = $('#messageList');
  if (state.messages.length === 0) {
    list.innerHTML = '<p class="empty"><i class="fa-solid fa-envelope"></i> No messages yet.</p>';
    return;
  }
  list.innerHTML = state.messages.map(m => `
    <div class="message-item ${m.unread ? 'active' : ''}" data-id="${m.id}">
      <div class="avatar-sm" style="background: ${m.color}; color:#fff;">
        <i class="fa-solid fa-user"></i>
      </div>
      <div>
        <div class="name">${escapeHtml(m.sender)}</div>
        <div class="handle">${escapeHtml(m.handle)}</div>
      </div>
      <div class="message-meta">${escapeHtml(m.lastMessage)} · ${formatTime(m.time)}</div>
    </div>
  `).join('');
}

function renderInbox() {
  const conv = state.currentConversation;
  if (!conv) {
    $('#inboxTitle').textContent = 'Inbox';
    $('#inboxSubtitle').textContent = 'Select a conversation to chat.';
    $('#inboxBody').innerHTML = '';
    $('#inboxFooter').style.display = 'none';
    return;
  }
  $('#inboxTitle').textContent = `${conv.sender} · ${conv.handle}`;
  $('#inboxSubtitle').textContent = 'Last message';
  const body = $('#inboxBody');
  body.innerHTML = conv.messages.map(m => `
    <div class="message ${m.sender === 'me' ? 'me' : ''}">
      <div class="meta">${m.sender === 'me' ? 'You' : conv.sender} · ${formatTime(m.time)}</div>
      <div class="text">${escapeHtml(m.text)}</div>
    </div>
  `).join('');
  $('#inboxFooter').style.display = 'flex';
}

// ---------- Navigation ----------
function switchView(name) {
  state.view = name;
  $$('.sidebar-nav a').forEach(a => a.classList.toggle('active', a.dataset.view === name));
  $$('.view').forEach(v => v.classList.toggle('active', v.id === `view-${name}`));
  window.scrollTo({ top: 0, behavior: 'smooth' });
  if (name === 'messages') renderMessages();
  if (name === 'social') renderSocial();
}

// ---------- Modal ----------
function openModal(title, bodyId, submit) {
  $('#modalTitle').textContent = title;
  $('#modalBody').value = '';
  $('#modal').classList.remove('hidden');
  setTimeout(() => $('#modalBody').focus(), 100);
}
function closeModal() { $('#modal').classList.add('hidden'); }

// ---------- Login / Registration ----------
function openLogin() {
  $('#loginModal').classList.remove('hidden');
  $('#loginEmail').value = '';
  $('#loginPassword').value = '';
}
function closeLogin() { $('#loginModal').classList.add('hidden'); }
function openRegister() {
  $('#registerModal').classList.remove('hidden');
  $('#regName').value = '';
  $('#regEmail').value = '';
  $('#regPassword').value = '';
}
function closeRegister() { $('#registerModal').classList.add('hidden'); }

// ---------- Messages ----------
function selectConversation(id) {
  const conv = state.messages.find(m => m.id === id);
  if (!conv) return;
  state.currentConversation = conv;
  renderInbox();
  toast(`Chat with ${conv.sender}`, 'info');
}

function sendMessage(text) {
  if (!state.currentConversation || !text.trim()) return;
  const conv = state.currentConversation;
  const now = new Date();
  conv.messages.push({
    sender: 'me',
    text,
    time: now.toISOString(),
  });
  conv.unread = 0;
  renderInbox();
  toast('Message sent', 'success');
}

function sendModalMessage() {
  const text = $('#modalBody').value.trim();
  if (!text) return;
  if (!state.currentConversation) return;
  state.currentConversation.messages.push({
    sender: 'me',
    text,
    time: new Date().toISOString(),
  });
  closeModal();
  renderInbox();
  toast('Message sent', 'success');
}

// ---------- Theme ----------
function toggleTheme() {
  document.body.classList.toggle('dark');
  localStorage.setItem('lumen-theme', document.body.classList.contains('dark') ? 'dark' : 'light');
  toast('Theme toggled', 'info');
}

// ---------- Event wiring ----------
document.addEventListener('DOMContentLoaded', () => {
  // Theme
  const saved = localStorage.getItem('lumen-theme');
  if (saved === 'dark') document.body.classList.add('dark');
  $('#themeToggle').addEventListener('click', toggleTheme);

  // Nav
  $$('.sidebar-nav a').forEach(a => {
    a.addEventListener('click', e => {
      e.preventDefault();
      switchView(a.dataset.view);
    });
  });

  // Article pagination
  $('#articleList').addEventListener('click', e => {
    const prev = e.target.closest('.page-btn');
    if (prev) {
      e.preventDefault();
      const p = prev.dataset.page;
      if (p === 'prev') state.page = Math.max(1, state.page - 1);
      else if (p === 'next') state.page = Math.min(Math.ceil(ARTICLES.length / state.pageSize), state.page + 1);
      else state.page = Number(p);
      renderArticles();
    }
  });

  // Social click
  $('#socialList').addEventListener('click', e => {
    const item = e.target.closest('.social-item');
    if (item) {
      const handle = item.dataset.handle;
      toast(`Opening conversation with ${item.dataset.name}`, 'info');
    }
  });

  // Message click
  $('#messageList').addEventListener('click', e => {
    const item = e.target.closest('.message-item');
    if (item) selectConversation(Number(item.dataset.id));
  });

  // Inbox send
  $('#inboxFooter').addEventListener('click', e => {
    const input = $('#inboxInput');
    if (!input) return;
    const text = input.value.trim();
    if (!text) return;
    sendMessage(text);
    input.value = '';
  });

  // Modal
  $('#modalSend').addEventListener('click', sendModalMessage);
  $('#modalClose').addEventListener('click', closeModal);
  $('#modalCancel').addEventListener('click', closeModal);
  $('#modal').addEventListener('click', e => { if (e.target.id === 'modal') closeModal(); });

  // Login
  $('#loginBtn').addEventListener('click', openLogin);
  $('#loginClose').addEventListener('click', closeLogin);
  $('#goRegister').addEventListener('click', openRegister);
  $('#registerClose').addEventListener('click', closeRegister);
  $('#goLogin').addEventListener('click', openLogin);

  $('#loginSubmit').addEventListener('click', () => {
    const email = $('#loginEmail').value;
    const password = $('#loginPassword').value;
    if (!email || !password) { toast('Please fill in all fields', 'error'); return; }
    state.user = { email, name: email.split('@')[0] };
    closeLogin();
    toast('Welcome back, ' + state.user.name + '!', 'success');
  });

  $('#registerSubmit').addEventListener('click', () => {
    const name = $('#regName').value;
    const email = $('#regEmail').value;
    const password = $('#regPassword').value;
    if (!name || !email || !password) { toast('Please fill in all fields', 'error'); return; }
    state.user = { email, name };
    closeRegister();
    toast('Account created!', 'success');
  });

  // Keyboard: ESC closes modals
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      if (!$('#modal').classList.contains('hidden')) closeModal();
      if (!$('#loginModal').classList.contains('hidden')) closeLogin();
      if (!$('#registerModal').classList.contains('hidden')) closeRegister();
    }
  });

  // Init
  renderArticles();
  renderPhotos();
  renderSocial();
  renderMessages();
  renderInbox();
});
</script>
</body>
</html>
```

Here's a complete **online furniture shopping platform** implemented as a **single-page web application** using modern web technologies:

---

## ✅ Features

1. **Browse categories** of furniture (e.g., Sofa, Table, Lamp, Bed, Chair).
2. **Virtual room preview** with **drag-and-drop** furniture placement.
3. **Shopping cart** with combined purchase and total price calculation.
4. **User accounts** (localStorage-based).
5. **Save & share arrangement plans** via unique shareable links.
6. **Responsive design**.

---

## 📦 Tech Stack

- HTML5, CSS3, JavaScript (ES6+)
- Canvas for virtual room rendering (fallback: SVG)
- Drag-and-drop via `dataTransfer` and event delegation
- LocalStorage for persistence

