  padding: 32px;
}

.practice-card h3 {
  margin-bottom: 8px;
}

.practice-card p {
  margin: 0 0 24px;
  color: #475569;
}

.progression-form {
  display: grid;
  gap: 16px;
}

.progression-form label {
  display: block;
  font-weight: 600;
  font-size: 14px;
  margin-bottom: 6px;
  color: #1e293b;
}

.select, .chord-input {
  width: 100%;
  padding: 12px 14px;
  border: 2px solid #cbd5e1;
  border-radius: 12px;
  background: #fff;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.select:focus, .chord-input:focus {
  outline: none;
  border-color: #3a86ff;
  box-shadow: 0 0 0 4px rgba(58, 134, 255, 0.15);
}

.chord-row {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 12px;
}

.chord-row label {
  text-align: right;
}

.btn-primary {
  grid-column: 1 / -1;
  padding: 14px 24px;
  background: #3a86ff;
  color: #fff;
  border: none;
  border-radius: 12px;
  font-weight: 600;
  font-size: 16px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.btn-primary:hover {
  background: #2563eb;
}

.btn-primary:active {
  transform: translateY(1px);
}

.btn-primary:focus-visible {
  outline: 3px solid #1e3a8a;
  outline-offset: 2px;
}

/* ---------- Feedback ---------- */
.feedback {
  margin-top: 16px;
  padding: 14px 16px;
  border-radius: 12px;
  font-weight: 500;
  min-height: 28px;
  text-align: center;
}

.feedback.success {
  background: #dcfce7;
  color: #166534;
  border: 1px solid #86efac;
}

.feedback.error {
  background: #fee2e2;
  color: #991b1b;
  border: 1px solid #fecaca;
}

.feedback.info {
  background: #eff6ff;
  color: #1e40af;
  border: 1px solid #bfdbfe;
}

/* ---------- Footer ---------- */
.site-footer {
  text-align: center;
  padding: 24px 32px 40px;
  color: #94a3b8;
  font-size: 14px;
}

.site-footer p { margin: 0; }

/* ---------- Responsive ---------- */
@media (max-width: 720px) {
  .site-header {
    flex-direction: column;
    align-items: stretch;
    padding: 14px 16px;
    gap: 12px;
  }

  .brand h1 { font-size: 16px; }
  .tagline { font-size: 12px; }

  .top-nav {
    flex-wrap: wrap;
    gap: 6px;
  }
  .nav-link { padding: 8px 10px; font-size: 14px; }

  main { padding: 24px 16px 60px; }
  .section-head h2 { font-size: 24px; }
  .card { padding: 20px; }
  .card h3 { font-size: 18px; }
  .audio-btn { font-size: 14px; padding: 10px 12px; }

