    grid-template-columns: 1fr;
  }
  .chord-row label { text-align: left; }

  .practice-card { padding: 24px; }
}

@media (max-width: 420px) {
  .section { margin-bottom: 40px; }
  .section-head { margin-bottom: 24px; }
}
