      const notes = (data.notes || '').split(',').map(n => n.trim());
      const name = data.name || data.scale || data.chord || data.interval || 'Chord';

      let duration = 1.5;
      if (name.includes('Scale')) duration = 2;
      if (name.includes('Interval')) duration = 1.5;
      if (name.includes('Chord')) duration = 1.5;

      if (name.includes('Interval')) {
        playInterval(notes, duration, -10);
      } else if (name.includes('Scale')) {
        playScale(notes, duration, -10);
      } else if (name.includes('Chord')) {
        playChordSequence(notes, duration, -10);
      } else {
        playChord(notes, duration, -10);
      }

      setTimeout(() => { isPlaying = false; }, duration * 1000 + 500);
    });
  });

