      const bx = b.x + dx, by = b.y + dy;
      if (bx >= nb.x && bx <= nb.x + nb.w &&
          by >= nb.y && by <= nb.y + nb.h) {
        // Collision: bounce
        const nx = nb.x + nb.w / 2 - b.x;
        const ny = nb.y + nb.h / 2 - b.y;
        const len = Math.sqrt(nx*nx + ny*ny);
        if (len === 0) continue;
        const nxn = nx / len, nyn = ny / len;
        const dot = b.vx * nxn + b.vy * nyn;
        b.vx -= 2 * dot * nxn;
        b.vy -= 2 * dot * nyn;
        b.vx *= BOUNCE;
        b.vy *= BOUNCE;
        b.x = nb.x + nb.w / 2 - b.vx * dt;
        b.y = nb.y + nb.h / 2 - b.vy * dt;
        hit = true;
      }
    }
  }

  // Check wall collisions
  if (b.x < 0) { b.x = 0; b.vx = Math.abs(b.vx) * BOUNCE; }
  if (b.x + b.w > W) { b.x = W - b.w; b.vx = -Math.abs(b.vx) * BOUNCE; }
  if (b.y < 0) { b.y = 0; b.vy = Math.abs(b.vy) * BOUNCE; }
  if (b.y + b.h > H) { b.y = H - b.h; b.vy = -Math.abs(b.vy) * BOUNCE; }

  // Adhesion
  if (b.falling && !hit) {
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const nb = getBubbleAt(r, c);
        if (!nb) continue;
        const dx = nb.x + nb.w / 2 - b.x;
        const dy = nb.y + nb.h / 2 - b.y;
        const d = Math.sqrt(dx*dx + dy*dy);
        if (d < 22) {
          b.adhered = true;
          b.vx = 0; b.vy = 0;
          b.x = nb.x + nb.w / 2;
          b.y = nb.y + nb.h / 2;
          return;
        }
      }
    }
  }

  // Gravity pull toward matrix
  if (b.falling && !b.adhered) {
    let closest = null, closestDist = 9999;
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const nb = getBubbleAt(r, c);
        if (!nb) continue;
        const dx = nb.x + nb.w / 2 - b.x;
        const dy = nb.y + nb.h / 2 - b.y;
        const d = Math.sqrt(dx*dx + dy*dy);
        if (d < closestDist) {
          closestDist = d;
          closest = nb;
        }
      }
    }
    if (closest && closestDist < 40) {
      const nx = closest.x + closest.w / 2 - b.x;
      const ny = closest.y + closest.h / 2 - b.y;
      const len = Math.sqrt(nx*nx + ny*ny);
      if (len > 0) {
        b.vx -= nx / len * ADHESION;
        b.vy -= ny / len * ADHESION;
      }
    }
  }

  b.x += dx;
  b.y += dy;
  b.t += dt;
}

function updateBubbles(dt) {
  for (let i = 0; i < bubbles.length; i++) {
    const b = bubbles[i];
    if (!b.dead) {
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      b.vx *= FRICTION;
      b.vy += GRAVITY * dt;
      // Gravity toward matrix
      if (b.falling) {
        let closest = null, closestDist = 9999;
        for (let r = 0; r < ROWS; r++) {
          for (let c = 0; c < COLS; c++) {
            const nb = getBubbleAt(r, c);
            if (!nb) continue;
            const dx = nb.x + nb.w / 2 - b.x;
            const dy = nb.y + nb.h / 2 - b.y;
            const d = Math.sqrt(dx*dx + dy*dy);
            if (d < closestDist) {
              closestDist = d;
              closest = nb;
            }
          }
        }
        if (closest && closestDist < 40) {
          const nx = closest.x + closest.w / 2 - b.x;
          const ny = closest.y + closest.h / 2 - b.y;
          const len = Math.sqrt(nx*nx + ny*ny);
          if (len > 0) {
            b.vx -= nx / len * ADHESION;
            b.vy -= ny / len * ADHESION;
          }
        }
      }
      // Wall collisions
      if (b.x < 0) { b.x = 0; b.vx = Math.abs(b.vx) * BOUNCE; }
      if (b.x + b.w > W) { b.x = W - b.w; b.vx = -Math.abs(b.vx) * BOUNCE; }
      if (b.y < 0) { b.y = 0; b.vy = Math.abs(b.vy) * BOUNCE; }
      if (b.y + b.h > H) { b.y = H - b.h; b.vy = -Math.abs(b.vy) * BOUNCE; }
      // Adhesion
      if (b.falling && !b.adhered) {
        let closest = null, closestDist = 9999;
        for (let r = 0; r < ROWS; r++) {
          for (let c = 0; c < COLS; c++) {
            const nb = getBubbleAt(r, c);
            if (!nb) continue;
            const dx = nb.x + nb.w / 2 - b.x;
            const dy = nb.y + nb.h / 2 - b.y;
            const d = Math.sqrt(dx*dx + dy*dy);
            if (d < closestDist) {
              closestDist = d;
              closest = nb;
            }
          }
        }
        if (closest && closestDist < 22) {
          b.adhered = true;
          b.vx = 0; b.vy = 0;
          b.x = closest.x + closest.w / 2;
          b.y = closest.y + closest.h / 2;
        }
      }
    }
  }
}

function updateMatrix(dt) {
  // Drop bubbles down
  for (let c = 0; c < COLS; c++) {
    for (let r = ROWS - 1; r >= 0; r--) {
      const b = getBubbleAt(r, c);
      if (!b) continue;
      if (b.falling) {
        let newR = r;
        while (newR < ROWS - 1 && !getBubbleAt(newR + 1, c)) newR++;
        if (newR !== r) {
          b.r = newR;
          b.y = hexCenter(newR, c).y - HEX_H / 2;
        }
      }
    }
  }
}

function updateChain(dt) {
  chainTimer += dt;
  if (chainTimer >= chainDelay) {
    // Animate removal: fade out
    for (let i = 0; i < bubbles.length; i++) {
      const b = bubbles[i];
      if (b.dead && b.t < 1) {
        b.t += dt;
        b.alpha = 1 - b.t;
      }
    }
    chainTimer = 0;
  }
}

function drawHexagon(x, y, w, h, color, alpha = 1) {
  const cx = x + w / 2, cy = y + h / 2;
  const points = [
    cx - w / 2, cy - h / 2,
    cx + w / 2, cy - h / 2,
    cx + w / 2, cy + h / 2,
    cx - w / 2, cy + h / 2,
    cx - w / 2, cy - h / 2
  ];
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(points[0], points[1]);
  for (let i = 2; i < points.length; i += 2) {
    ctx.lineTo(points[i], points[i+1]);
  }
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawMatrix() {
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const b = getBubbleAt(r, c);
      if (!b) continue;
      drawHexagon(b.x, b.y, HEX_W, HEX_H, COLORS[b.color], b.alpha);
    }
  }
}

function drawCannon() {
  const cx = CANON_X + CANON_W / 2;
  const cy = CANON_Y + CANON_H / 2;
  // Base
  ctx.fillStyle = '#3a3a55';
  ctx.fillRect(CANON_X, CANON_BASE_Y, CANON_W, 8);
  // Barrel
  ctx.fillStyle = '#2a2a45';
  ctx.fillRect(CANON_X, CANON_Y, CANON_W, CANON_H);
  // Barrel tip
  ctx.fillStyle = '#1a1a35';
  ctx.fillRect(CANON_X + CANON_W / 2 - 4, CANON_Y + CANON_H / 2 - 4, 8, 8);
  // Barrel angle
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.lineTo(cx + Math.cos(cannonAngle) * 40, cy + Math.sin(cannonAngle) * 40);
  ctx.stroke();
}

function drawTrajectory() {
  if (!shotBubble) return;
  const b = shotBubble;
  if (b.dead || !b.falling) return;
  ctx.strokeStyle = '#ff8a8a';
  ctx.lineWidth = 2;
  ctx.setLineDash([6, 6]);
  ctx.beginPath();
  ctx.moveTo(b.x, b.y);
  const dx = b.vx * 0.5, dy = b.vy * 0.5;
  ctx.lineTo(b.x + dx, b.y + dy);
  ctx.stroke();
  ctx.setLineDash([]);
}

function drawShotBubble() {
  if (!shotBubble || shotBubble.dead) return;
  const b = shotBubble;
  const cx = b.x + HEX_W / 2, cy = b.y + HEX_H / 2;
  ctx.save();
  ctx.globalAlpha = b.alpha;
  ctx.fillStyle = COLORS[b.color];
  ctx.beginPath();
  ctx.moveTo(cx - HEX_W / 2, cy - HEX_H / 2);
  ctx.lineTo(cx + HEX_W / 2, cy - HEX_H / 2);
  ctx.lineTo(cx + HEX_W / 2, cy + HEX_H / 2);
  ctx.lineTo(cx - HEX_W / 2, cy + HEX_H / 2);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function render() {
  ctx.clearRect(0, 0, W, H);
  drawMatrix();
  drawCannon();
  drawShotBubble();
  drawTrajectory();
}

function loop(dt) {
  updateCannonPower();
  updateShotBubble(dt);
  updateBubbles(dt);
  updateMatrix(dt);
  updateChain(dt);
  render();
  if (cannonCooldown <= 0 && mouse.down) {
    shootBubble();
  }
  requestAnimationFrame(loop);
}

// Mouse
canvas.addEventListener('mousemove', (e) => {
  const rect = canvas.getBoundingClientRect();
  mouse.x = e.clientX - rect.left;
  mouse.y = e.clientY - rect.top;
  mouse.angle = Math.atan2(mouse.y - CANON_Y, mouse.x - CANON_X);
});
canvas.addEventListener('mousedown', (e) => {
  mouse.down = true;
});
canvas.addEventListener('mouseup', (e) => {
  mouse.down = false;
});

// Keyboard: space to shoot
window.addEventListener('keydown', (e) => {
  if (e.code === 'Space' && cannonCooldown <= 0) {
    shootBubble();
  }
});

// Init
spawnInitialMatrix();
shotBubble = new Bubble('red', { x: CANON_X + CANON_W / 2, y: CANON_Y + CANON_H / 2 });
requestAnimationFrame(loop);
</script>
</body>
</html>
```

---

### 📈 Game Loop

- `updateCannonPower()`: accumulates power when mouse held.
- `shootBubble()`: launches the bubble from the cannon.
- `updateShotBubble(dt)`: simulates trajectory, collisions, adhesion.
- `updateBubbles(dt)`: simulates all bubbles (gravity, collisions, adhesion).
- `updateMatrix(dt)`: drops bubbles down after removal.
- `updateChain(dt)`: fades out removed bubbles.
- `render()`: draws everything.

---

### 🧠 Physics Notes

- **Adhesion**: when a shot bubble gets within ~22px of a matrix bubble, it sticks.
- **Trajectory**: drawn as a dashed red line while shooting.
- **Chain reaction**: after elimination, any connected group of 3+ is removed and falls.

---

### 🎨 Visuals

- Hexagons drawn with 6-point polygons.
- Cannon barrel rotates with mouse.
- Shot bubble fades out on collision or adhesion.
- Score increases by 100 per chain.

