@app.route('/')
def index():
    return redirect(url_for('customer_menu'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    form = LoginForm()
    if form.validate_on_submit():
        user = User.query.filter_by(username=form.username.data).first()
        if user and user.check_password(form.password.data) and user.is_active:
            login_user(user)
            flash('Welcome back!', 'success')
            return redirect(url_for('customer_menu'))
        flash('Invalid credentials. Please try again.', 'error')
    return render_template('login.html', form=form)

@app.route('/logout')
@login_required
def logout():
    logout_user()
    flash('You have been logged out.', 'info')
    return redirect(url_for('login'))

@app.route('/register', methods=['GET', 'POST'])
def register():
    form = UserRegistrationForm()
    if request.method == 'POST' and form.validate_on_submit():
        # Fetch role choices from DB
        roles = Role.query.all()
        form.role.choices = [(r.id, r.name) for r in roles]
        if not form.role.data:
            flash('Please select a role.', 'error')
            return render_template('register.html', form=form)

        existing = User.query.filter_by(username=form.username.data).first()
        if existing:
            flash('Username already taken.', 'error')
            return render_template('register.html', form=form)

        user = User(username=form.username.data, email=form.email.data, role_id=form.role.data)
        user.set_password(form.password.data)
        db.session.add(user)
        db.session.commit()
        flash('Account created successfully. Please login.', 'success')
        return redirect(url_for('login'))
    return render_template('register.html', form=form)

@app.route('/chef-upload', methods=['GET', 'POST'])
@login_required
def chef_upload():
    if not current_user.role.name.lower() in ['chef', 'admin']:
        flash('You do not have permission to upload menus.', 'error')
        return redirect(url_for('customer_menu'))
    form = MenuForm()
    categories = get_categories()
    form.category.choices = [(c.id, c.name) for c in categories.values()]

    if request.method == 'POST' and form.validate():
        file = request.files.get('image')
        title = form.title.data.strip()
        description = form.description.data.strip()
        category_id = form.category.data

        if not file or not allowed_file(file.filename):
            flash('Please upload a valid image file.', 'error')
            return render_template('chef_upload.html', form=form, categories=categories)

        filename = generate_filename(file.filename)
        file_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
        file.save(file_path)

        menu = Menu(
            title=title,
            description=description,
            category_id=category_id,
            image_file=filename,
            status='pending',
            uploaded_by_id=current_user.id
        )
        db.session.add(menu)
        db.session.commit()

        flash(f'Menu "{title}" submitted for review.', 'success')
        return redirect(url_for('chef_upload'))

    return render_template('chef_upload.html', form=form, categories=categories)

