    categories = get_categories()
    menus = {}
    for cid, cat in categories.items():
        menus[cid] = Menu.query.filter_by(category_id=cid, status='approved').all()
    return render_template('customer_menu.html', categories=categories, menus=menus)

@app.route('/uploads/<filename>')
def uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

# ----------------------------
# ADMIN (optional) - create default roles/users
# ----------------------------

@app.before_first_request
def create_default_data():
    # Roles
    roles = ['Chef', 'Manager', 'Admin']
    for r in roles:
        role = Role.query.filter_by(name=r).first()
        if not role:
            db.session.add(Role(name=r, description=f'{r} role'))
    db.session.commit()

    # Default admin user
    admin = User.query.filter_by(username='admin').first()
    if not admin:
        admin = User(username='admin', email='admin@chef.com', role_id=3, is_active=True)
        admin.set_password('admin123')
        db.session.add(admin)
        db.session.commit()

    # Default categories
    categories = ['Appetizers', 'Main Course', 'Desserts', 'Drinks']
    for c in categories:
        cat = MenuCategory.query.filter_by(name=c).first()
        if not cat:
            db.session.add(MenuCategory(name=c, description=f'{c} category'))
    db.session.commit()

# ----------------------------
# ERROR HANDLERS
# ----------------------------

@app.errorhandler(404)
def page_not_found(e):
    return render_template('404.html'), 404

@app.errorhandler(500)
def internal_error(e):
    db.session.rollback()
    return render_template('500.html'), 500

# ----------------------------
# RUN
# ----------------------------

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
        create_default_data()
    app.run(debug=True)
