    --radius-sm: 6px;
    --radius: 10px;
    --radius-lg: 14px;
    --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.06);
    --shadow: 0 4px 12px rgba(15, 23, 42, 0.08);
    --shadow-lg: 0 12px 32px rgba(15, 23, 42, 0.12);
  }

  * { box-sizing: border-box; }

  html, body {
    margin: 0;
    padding: 0;
    height: 100%;
  }

  body {
    font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    font-size: 14px;
    line-height: 1.5;
    color: var(--text);
    background: var(--bg);
    -webkit-font-smoothing: antialiased;
  }

  .app {
    display: grid;
    grid-template-columns: 280px 1fr;
    min-height: 100vh;
  }

  /* Sidebar */
  .sidebar {
    background: var(--surface);
    border-right: 1px solid var(--border);
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 16px;
    position: sticky;
    top: 0;
    height: 100vh;
  }

  .sidebar h2 {
    font-size: 14px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--text-muted);
    margin: 0 0 12px;
  }

  .sidebar .section {
    padding: 12px 14px;
    background: var(--primary-50);
    border-radius: var(--radius);
    border: 1px solid transparent;
    transition: border-color 0.2s, background 0.2s;
  }

  .sidebar .section:hover {
    border-color: var(--border);
    background: #fff;
  }

  .sidebar .section.active {
    border-color: var(--primary);
    background: #fff;
  }

  .sidebar .section-label {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
    font-weight: 500;
    color: var(--text);
  }

  .sidebar .section-icon {
    width: 18px;
    height: 18px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 6px;
    background: var(--primary);
    color: #fff;
  }

  .sidebar .section-count {
    font-size: 12px;
    color: var(--text-muted);
    font-weight: 500;
  }

  .sidebar .section-count.active {
    color: var(--primary);
  }

  .sidebar .section-content {
    margin-top: 4px;
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  .sidebar .section-content button {
    width: 100%;
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 10px;
    border: 1px solid transparent;
    border-radius: var(--radius-sm);
    font-size: 13px;
    font-weight: 500;
    color: var(--text);
    background: transparent;
    transition: all 0.2s;
  }

  .sidebar .section-content button:hover {
    background: var(--primary-50);
    border-color: var(--border);
  }

  .sidebar .section-content button.active {
    background: var(--primary);
    color: #fff;
    border-color: var(--primary);
  }

  .sidebar .section-content button i {
    font-size: 12px;
  }

  .sidebar .section-content button.active i {
    color: #fff;
  }

  .sidebar .section-content button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }

  .sidebar .section-content button:disabled i {
    color: var(--text-muted);
  }

  .sidebar .section-content button.active:disabled {
    background: #e2e8f0;
  }

  .sidebar .section-content button.active:disabled i {
    color: var(--text-muted);
  }

  .sidebar .section-content button.active:disabled:hover {
    background: #e2e8f0;
  }

  .sidebar .section-content button.active:disabled:hover i {
    color: var(--text-muted);
  }

  /* Main */
  .main {
    padding: 24px;
    display: flex;
    flex-direction: column;
    gap: 20px;
    overflow: hidden;
  }

  .header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    flex-wrap: wrap;
  }

  .header h1 {
    margin: 0;
    font-size: 22px;
    font-weight: 700;
    color: var(--text);
  }

  .header .badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    background: var(--primary-50);
    color: var(--primary);
    border-radius: 999px;
    font-size: 12px;
    font-weight: 600;
  }

  .header .badge i {
    font-size: 11px;
  }

  .upload-area {
    border: 2px dashed var(--border);
    border-radius: var(--radius-lg);
    padding: 32px 24px;
    text-align: center;
    cursor: pointer;
    transition: all 0.2s;
    background: var(--surface);
  }

  .upload-area:hover {
    border-color: var(--primary);
    background: var(--primary-50);
  }

  .upload-area.dragover {
    border-color: var(--primary);
    background: var(--primary-50);
    transform: scale(1.01);
  }

  .upload-area i {
    font-size: 48px;
    color: var(--primary);
    margin-bottom: 12px;
  }

  .upload-area h3 {
    margin: 0 0 6px;
    font-size: 16px;
    font-weight: 600;
  }

  .upload-area p {
    margin: 0;
    color: var(--text-muted);
    font-size: 13px;
  }

  .upload-area .btn {
    padding: 10px 20px;
    background: var(--primary);
    color: #fff;
    border: none;
    border-radius: var(--radius-sm);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
  }

  .upload-area .btn:hover {
    background: var(--primary-600);
  }

  .upload-area .btn:disabled {
    background: #cbd5e1;
    cursor: not-allowed;
  }

  .file-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .file-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    transition: all 0.2s;
  }

  .file-item:hover {
    border-color: var(--primary);
    box-shadow: var(--shadow-sm);
  }

  .file-thumb {
    width: 56px;
    height: 56px;
    border-radius: 8px;
    background: #e2e8f0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-muted);
    font-size: 22px;
    font-weight: 600;
    flex-shrink: 0;
  }

  .file-info {
    flex: 1;
    min-width: 0;
  }

  .file-name {
    font-size: 14px;
    font-weight: 500;
    color: var(--text);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .file-size {
    font-size: 12px;
    color: var(--text-muted);
  }

  .file-actions {
    display: flex;
    gap: 4px;
  }

  .file-actions button {
    width: 28px;
    height: 28px;
    border: none;
    background: transparent;
    border-radius: 6px;
    color: var(--text-muted);
    cursor: pointer;
    transition: all 0.2s;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .file-actions button:hover {
    background: var(--primary-50);
    color: var(--primary);
  }

  .file-actions button.danger:hover {
    background: #fee2e2;
    color: var(--danger);
  }

  .canvas-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 16px;
    box-shadow: var(--shadow);
  }

  .canvas-container .canvas {
    background: #eef2ff;
    border-radius: var(--radius);
    min-height: 320px;
    position: relative;
    overflow: hidden;
  }

  .canvas-container .canvas canvas {
    width: 100%;
    height: 100%;
    display: block;
  }

  .canvas-container .canvas .canvas-wrap {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  .canvas-container .canvas .canvas-wrap canvas {
    pointer-events: auto;
  }

  .canvas-container .canvas .canvas-wrap .canvas-canvas {
    position: absolute;
    top: 0;
    left: 0;
    pointer-events: none;
  }

  .canvas-container .canvas .canvas-wrap .canvas-canvas canvas {
    pointer-events: auto;
  }

