## 🧠 script.js

```javascript
(() => {
  'use strict';

  const $ = (id) => document.getElementById(id);
  const fileInput = $('fileInput');
  const dropzone = $('dropzone');
  const fileInfo = $('fileInfo');
  const fileNameEl = $('fileName');
  const fileDurationEl = $('fileDuration');
  const fileResEl = $('fileRes');
  const tlTrack = $('tlTrack');
  const tlPlayhead = $('tlPlayhead');
  const tlSeek = $('tlSeek');
  const tlTime = $('tlTime');
  const playBtn = $('playBtn');
  const addBtn = $('addBtn');
  const removeBtn = $('removeBtn');
  const subtitleList = $('subtitleList');
  const fontFamily = $('fontFamily');
  const fontSize = $('fontSize');
  const color = $('color');
  const bgColor = $('bgColor');
  const bgOpacity = $('bgOpacity');
  const bgOpacityVal = $('bgOpacityVal');
  const position = $('position');
  const exportBtn = $('exportBtn');
  const progress = $('progress');
  const progressBar = $('progressBar');
  const progressText = $('progressText');

  const state = {
    video: null,
    duration: 0,
    currentTime: 0,
    subtitles: [],
    activeIndex: -1,
    ffmpeg: null,
    worker: null,
  };

  // ---------- File handling ----------
  const handleFile = (file) => {
    if (!file) return;
    const url = URL.createObjectURL(file);
    const video = document.createElement('video');
    video.src = url;
    video.controls = false;
    video.muted = true;
    video.playsInline = true;
    video.addEventListener('loadedmetadata', () => {
      state.video = video;
      state.duration = video.duration;
      state.currentTime = 0;
      renderFileInfo();
      renderTimeline();
      renderSubtitles();
      playBtn.addEventListener('click', () => togglePlay());
      tlSeek.addEventListener('input', () => seekTo(parseFloat(tlSeek.value)));
      tlSeek.addEventListener('mousedown', (e) => {
        e.preventDefault();
        tlSeek.setPointerCapture(e.pointerId);
      });
      tlSeek.addEventListener('mouseup', () => tlSeek.releasePointerCapture(tlSeek));
      tlSeek.addEventListener('pointerleave', () => tlSeek.releasePointerCapture(tlSeek));
      tlSeek.addEventListener('pointerupoutside', () => tlSeek.releasePointerCapture(tlSeek));
      window.addEventListener('resize', () => renderTimeline());
      window.addEventListener('resize', () => renderSubtitles());
      window.addEventListener('resize', () => renderFileInfo());
    });
    $('body').appendChild(video);
  };

  const renderFileInfo = () => {
    if (!state.video) return;
    const d = state.video.duration;
    fileNameEl.textContent = state.video.src.split('/').pop();
    fileDurationEl.textContent = formatTime(d);
    fileResEl.textContent = `${state.video.videoWidth} × ${state.video.videoHeight}`;
  };

  const formatTime = (s) => {
    if (!isFinite(s)) return '—';
    const m = Math.floor(s / 60);
    const sec = Math.floor(s % 60).toString().padStart(2, '0');
    return `${m}:${sec}`;
  };

  // ---------- Timeline ----------
  const renderTimeline = () => {
    tlTrack.style.height = `${state.duration * 4}px`;
    tlPlayhead.style.left = '0%';
    tlTime.textContent = formatTime(state.currentTime);
  };

  const seekTo = (pct) => {
    if (!state.video) return;
    const t = state.duration * (pct / 100);
    state.currentTime = t;
    state.video.currentTime = t;
    tlPlayhead.style.left = `${pct}%`;
    tlTime.textContent = formatTime(t);
  };

  const togglePlay = () => {
    if (!state.video) return;
    if (state.video.paused) state.video.play();
    else state.video.pause();
  };

  // ---------- Subtitles ----------
  const renderSubtitles = () => {
    subtitleList.innerHTML = '';
    state.subtitles.forEach((s, i) => {
      const el = document.createElement('div');
      el.className = 'subtitle-item' + (i === state.activeIndex ? ' active' : '');
      el.dataset.index = i;
      el.innerHTML = `
        <span class="time">${formatTime(s.start)} → ${formatTime(s.end)}</span>
        <span class="text">${escapeHtml(s.text)}</span>
      `;
      el.addEventListener('click', () => selectSubtitle(i));
      subtitleList.appendChild(el);
    });
  };

  const escapeHtml = (s) =>
    String(s).replace(/[&<>"']/g, (c) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));

  const addSubtitle = () => {
    const start = state.currentTime || 0;
    const end = start + 3; // 3s default
    state.subtitles.push({ start, end, text: '', fontFamily: fontFamily.value, fontSize: fontSize.value, color: color.value, bgColor: bgColor.value, opacity: parseFloat(bgOpacity.value) / 100, position: position.value });
    renderSubtitles();
    selectSubtitle(state.subtitles.length - 1);
  };

  const selectSubtitle = (i) => {
    state.activeIndex = i;
    renderSubtitles();
    updateRemoveBtn();
  };

  const updateRemoveBtn = () => {
    removeBtn.disabled = state.activeIndex < 0 || state.activeIndex >= state.subtitles.length;
  };

  const removeSubtitle = () => {
    if (state.activeIndex < 0) return;
    state.subtitles.splice(state.activeIndex, 1);
    if (state.activeIndex >= state.subtitles.length) state.activeIndex = state.subtitles.length - 1;
    renderSubtitles();
    updateRemoveBtn();
  };

  // ---------- Drag to add subtitles ----------
  const onDragStart = (e) => {
    e.preventDefault();
    tlTrack.classList.add('dragging');
    tlTrack.dataset.dragStart = e.clientX;
  };
  const onDragMove = (e) => {
    if (!tlTrack.dataset.dragStart) return;
    const startX = parseFloat(tlTrack.dataset.dragStart);
    const dx = e.clientX - startX;
    const pct = Math.max(0, Math.min(100, (dx / state.duration) * 100));
    tlPlayhead.style.left = `${pct}%`;
    tlTime.textContent = formatTime(state.duration * (pct / 100));
  };
  const onDragEnd = (e) => {
    tlTrack.classList.remove('dragging');
    tlTrack.dataset.dragStart = null;
    const pct = parseFloat(tlPlayhead.style.left.replace('%', ''));
    const start = state.duration * (pct / 100);
    const end = start + 3;
    state.subtitles.push({ start, end, text: '', fontFamily: fontFamily.value, fontSize: fontSize.value, color: color.value, bgColor: bgColor.value, opacity: parseFloat(bgOpacity.value) / 100, position: position.value });
    renderSubtitles();
    selectSubtitle(state.subtitles.length - 1);
  };

  tlTrack.addEventListener('pointerdown', onDragStart);
  window.addEventListener('pointermove', onDragMove);
  window.addEventListener('pointerup', onDragEnd);
  window.addEventListener('pointercancel', onDragEnd);

  // ---------- Export ----------
  const buildWebVTT = () => {
    const cues = [];
    state.subtitles.forEach((s) => {
      const startSec = s.start;
      const endSec = s.end;
      const startMs = Math.round(startSec * 1000);
      const endMs = Math.round(endSec * 1000);
      const startLine = `${startMs.toString().padStart(6, '0')},000`;
      const endLine = `${endMs.toString().padStart(6, '0')},000`;
      cues.push({ start: startSec, end: endSec, text: s.text, startLine, endLine });
    });
    cues.sort((a, b) => a.start - b.start);
    const header = `WEBVTT\n\n`;
    const body = cues.map((c) => `${c.startLine} --> ${c.endLine}\n${escapeHtml(c.text)}\n`).join('');
    return header + body;
  };

  const exportVideo = async () => {
    if (!state.video || state.subtitles.length === 0) return;
    progress.hidden = false;
    progressBar.style.width = '0%';
    progressText.textContent = 'Preparing export...';

    try {
      const ffmpegPath = require('ffmpeg-static').path;
      const ffmpeg = require('fluent-ffmpeg');
      const ffprobe = require('fluent-ffmpeg');
      const ffprobePath = require('ffprobe-static').path;

      state.ffmpeg = ffmpeg;
      state.worker = null;

      const input = state.video.src;
      const output = 'output.mp4';
      const vtt = buildWebVTT();
      const vttFile = 'subtitles.vtt';

      // Write VTT file
      const vttBlob = new Blob([vtt], { type: 'text/vtt' });
      const vttUrl = URL.createObjectURL(vttBlob);
      const vttFileBlob = new File([vtt], vttFile, { type: 'text/vtt' });
      const vttFileUrl = URL.createObjectURL(vttFileBlob);

      const tempDir = 'temp';
      const tempVtt = `${tempDir}/${vttFile}`;
      const tempOutput = `${tempDir}/output.mp4`;
      const tempSubs = `${tempDir}/subtitles.vtt`;

      await new Promise((resolve) => {
        const writer = fs.createWriteStream(tempVtt);
        writer.write(vtt);
        writer.end(() => resolve());
      });

      const cmd = [
        '-i', input,
        '-i', tempVtt,
        '-c', 'copy',
        '-map', '0:v:0',
        '-map', '1:s:0',
        '-c:s', 'webvtt',
        '-map', '1:s:0',
        '-c:s', 'webvtt',
        '-y',
        tempOutput,
      ];

      const proc = state.ffmpeg(cmd);

      proc.on('start', () => {
        progressText.textContent = 'Encoding with FFmpeg...';
      });

      proc.on('progress', (p) => {
        progressBar.style.width = `${Math.min(100, p.percent)}%`;
        progressText.textContent = `Encoding... ${p.percent.toFixed(0)}%`;
      });

      proc.on('end', () => {
        progressBar.style.width = '100%';
        progressText.textContent = 'Export complete!';
        setTimeout(() => {
          progress.hidden = true;
          progressBar.style.width = '0%';
          progressText.textContent = 'Ready';
        }, 1500);
        alert('Export complete! Check your downloads folder.');
      });

      proc.on('error', (err) => {
        progressBar.style.width = '0%';
        progressText.textContent = 'Export failed: ' + err.message;
        setTimeout(() => {
          progress.hidden = true;
          progressBar.style.width = '0%';
          progressText.textContent = 'Ready';
        }, 1500);
      });

      await new Promise((resolve) => proc.on('end', resolve));

      // Clean up
      fs.unlinkSync(tempVtt);
      fs.unlinkSync(tempOutput);
      fs.unlinkSync(tempSubs);
      URL.revokeObjectURL(vttUrl);
      URL.revokeObjectURL(vttFileUrl);
    } catch (err) {
      console.error(err);
      progressBar.style.width = '0%';
      progressText.textContent = 'Export failed: ' + err.message;
      setTimeout(() => {
        progress.hidden = true;
        progressBar.style.width = '0%';
        progressText.textContent = 'Ready';
      }, 1500);
    }
  };

  // ---------- Dropzone ----------
  const setupDropzone = () => {
    ['dragenter', 'dragover'].forEach((ev) => {
      dropzone.addEventListener(ev, (e) => {
        e.preventDefault();
        e.stopPropagation();
        dropzone.classList.add('drag');
      });
    });
    ['dragleave', 'drop'].forEach((ev) => {
      dropzone.addEventListener(ev, (e) => {
        e.preventDefault();
        e.stopPropagation();
        dropzone.classList.remove('drag');
      });
    });
    dropzone.addEventListener('drop', (e) => {
      const file = e.dataTransfer.files && e.dataTransfer.files[0];
      if (file) handleFile(file);
    });
    fileInput.addEventListener('change', (e) => {
      const file = e.target.files && e.target.files[0];
      if (file) handleFile(file);
    });
    dropzone.addEventListener('click', () => fileInput.click());
  };

  // ---------- Init ----------
  setupDropzone();
  addBtn.addEventListener('click', addSubtitle);
  removeBtn.addEventListener('click', removeSubtitle);
  exportBtn.addEventListener('click', exportVideo);
})();
