    grid-template-columns: 1fr 1fr;
    gap: 16px;
  }
  .form-row .full { grid-column: 1 / -1; }
  .field {
    margin-bottom: 16px;
  }
  .field label {
    display: block;
    font-size: 13px;
    font-weight: 600;
    margin-bottom: 8px;
    color: #fff;
    letter-spacing: 0.2px;
  }
  .field input[type="text"],
  .field input[type="range"],
  .field select {
    width: 100%;
    padding: 10px 12px;
    border-radius: 10px;
    border: 1px solid rgba(255,255,255,0.2);
    background: rgba(255,255,255,0.1);
    color: #fff;
    font-size: 14px;
    font-family: inherit;
    transition: border-color 0.2s, background 0.2s;
  }
  .field input[type="text"]:hover,
  .field input[type="range"]:hover,
  .field select:hover {
    border-color: rgba(255,255,255,0.4);
  }
  .field input[type="text"]:focus,
  .field input[type="range"]:focus,
  .field select:focus {
    outline: none;
    border-color: #fff;
    background: rgba(255,255,255,0.2);
  }
  .field input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    height: 4px;
    background: rgba(255,255,255,0.2);
    border-radius: 999px;
    outline: none;
  }
  .field input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: #fff;
    cursor: pointer;
    border: 2px solid rgba(0,0,0,0.3);
    box-shadow: 0 2px 6px rgba(0,0,0,0.3);
  }
  .field input[type="range"]::-moz-range-thumb {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: #fff;
    cursor: pointer;
    border: 2px solid rgba(0,0,0,0.3);
  }
  .btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 12px 20px;
    border-radius: 12px;
    border: 1px solid transparent;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.2s, background 0.2s, border-color 0.2s, opacity 0.2s;
  }
  .btn-primary {
    background: #fff;
    color: #1a237e;
    border-color: #fff;
  }
  .btn-primary:hover { background: #fff; transform: translateY(-1px); }
  .btn-primary:active { transform: translateY(0); }
  .btn-primary:disabled {
    background: rgba(255,255,255,0.15);
    border-color: rgba(255,255,255,0.2);
    cursor: not-allowed;
    opacity: 0.7;
  }
  .btn-secondary {
    background: transparent;
    color: #fff;
    border-color: rgba(255,255,255,0.3);
  }
  .btn-secondary:hover { background: rgba(255,255,255,0.15); }
  .btn-danger {
    background: #ff4d4d;
    color: #fff;
    border-color: #ff4d4d;
  }
  .btn-danger:hover { background: #ff6b6b; }
  .btn-danger:disabled { opacity: 0.6; cursor: not-allowed; }
  .progress {
    margin-top: 16px;
    height: 6px;
    background: rgba(255,255,255,0.15);
    border-radius: 999px;
    overflow: hidden;
  }
  .progress-bar {
    height: 100%;
    width: 0%;
    background: linear-gradient(90deg, #fff, #ff9500);
    border-radius: 999px;
    transition: width 0.3s ease;
  }
  .status {
    margin-top: 12px;
    font-size: 13px;
    color: #fff;
    min-height: 18px;
  }
  .status.success { color: #4ade80; }
  .status.error { color: #f87171; }
  .watermark-text {
    margin-top: 16px;
    padding: 12px;
    background: rgba(255,255,255,0.1);
    border: 1px dashed rgba(255,255,255,0.3);
    border-radius: 10px;
    font-family: 'Courier New', monospace;
    font-size: 13px;
    color: #fff;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .watermark-text strong { color: #fff; }
  .watermark-text em { color: #ff9500; }
  .watermark-text small { color: #b9c6ff; }

  /* Toast */
  .toast {
    position: fixed;
    bottom: 24px;
    left: 50%;
    transform: translateX(-50%) translateY(20px);
    background: rgba(17, 24, 70, 0.95);
    color: #fff;
    padding: 12px 18px;
    border-radius: 12px;
    font-size: 14px;
    font-weight: 500;
    box-shadow: 0 10px 30px rgba(0,0,0,0.3);
    opacity: 0;
    transition: opacity 0.3s, transform 0.3s;
    z-index: 1000;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .toast.show {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
  .toast.success { color: #4ade80; }
  .toast.error { color: #f87171; }
  .toast i { font-size: 16px; }

  /* File preview */
  .file-preview {
    margin-top: 16px;
    padding: 14px;
    background: rgba(255,255,255,0.08);
    border: 1px dashed rgba(255,255,255,0.2);
    border-radius: 12px;
    text-align: center;
  }
  .file-preview i { font-size: 40px; margin-bottom: 8px; }
  .file-preview strong { display: block; font-size: 13px; margin-bottom: 2px; }
  .file-preview small { color: #b9c6ff; font-size: 12px; }

  @media (max-width: 560px) {
    .card { padding: 20px; border-radius: 14px; }
    .form-row { grid-template-columns: 1fr; }
    h1 { font-size: 22px; }
  }
</style>
</head>
<body>
  <div class="card">
    <h1><i class="fa-solid fa-waveform-lines"></i> Audio Watermark Creator</h1>
    <p class="subtitle">Upload an audio file and add a watermark text to protect your content.</p>

    <div class="field">
      <label for="fileInput">Upload Audio File</label>
      <input type="file" id="fileInput" accept="audio/*" />
    </div>

    <div class="field">
      <label for="watermarkText">Watermark Text</label>
      <input type="text" id="watermarkText" placeholder="e.g. © 2025 YourBrand" value="© 2025 YourBrand" />
    </div>

    <div class="form-row">
      <div class="field">
        <label for="watermarkPlacement">Placement</label>
        <select id="watermarkPlacement">
          <option value="beginning">Beginning</option>
          <option value="middle">Middle</option>
          <option value="end">End</option>
        </select>
      </div>
      <div class="field">
        <label for="volumeSlider">Volume (%)</label>
        <input type="range" id="volumeSlider" min="0" max="100" value="30" />
        <div class="range-value"><span id="volumeValue">30%</span></div>
      </div>
    </div>

    <div class="field">
      <label for="frequencySlider">Frequency (Hz) <small>how often the watermark repeats</small></label>
      <input type="range" id="frequencySlider" min="50" max="500" value="200" />
      <div class="range-value"><span id="frequencyValue">200 Hz</span></div>
    </div>

    <div class="field">
      <label for="durationSlider">Duration (seconds) <small>how long the watermark plays</small></label>
      <input type="range" id="durationSlider" min="0.5" max="60" step="0.5" value="3" />
      <div class="range-value"><span id="durationValue">3.0 s</span></div>
    </div>

    <div class="field">
      <label for="formatSelect">Output Format</label>
      <select id="formatSelect">
        <option value="mp3">MP3</option>
        <option value="wav">WAV</option>
      </select>
    </div>

    <div class="field">
      <label>Preview</label>
      <div class="file-preview" id="filePreview" hidden>
        <i class="fa-solid fa-file-audio"></i>
        <strong id="fileName">audio.mp3</strong>
        <small id="fileSize">0 KB</small>
      </div>
    </div>

    <div class="watermark-text" id="watermarkTextDisplay">
      <strong>Watermark:</strong> <em id="watermarkTextDisplayText">© 2025 YourBrand</em> <small>— Volume: 30%, Frequency: 200 Hz</small>
    </div>

    <div class="form-row">
      <button class="btn btn-secondary" id="clearBtn" title="Clear">
        <i class="fa-solid fa-rotate-left"></i> Clear
      </button>
      <button class="btn btn-primary" id="processBtn" disabled>
        <i class="fa-solid fa-play"></i> Process Watermark
      </button>
      <button class="btn btn-danger" id="cancelBtn" disabled>
        <i class="fa-solid fa-xmark"></i> Cancel
      </button>
    </div>

    <div class="progress" id="progressBar" hidden>
      <div class="progress-bar" id="progressBarFill"></div>
    </div>
    <div class="status" id="statusText"></div>
  </div>

  <div class="toast" id="toast" role="status" aria-live="polite">
    <i class="fa-solid fa-circle-check"></i>
    <span id="toastMsg">Ready</span>
  </div>

  <script src="https://cdn.jsdelivr.net/npm/@ffmpeg/ffmpeg@0.11.2/dist/ffmpeg.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/@ffmpeg/core@0.11.2/dist/ffmpeg-core.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/@ffmpeg/util@0.11.2/dist/util.min.js"></script>

  <script>
    const fileInput = document.getElementById('fileInput');
    const watermarkText = document.getElementById('watermarkText');
    const watermarkPlacement = document.getElementById('watermarkPlacement');
    const volumeSlider = document.getElementById('volumeSlider');
    const volumeValue = document.getElementById('volumeValue');
    const frequencySlider = document.getElementById('frequencySlider');
    const frequencyValue = document.getElementById('frequencyValue');
    const durationSlider = document.getElementById('durationSlider');
    const durationValue = document.getElementById('durationValue');
    const formatSelect = document.getElementById('formatSelect');
    const filePreview = document.getElementById('filePreview');
    const fileNameEl = document.getElementById('fileName');
    const fileSizeEl = document.getElementById('fileSize');
    const watermarkTextDisplayText = document.getElementById('watermarkTextDisplayText');
    const processBtn = document.getElementById('processBtn');
    const cancelBtn = document.getElementById('cancelBtn');
    const clearBtn = document.getElementById('clearBtn');
    const progressBar = document.getElementById('progressBar');
    const progressBarFill = document.getElementById('progressBarFill');
    const statusText = document.getElementById('statusText');
    const toast = document.getElementById('toast');
    const toastMsg = document.getElementById('toastMsg');

    let currentFile = null;
    let ffmpeg = null;
    let worker = null;
    let isProcessing = false;

    function formatBytes(bytes) {
      if (bytes < 1024) return bytes + ' B';
      if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
      return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
    }

    function updatePreview() {
      if (!currentFile) return;
      fileNameEl.textContent = currentFile.name;
      fileSizeEl.textContent = formatBytes(currentFile.size);
      filePreview.hidden = false;
    }

    function updateWatermarkDisplay() {
      const text = watermarkText.value.trim() || '© 2025 YourBrand';
      watermarkTextDisplayText.textContent = text;
      watermarkTextDisplayText.parentElement.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }

    function updateVolumeDisplay() {
      const v = volumeSlider.value;
      volumeValue.textContent = v + '%';
    }

    function updateFrequencyDisplay() {
      const f = frequencySlider.value;
      frequencyValue.textContent = f + ' Hz';
    }

    function updateDurationDisplay() {
      const d = durationSlider.value;
      durationValue.textContent = d.toFixed(1) + ' s';
    }

    fileInput.addEventListener('change', (e) => {
      const file = e.target.files[0];
      if (!file) return;
      if (!file.type.startsWith('audio/')) {
        showToast('error', 'Please upload an audio file.', 'error');
        fileInput.value = '';
        return;
      }
      currentFile = file;
      updatePreview();
      updateWatermarkDisplay();
      updateVolumeDisplay();
      updateFrequencyDisplay();
      updateDurationDisplay();
      processBtn.disabled = false;
      cancelBtn.disabled = false;
    });

    watermarkText.addEventListener('input', updateWatermarkDisplay);

    volumeSlider.addEventListener('input', updateVolumeDisplay);
    frequencySlider.addEventListener('input', updateFrequencyDisplay);
    durationSlider.addEventListener('input', updateDurationDisplay);

    processBtn.addEventListener('click', async () => {
      if (!currentFile) {
        showToast('error', 'Please upload an audio file first.', 'error');
        return;
      }
      if (isProcessing) return;
      isProcessing = true;
      processBtn.disabled = true;
      cancelBtn.disabled = true;
      clearBtn.disabled = true;
      fileInput.disabled = true;
      watermarkText.disabled = true;
      watermarkPlacement.disabled = true;
      volumeSlider.disabled = true;
      frequencySlider.disabled = true;
      durationSlider.disabled = true;
      formatSelect.disabled = true;

      progressBar.hidden = false;
      progressBarFill.style.width = '0%';
      statusText.textContent = 'Initializing FFmpeg...';
      statusText.className = 'status';

      try {
        await initFFmpeg();
        statusText.textContent = 'Preparing watermark audio...';
        await prepareWatermark();
        statusText.textContent = 'Processing audio...';
        await processAudio();
        statusText.textContent = 'Saving output...';
        await saveOutput();
        statusText.textContent = 'Watermark applied successfully!';
        statusText.className = 'status success';
        showToast('success', 'Watermark applied successfully!', 'success');
      } catch (err) {
        console.error(err);
        statusText.textContent = 'Error: ' + (err.message || 'Unknown error');
        statusText.className = 'status error';
        showToast('error', 'Error processing audio: ' + (err.message || 'Unknown error'), 'error');
      } finally {
        isProcessing = false;
        progressBarFill.style.width = '0%';
        progressBar.hidden = true;
        fileInput.disabled = false;
        watermarkText.disabled = false;
        watermarkPlacement.disabled = false;
        volumeSlider.disabled = false;
        frequencySlider.disabled = false;
        durationSlider.disabled = false;
        formatSelect.disabled = false;
        processBtn.disabled = false;
        cancelBtn.disabled = false;
        clearBtn.disabled = false;
      }
    });

    cancelBtn.addEventListener('click', () => {
      if (!isProcessing) return;
      if (worker) {
        worker.postMessage({ action: 'cancel' });
        worker.terminate();
        worker = null;
      }
      if (ffmpeg) {
        ffmpeg.release();
        ffmpeg = null;
      }
      isProcessing = false;
      progressBarFill.style.width = '0%';
      progressBar.hidden = true;
      showToast('error', 'Processing cancelled.', 'error');
    });

    clearBtn.addEventListener('click', () => {
      currentFile = null;
      fileInput.value = '';
      updatePreview();
      updateWatermarkDisplay();
      updateVolumeDisplay();
      updateFrequencyDisplay();
      updateDurationDisplay();
      processBtn.disabled = true;
      cancelBtn.disabled = true;
      clearBtn.disabled = true;
      fileInput.disabled = false;
      watermarkText.disabled = false;
      watermarkPlacement.disabled = false;
      volumeSlider.disabled = false;
      frequencySlider.disabled = false;
      durationSlider.disabled = false;
      formatSelect.disabled = false;
    });

    async function initFFmpeg() {
      if (ffmpeg) return;
      try {
        const FFmpeg = await window.FFmpeg;
        ffmpeg = new FFmpeg();
        await ffmpeg.load();
      } catch (err) {
        throw new Error('FFmpeg failed to load: ' + err.message);
      }
    }

    async function prepareWatermark() {
      const text = watermarkText.value.trim() || '© 2025 YourBrand';
      const placement = watermarkPlacement.value;
      const volume = parseInt(volumeSlider.value, 10) / 100;
      const frequency = parseInt(frequencySlider.value, 10);
      const duration = parseFloat(durationSlider.value);

      // Generate a simple sine wave tone with text as metadata
      const tone = await generateTone(text, frequency, duration, volume);
      await ffmpeg.writeFile('tone.wav', tone);

      // Add metadata
      const toneMeta = await ffmpeg.readFile('tone.wav');
      const toneData = toneMeta.data;
      const toneMetadata = {
        title: 'Watermark',
        artist: text,
        album: 'Protected',
        year: new Date().getFullYear(),
        comment: 'Watermarked by Audio Watermark Creator',
      };
      await ffmpeg.writeFile('tone-meta.wav', toneData);

      return { tone, toneMeta };
    }

