from datetime import datetime, timedelta
from typing import List, Dict, Optional
import uuid
import json
from dataclasses import dataclass, field
from enum import Enum
from pathlib import Path
from rich.console import Console
from rich.table import Table
from rich.panel import Panel
from rich.text import Text
from rich.progress import Progress
from rich import box

console = Console()

class MaintenanceCycle(Enum):
    BY_HOURS = "hours"
    BY_DAYS = "days"

@dataclass
class Device:
    id: str
    name: str
    description: str
    cycle_type: MaintenanceCycle
    cycle_value: int  # hours or days
    last_maintenance: datetime = None
    next_maintenance: datetime = None
    status: str = "normal"  # "normal" | "due" | "overdue"
    color: str = "green"
    history: List["MaintenanceRecord"] = field(default_factory=list)

    def __post_init__(self):
        if self.cycle_type == MaintenanceCycle.BY_HOURS:
            self._compute_next_maintenance_hours()
        else:
            self._compute_next_maintenance_days()

    def _compute_next_maintenance_hours(self):
        if self.last_maintenance is None:
            self.last_maintenance = datetime.now() - timedelta(hours=self.cycle_value)
        else:
            self.last_maintenance += timedelta(hours=self.cycle_value)
        self.next_maintenance = self.last_maintenance

    def _compute_next_maintenance_days(self):
        if self.last_maintenance is None:
            self.last_maintenance = datetime.now() - timedelta(days=self.cycle_value)
        else:
            self.last_maintenance += timedelta(days=self.cycle_value)
        self.next_maintenance = self.last_maintenance

    def update_status(self):
        now = datetime.now()
        diff = self.next_maintenance - now
        if diff.total_seconds() < 0:
            self.status = "overdue"
            self.color = "red"
        elif diff.total_seconds() < 7 * 86400:  # 7 days
            self.status = "due"
            self.color = "yellow"
        else:
            self.status = "normal"
            self.color = "green"

@dataclass
class MaintenanceRecord:
    id: str
    device_id: str
    performed_by: str
    performed_at: datetime
    consumables: List[str] = field(default_factory=list)
    notes: str = ""

    def __post_init__(self):
        if self.performed_at is None:
            self.performed_at = datetime.now()

@dataclass
class Consumable:
    id: str
    name: str
    unit: str = "unit"
    stock: int = 0

    def __post_init__(self):
        if self.stock < 0:
            self.stock = 0

@dataclass
