            {"id": str(uuid.uuid4()), "name": "Operator", "role": "operator"},
        ]
        for u in users:
            self.users[u["id"]] = User(**u)

    def _save_data(self):
        """Save current data to JSON files."""
        Path("data").mkdir(exist_ok=True)
        for device in self.devices.values():
            device.update_status()
        with open(Path("data", "devices.json"), "w", encoding="utf-8") as f:
            json.dump([d.__dict__ for d in self.devices.values()], f, indent=2, default=str)
        with open(Path("data", "consumables.json"), "w", encoding="utf-8") as f:
            json.dump([c.__dict__ for c in self.consumables.values()], f, indent=2, default=str)
        with open(Path("data", "personnel.json"), "w", encoding="utf-8") as f:
            json.dump([p.__dict__ for p in self.personnel.values()], f, indent=2, default=str)
        with open(Path("data", "inventory.json"), "w", encoding="utf-8") as f:
            json.dump([i.__dict__ for i in self.inventory.values()], f, indent=2, default=str)
        with open(Path("data", "users.json"), "w", encoding="utf-8") as f:
            json.dump([u.__dict__ for u in self.users.values()], f, indent=2, default=str)

    def register_device(self, name: str, description: str, cycle_type: MaintenanceCycle, cycle_value: int) -> str:
        """Register a new device with maintenance cycle."""
        device_id = str(uuid.uuid4())
        device = Device(
            id=device_id,
            name=name,
            description=description,
            cycle_type=cycle_type,
            cycle_value=cycle_value,
            last_maintenance=None,
            next_maintenance=None,
            status="normal",
            color="green",
            history=[],
        )
        self.devices[device_id] = device
        self._save_data()
        return device_id

    def add_consumable(self, name: str, unit: str, stock: int = 0) -> str:
        """Add a consumable to inventory."""
        c_id = str(uuid.uuid4())
        self.consumables[c_id] = Consumable(id=c_id, name=name, unit=unit, stock=stock)
        self._save_data()
        return c_id

    def add_personnel(self, name: str, department: str = "Maintenance") -> str:
        """Add a maintenance personnel."""
        p_id = str(uuid.uuid4())
        self.personnel[p_id] = Personnel(id=p_id, name=name, department=department)
        self._save_data()
        return p_id

    def add_inventory_item(self, name: str, unit: str, stock: int = 0, reorder_point: int = 0) -> str:
        """Add an inventory item."""
        i_id = str(uuid.uuid4())
        self.inventory[i_id] = Inventory(id=i_id, name=name, unit=unit, stock=stock, reorder_point=reorder_point)
        self._save_data()
        return i_id

    def add_maintenance_record(self, device_id: str, performed_by: str, consumables: List[str], notes: str = "") -> str:
        """Add a maintenance record."""
        if device_id not in self.devices:
            raise ValueError(f"Device {device_id} not found.")
        if performed_by not in self.personnel:
            raise ValueError(f"Personnel {performed_by} not found.")
        record_id = str(uuid.uuid4())
        record = MaintenanceRecord(
            id=record_id,
            device_id=device_id,
            performed_by=performed_by,
            performed_at=None,
            consumables=consumables,
            notes=notes,
        )
        self.devices[device_id].history.append(record)
        self._save_data()
        return record_id

