    def list_records_for_device(self, device_id: str) -> List[MaintenanceRecord]:
        """List maintenance records for a device."""
        device = self.get_device(device_id)
        if not device:
            return []
        return sorted(device.history, key=lambda r: r.performed_at, reverse=True)

    def update_consumable_stock(self, c_id: str, delta: int) -> None:
        """Update consumable stock."""
        c = self.get_consumable(c_id)
        if not c:
            return
        c.stock += delta
        self._save_data()

    def update_inventory_stock(self, i_id: str, delta: int) -> None:
        """Update inventory stock."""
        i = self.get_inventory(i_id)
        if not i:
            return
        i.stock += delta
        self._save_data()

    def update_device_cycle(self, device_id: str, cycle_type: MaintenanceCycle, cycle_value: int) -> None:
        """Update device maintenance cycle."""
        device = self.get_device(device_id)
        if not device:
            return
        device.cycle_type = cycle_type
        device.cycle_value = cycle_value
        device._compute_next_maintenance_hours() if cycle_type == MaintenanceCycle.BY_HOURS else device._compute_next_maintenance_days()
        device.update_status()
        self._save_data()

