        device = self.get_device(device_id)
        return device.next_maintenance

    def get_device_age(self, device_id: str) -> int:
        """Get device age in days since last maintenance."""
        device = self.get_device(device_id)
        if device.last_maintenance:
            return (datetime.now() - device.last_maintenance).days
        return 0

    def get_consumable_usage(self, device_id: str) -> Dict[str, int]:
        """Get consumable usage statistics for a device."""
        device = self.get_device(device_id)
        if not device:
            return {}
        usage = {}
        for record in device.history:
            for c_id in record.consumables:
                usage[c_id] = usage.get(c_id, 0) + 1
        return usage

