### 3. `server/index.js`

```javascript
const express = require('express');
const cors = require('cors');
const multer = require('multer');
const { ffmpeg } = require('fluent-ffmpeg');
const { outputDir, watermarkText, watermarkColor, watermarkOpacity, watermarkX, watermarkY, watermarkSize, watermarkFont, watermarkRotate, watermarkPadding, watermarkPosition } = require('./ffmpeg.config');
const path = require('path');
const fs = require('fs');
const app = express();
const PORT = process.env.PORT || 3001;

app.use(cors());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Ensure output directory exists
fs.mkdirSync(outputDir, { recursive: true });

// Multer storage
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, outputDir);
  },
  filename: (req, file, cb) => {
    const ext = path.extname(file.originalname);
    const name = path.basename(file.originalname, ext);
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    cb(null, name + '-' + uniqueSuffix + ext);
  },
});

const upload = multer({ storage });

// Upload route
app.post('/api/upload', upload.array('files', 20), (req, res) => {
  if (!req.files || req.files.length === 0) {
    return res.status(400).json({ error: 'No files uploaded' });
  }
  res.json({ files: req.files });
});

// Generate final video route
app.post('/api/generate', (req, res) => {
  const { clips, outputName } = req.body;

  if (!clips || clips.length === 0) {
    return res.status(400).json({ error: 'No clips provided' });
  }

  const outputPath = path.join(outputDir, `${outputName || 'output'}.mp4`);
  const inputPaths = clips.map((c) => path.join(outputDir, c.path));

  const stream = ffmpeg()
    .addInput(inputPaths[0])
    .addInput(inputPaths[1]);

  // Add watermark
  if (watermarkText) {
    stream.addFilter(
      `drawtext=text='${watermarkText}':fontfile=${watermarkFont}:fontsize=${watermarkSize}:fontcolor=${watermarkColor}:alpha=${watermarkOpacity}:x=${watermarkX}:y=${watermarkY}:box=1:boxcolor=0x000000@0.5:boxborderw=2:shadowx=2:shadowy=2:shadowcolor=0x000000`
    );
  }

  stream
    .outputOptions([
      '-c:v libx264',
      '-preset fast',
      '-crf 23',
      '-c:a aac',
      '-b:a 192k',
      '-pix_fmt yuv420p',
      '-strict experimental',
      '-vf "scale=trunc(iw/2)*2:trunc(ih/2)*2"',
    ])
    .on('end', () => {
      res.json({ success: true, outputPath });
    })
    .on('error', (err) => {
      console.error(err);
      res.status(500).json({ error: 'Video generation failed', message: err.message });
    })
    .save(outputPath);
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

