```javascript
import React, { useState, useRef } from 'react';
import { DragDropContext, DropResult } from 'react-dnd';
import HTML5Backend from 'react-dnd-html5-backend';
import TouchBackend from 'react-dnd-touch-backend';
import { useDrag, useDrop } from 'react-dnd';
import {
  Box,
  Flex,
  VStack,
  HStack,
  Text,
  Button,
  Input,
  Stack,
  Divider,
  useToast,
} from '@chakra-ui/react';
import { FaUpload, FaPlay, FaPause, FaStop, FaTrash, FaTimes, FaPlus, FaFolderOpen, FaDownload } from 'react-icons/fa';
import UploadPanel from './components/UploadPanel';
import Sidebar from './components/Sidebar';
import Timeline from './components/Timeline';
import Preview from './components/Preview';
import Toolbar from './components/Toolbar';

const TYPE = 'CLIP';

function App() {
  const [files, setFiles] = useState([]);
  const [clips, setClips] = useState([]);
  const [selectedClip, setSelectedClip] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [isExporting, setIsExporting] = useState(false);
  const [exportName, setExportName] = useState('output');
  const [previewUrl, setPreviewUrl] = useState(null);
  const [previewDuration, setPreviewDuration] = useState(0);
  const [previewLoaded, setPreviewLoaded] = useState(false);

  const toast = useToast();

  const handleDrop = (item) => {
    setFiles((prev) => [...prev, item]);
  };

  const handleRemove = (index) => {
    setFiles((prev) => prev.filter((_, i) => i !== index));
  };

  const handleAddToTimeline = (file) => {
    const clip = {
      id: Math.random().toString(36).slice(2, 10),
      type: file.type.startsWith('video/') ? 'video' : 'audio',
      path: file.name,
      duration: 0,
      position: clips.length ? clips[clips.length - 1].position + clips[clips.length - 1].duration : 0,
      order: clips.length,
    };
    setClips((prev) => [...prev, clip]);
  };

  const handleRemoveFromTimeline = (id) => {
    setClips((prev) => prev.filter((c) => c.id !== id));
  };

  const handleExport = async () => {
    if (clips.length === 0) {
      toast({
        title: 'Nothing to export',
        description: 'Add some clips to the timeline first.',
        status: 'warning',
        duration: 3000,
      });
      return;
    }
    setIsExporting(true);
    try {
      const response = await fetch('/api/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ clips, outputName: exportName }),
      });
      const result = await response.json();
      if (result.success) {
        setPreviewUrl(result.outputPath);
        setPreviewDuration(result.clips.reduce((sum, c) => sum + c.duration, 0));
        setPreviewLoaded(true);
        toast({
          title: 'Export successful',
          description: `Video saved as ${result.outputPath}`,
          status: 'success',
          duration: 3000,
        });
      } else {
        toast({
          title: 'Export failed',
          description: result.message || 'Unknown error',
          status: 'error',
          duration: 3000,
        });
      }
    } catch (err) {
      toast({
        title: 'Export failed',
        description: err.message || 'Network error',
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsExporting(false);
    }
  };

  const handleReset = () => {
    setClips([]);
    setFiles([]);
    setPreviewUrl(null);
    setPreviewDuration(0);
    setPreviewLoaded(false);
    setExportName('output');
  };

  const handlePlayPause = () => {
    setIsPlaying((prev) => !prev);
  };

  const handleStop = () => {
    setIsPlaying(false);
    setCurrentTime(0);
  };

  const handleSeek = (delta) => {
    if (!isPlaying) {
      setIsPlaying(true);
    }
    setCurrentTime((prev) => Math.max(0, Math.min(prev + delta, previewDuration)));
  };

  const handleDragEnd = (result) => {
    if (!result.destination) return;
    const { source, destination } = result;
    if (source.index === destination.index) return;
    const reordered = [...clips];
    const [moved] = reordered.splice(source.index, 1);
    reordered.splice(destination.index, 0, moved);
    setClips(reordered);
  };

  const handleClipDrop = (id) => {
    setClips((prev) => {
      const clip = prev.find((c) => c.id === id);
      if (!clip) return prev;
      return prev.map((c) => {
        if (c.id === id) {
          const duration = previewDuration || 0;
          const newPosition = duration - c.position;
          return { ...c, position: newPosition };
        }
        return c;
      });
    });
  };

  const handleClipRemove = (id) => {
    setClips((prev) => prev.filter((c) => c.id !== id));
  };

  const handleClipSelect = (id) => {
    const clip = clips.find((c) => c.id === id);
    if (!clip) return;
    setSelectedClip(clip);
  };

  const handleClipDeselect = () => {
    setSelectedClip(null);
  };

  return (
    <Box minH="100vh" bg="#f5f5f7" color="#1a1a1a">
      <Flex direction="column" minH="100vh">
        <Toolbar
          onPlayPause={handlePlayPause}
          onStop={handleStop}
          isPlaying={isPlaying}
          currentTime={currentTime}
          duration={previewDuration}
          onSeek={handleSeek}
          onExport={handleExport}
          isExporting={isExporting}
          exportName={exportName}
          setExportName={setExportName}
          onReset={handleReset}
        />

        <Flex flex="1" minH="0">
          <Sidebar
            files={files}
            clips={clips}
            onAddToTimeline={handleAddToTimeline}
            onRemove={handleRemove}
            onRemoveFromTimeline={handleRemoveFromTimeline}
            selectedClip={selectedClip}
            onSelect={handleClipSelect}
            onDeselect={handleClipDeselect}
          />
          <Box flex="1" overflow="hidden" position="relative">
            <Timeline
              clips={clips}
              onDragEnd={handleDragEnd}
              onClipDrop={handleClipDrop}
              onClipRemove={handleClipRemove}
              selectedClip={selectedClip}
              onClipSelect={handleClipSelect}
            />
            <Preview
              url={previewUrl}
              duration={previewDuration}
              currentTime={currentTime}
              isPlaying={isPlaying}
              onSeek={handleSeek}
              onPlayPause={handlePlayPause}
              onStop={handleStop}
              previewLoaded={previewLoaded}
            />
          </Box>
        </Flex>
      </Flex>
    </Box>
  );
}

export default DragDropContext(HTML5Backend)(App);
