### 4. `components/Timeline.js`

```javascript
import React from 'react';
import { Box, Flex, Text, HStack, Button, VStack, useDrag, useDrop } from '@chakra-ui/react';
import { FaPlay, FaPause, FaTrash, FaTimes } from 'react-icons/fa';
import Clip from './Clip';

const Timeline = ({
  clips,
  onDragEnd,
  onClipDrop,
  onClipRemove,
  selectedClip,
  onClipSelect,
}) => {
  const containerRef = useRef(null);

  const handleDrag = (id) => {
    const el = document.getElementById(`clip-${id}`);
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const startX = rect.left;
    const startY = rect.top;
    const startLeft = startX - containerRef.current.getBoundingClientRect().left;
    const startTop = startY - containerRef.current.getBoundingClientRect().top;

    const onMove = (e) => {
      const x = e.clientX - containerRef.current.getBoundingClientRect().left;
      const y = e.clientY - containerRef.current.getBoundingClientRect().top;
      const dx = x - startLeft;
      const dy = y - startTop;
      if (Math.abs(dx) > 5 || Math.abs(dy) > 5) {
        onClipDrop(id);
      }
    };
    const onEnd = () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onEnd);
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onEnd);
  };

  const handleClipRemove = (id) => {
    onClipRemove(id);
  };

  const handleClipSelect = (id) => {
    onClipSelect(id);
  };

  return (
    <Box
      ref={containerRef}
      w="full"
      h="36"
      bg="gray.200"
      borderRadius="md"
      position="relative"
      overflow="hidden"
    >
      <Flex w="full" h="full" position="absolute" inset="0">
        {clips.map((clip) => (
          <Clip
            key={clip.id}
            id={clip.id}
            clip={clip}
            isSelected={selectedClip?.id === clip.id}
            onRemove={handleClipRemove}
            onSelect={handleClipSelect}
            onDrag={handleDrag}
          />
        ))}
      </Flex>
    </Box>
  );
};

export default Timeline;
```

