### 6. `components/Preview.js`

```javascript
import React, { useRef, useEffect } from 'react';
import { Box, Text, Button, HStack, VStack, useDrag, useDrop } from '@chakra-ui/react';
import { FaPlay, FaPause, FaStop, FaTimes } from 'react-icons/fa';
import ReactPlayer from 'react-player';

const Preview = ({
  url,
  duration,
  currentTime,
  isPlaying,
  onSeek,
  onPlayPause,
  onStop,
  previewLoaded,
}) => {
  const playerRef = useRef(null);
  const handleSeek = (delta) => {
    if (!playerRef.current) return;
    playerRef.current.seekTo(currentTime + delta);
  };

  const handlePlayPause = () => {
    if (!playerRef.current) return;
    if (isPlaying) {
      playerRef.current.pause();
    } else {
      playerRef.current.play();
    }
  };

  const handleStop = () => {
    if (!playerRef.current) return;
    playerRef.current.seekTo(0);
    playerRef.current.pause();
  };

  useEffect(() => {
    if (!playerRef.current) return;
    if (isPlaying) {
      playerRef.current.play();
    } else {
      playerRef.current.pause();
    }
  }, [isPlaying]);

  return (
    <Box
      w="full"
      h="full"
      position="relative"
      overflow="hidden"
      borderRadius="md"
      bg="gray.50"
    >
      {url ? (
        <ReactPlayer
          ref={playerRef}
          url={url}
          playing={isPlaying}
          controls={false}
          width="100%"
          height="100%"
          config={{
            file: {
              attributes: {
                crossOrigin: 'anonymous',
              },
            },
          }}
        />
      ) : (
        <Box
          w="full"
          h="full"
          display="flex"
          flexDir="column"
          align="center"
          justify="center"
          textAlign="center"
          color="gray.500"
        >
          <FaTimes size={64} />
          <Text mt="2" fontSize="lg" fontWeight="bold">
            No preview available
          </Text>
          <Text fontSize="sm">Add clips to the timeline and export</Text>
        </Box>
      )}
      <Box position="absolute" bottom="8" left="8" zIndex="2">
        <HStack spacing="2">
          <Button
            size="sm"
            variant="ghost"
            colorScheme="blue"
            aria-label="Play"
            onClick={handlePlayPause}
          >
            <FaPlay />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            colorScheme="blue"
            aria-label="Pause"
            onClick={handlePlayPause}
          >
            <FaPause />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            colorScheme="red"
            aria-label="Stop"
            onClick={handleStop}
          >
            <FaStop />
          </Button>
        </HStack>
      </Box>
      <Box position="absolute" bottom="8" right="8" zIndex="2">
        <VStack spacing="1" align="flex-end">
          <Text fontSize="sm" color="gray.500">
            {previewLoaded ? currentTime.toFixed(2) : '0.00'}s
          </Text>
          <Text fontSize="xs" color="gray.500">
            {duration}s
          </Text>
        </VStack>
      </Box>
    </Box>
  );
};

export default Preview;
```

