### `app.js`

```javascript
/* =========================================================
   ScreenSnap — Browser Screenshot Tool
   ========================================================= */

const app = (() => {
  'use strict';

  // ---------- State ----------
  const state = {
    mode: 'area',          // area | window | page
    tool: 'box',           // box | arrow | text
    editing: false,
    canvas: null,
    ctx: null,
    layers: [],            // [{ type, data, x, y, w, h, color, text, font, bg }]
    selectedLayerIdx: -1,
    history: [],
    redoStack: [],
    startX: 0,
    startY: 0,
    endX: 0,
    endY: 0,
    drawing: false,
    textInput: '',
    textX: 0,
    textY: 0,
    fontSize: 18,
    fontFamily: 'Arial, sans-serif',
    textColor: '#000000',
    textBg: 'rgba(255,255,255,0.85)',
    color: '#000000',
    captureRect: null,
    captureTitle: 'Select an area to capture',
    captureSub: 'Drag to select, or click Save to capture the visible window.',
    captureBtnText: 'Save',
  };

  // ---------- DOM ----------
  const $ = (sel) => document.querySelector(sel);
  const $$ = (sel) => document.querySelectorAll(sel);

  const previewInner = $('#previewInner');
  const placeholder = $('#placeholder');
  const sidebar = $('#sidebar');
  const textPanel = $('#textPanel');
  const colorPanel = $('#colorPanel');

  const modeBtns = $$('.mode-btn');
  const toolBtns = $$('.tool-btn');
  const editToggle = $('#editToggle');
  const undoBtn = $('#undoBtn');
  const redoBtn = $('#redoBtn');
  const saveBtn = $('#saveBtn');
  const captureOverlay = $('#captureOverlay');
  const captureTitle = $('#captureTitle');
  const captureSub = $('#captureSub');
  const captureBtnText = $('#confirmCapture');

  // ---------- Canvas helpers ----------
  const makeCanvas = (w, h) => {
    const c = document.createElement('canvas');
    c.width = w;
    c.height = h;
    c.style.width = w + 'px';
    c.style.height = h + 'px';
    c.style.display = 'block';
    c.style.cursor = state.editing ? 'crosshair' : 'default';
    c.setAttribute('tabindex', '0');
    c.setAttribute('role', 'img');
    c.setAttribute('aria-label', 'Screenshot canvas');
    return c;
  };

  const resizeCanvas = (canvas, w, h) => {
    canvas.width = w;
    canvas.height = h;
    canvas.style.width = w + 'px';
    canvas.style.height = h + 'px';
  };

  const clearCanvas = (canvas) => {
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  };

  const drawLayer = (canvas, layer) => {
    const ctx = canvas.getContext('2d');
    ctx.save();
    ctx.translate(layer.x, layer.y);

    if (layer.type === 'box') {
      ctx.strokeStyle = layer.color;
      ctx.lineWidth = 2;
      ctx.strokeRect(0, 0, layer.w, layer.h);
    } else if (layer.type === 'arrow') {
      ctx.strokeStyle = layer.color;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(layer.w, 0);
      ctx.lineTo(layer.w - 8, 8);
      ctx.lineTo(layer.w - 8, -8);
      ctx.closePath();
      ctx.stroke();
    } else if (layer.type === 'text') {
      ctx.font = `${layer.fontSize}px ${layer.fontFamily}`;
      ctx.fillStyle = layer.textColor;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText(layer.text, 0, 0);
      ctx.globalCompositeOperation = 'destination-out';
      ctx.fillStyle = layer.textBg;
      ctx.fillRect(0, 0, layer.w, layer.h);
      ctx.globalCompositeOperation = 'source-over';
    }

    ctx.restore();
  };

  const drawAll = () => {
    state.layers.forEach((layer) => drawLayer(state.canvas, layer));
  };

  const redraw = () => {
    clearCanvas(state.canvas);
    drawAll();
  };

  // ---------- Mode switching ----------
  const setMode = (mode) => {
    state.mode = mode;
    modeBtns.forEach((b) => {
      const active = b.dataset.mode === mode;
      b.classList.toggle('active', active);
      b.setAttribute('aria-selected', active);
    });
    captureTitle.textContent = state.mode === 'area'
      ? 'Select an area to capture'
      : state.mode === 'window'
        ? 'Capture visible window'
        : 'Capture entire page';
    captureSub.textContent = state.mode === 'area'
      ? 'Drag to select, or click Save to capture the visible window.'
      : state.mode === 'window'
        ? 'Click Save to capture the visible window.'
        : 'Click Save to capture the entire page.';
    captureBtnText.textContent = state.mode === 'area' ? 'Save' : 'Save';
    captureOverlay.classList.remove('hidden');
    state.captureRect = null;
    state.selectedLayerIdx = -1;
    redraw();
  };

  // ---------- Tool switching ----------
  const setTool = (tool) => {
    state.tool = tool;
    toolBtns.forEach((b) => {
      const active = b.dataset.tool === tool;
      b.classList.toggle('active', active);
      b.disabled = active ? false : true;
    });
    if (tool === 'text') {
      textPanel.classList.remove('hidden');
      colorPanel.classList.add('hidden');
    } else {
      textPanel.classList.add('hidden');
      colorPanel.classList.remove('hidden');
    }
    redraw();
  };

  // ---------- Editing ----------
  const setEditing = (on) => {
    state.editing = on;
    editToggle.checked = on;
    editToggle.indeterminate = false;
    state.drawing = false;
    state.startX = 0;
    state.startY = 0;
    state.endX = 0;
    state.endY = 0;
    state.textInput = '';
    state.textX = 0;
    state.textY = 0;
    state.selectedLayerIdx = -1;
    undoBtn.disabled = true;
    redoBtn.disabled = true;
    clearCanvas(state.canvas);
    drawAll();
    captureOverlay.classList.add('hidden');
  };

  // ---------- Capture overlay ----------
  const openCapture = () => {
    captureOverlay.classList.remove('hidden');
    if (state.mode === 'area') {
      state.captureRect = null;
      redraw();
    }
  };

  const closeCapture = () => {
    captureOverlay.classList.add('hidden');
  };

  // ---------- Capture logic ----------
  const captureArea = () => {
    if (!state.captureRect) return;
    const { x, y, w, h } = state.captureRect;
    const rect = { x, y, w, h };
    state.captureRect = null;
    return rect;
  };

  const captureWindow = () => {
    const dpr = window.devicePixelRatio || 1;
    const rect = window.visualViewport
      ? {
          x: window.visualViewport.pageLeft,
          y: window.visualViewport.pageTop,
          w: window.visualViewport.width,
          h: window.visualViewport.height,
        }
      : {
          x: 0,
          y: 0,
          w: window.innerWidth,
          h: window.innerHeight,
        };
    return rect;
  };

  const capturePage = () => {
    const dpr = window.devicePixelRatio || 1;
    const scrollX = window.scrollX || window.pageXOffset;
    const scrollY = window.scrollY || window.pageYOffset;
    const width = document.documentElement.scrollWidth;
    const height = document.documentElement.scrollHeight;
    const rect = {
      x: scrollX,
      y: scrollY,
      w: width,
      h: height,
    };
    return rect;
  };

  const capture = () => {
    const rect = state.mode === 'area'
      ? captureArea()
      : state.mode === 'window'
        ? captureWindow()
        : capturePage();

    if (!rect) return null;

    const dpr = window.devicePixelRatio || 1;
    const w = Math.round(rect.w * dpr);
    const h = Math.round(rect.h * dpr);

    const canvas = makeCanvas(w, h);
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);

    // Draw background
    ctx.fillStyle = '#0b0d10';
    ctx.fillRect(0, 0, w, h);

    // Scroll to top (for page mode)
    if (state.mode === 'page') {
      window.scrollTo(0, 0);
    }

    // Draw content
    const content = document.documentElement;
    const rect = content.getBoundingClientRect();
    ctx.save();
    ctx.translate(-rect.left, -rect.top);
    ctx.scale(1, 1);

    // Render visible content
    const clone = content.cloneNode(true);
    clone.style.position = 'absolute';
    clone.style.left = '0';
    clone.style.top = '0';
    clone.style.width = rect.width + 'px';
    clone.style.height = rect.height + 'px';
    clone.style.transform = 'translate(-' + rect.left + 'px, -' + rect.top + 'px)';
    clone.style.transformOrigin = '0 0';
    clone.style.boxSizing = 'border-box';

    // Remove hidden elements
    const hidden = clone.querySelectorAll('hidden, [hidden]');
    hidden.forEach((el) => el.remove());

    // Draw cloned content
    const cloneRect = clone.getBoundingClientRect();
    ctx.fillStyle = '#0b0d10';
    ctx.fillRect(0, 0, cloneRect.width, cloneRect.height);
    ctx.save();
    ctx.translate(-cloneRect.left, -cloneRect.top);
    ctx.scale(1, 1);

    // Render clone into canvas
    const tmp = document.createElement('canvas');
    tmp.width = cloneRect.width;
    tmp.height = cloneRect.height;
    tmp.getContext('2d').drawImage(clone, 0, 0);
    ctx.drawImage(tmp, 0, 0);

    ctx.restore();
    ctx.restore();

    // Add layers
    state.layers.forEach((layer) => {
      ctx.save();
      ctx.translate(layer.x, layer.y);
      if (layer.type === 'box') {
        ctx.strokeStyle = layer.color;
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, layer.w, layer.h);
      } else if (layer.type === 'arrow') {
        ctx.strokeStyle = layer.color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(layer.w, 0);
        ctx.lineTo(layer.w - 8, 8);
        ctx.lineTo(layer.w - 8, -8);
        ctx.closePath();
        ctx.stroke();
      } else if (layer.type === 'text') {
        ctx.font = `${layer.fontSize}px ${layer.fontFamily}`;
        ctx.fillStyle = layer.textColor;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'top';
        ctx.fillText(layer.text, 0, 0);
        ctx.globalCompositeOperation = 'destination-out';
        ctx.fillStyle = layer.textBg;
        ctx.fillRect(0, 0, layer.w, layer.h);
        ctx.globalCompositeOperation = 'source-over';
      }
      ctx.restore();
    });

    return canvas;
  };

  // ---------- Canvas drawing ----------
  const addLayer = (layer) => {
    state.layers.push(layer);
    state.history.push([...state.layers]);
    state.redoStack = [];
    state.selectedLayerIdx = state.layers.length - 1;
    redraw();
    updateUndoRedo();
  };

  const deleteLayer = (idx) => {
    if (idx < 0 || idx >= state.layers.length) return;
    state.layers.splice(idx, 1);
    state.history.push([...state.layers]);
    state.redoStack = [];
    state.selectedLayerIdx = -1;
    redraw();
    updateUndoRedo();
  };

  const undo = () => {
    if (state.history.length === 0) return;
    state.layers = state.history[state.history.length - 1];
    state.history.pop();
    state.selectedLayerIdx = -1;
    redraw();
    updateUndoRedo();
  };

  const redo = () => {
    if (state.redoStack.length === 0) return;
    state.layers = state.redoStack.pop();
    state.history.push([...state.layers]);
    state.selectedLayerIdx = -1;
    redraw();
    updateUndoRedo();
  };

  const updateUndoRedo = () => {
    undoBtn.disabled = state.history.length === 0;
    redoBtn.disabled = state.redoStack.length === 0;
  };

  const selectLayer = (idx) => {
    state.selectedLayerIdx = idx;
    redraw();
  };

  // ---------- Color selection ----------
  const setColor = (color) => {
    state.color = color;
    state.layers.forEach((l) => { if (l.type === 'box' || l.type === 'arrow') l.color = color; });
    redraw();
  };

  // ---------- Text input ----------
  const setText = (text) => {
    if (state.selectedLayerIdx < 0) return;
    const l = state.layers[state.selectedLayerIdx];
    l.text = text;
    redraw();
  };

  // ---------- Save ----------
  const save = () => {
    const canvas = capture();
    if (!canvas) return;
    const url = canvas.toDataURL('image/png');
    const link = document.createElement('a');
    link.download = `screenshot-${Date.now()}.png`;
    link.href = url;
    link.click();
    closeCapture();
  };

  // ---------- Events ----------
  modeBtns.forEach((b) => {
    b.addEventListener('click', () => setMode(b.dataset.mode));
  });

  toolBtns.forEach((b) => {
    b.addEventListener('click', () => setTool(b.dataset.tool));
  });

  editToggle.addEventListener('change', (e) => {
    setEditing(e.target.checked);
  });

  undoBtn.addEventListener('click', undo);
  redoBtn.addEventListener('click', redo);

  saveBtn.addEventListener('click', save);

  $('#cancelCapture').addEventListener('click', closeCapture);

  // Capture overlay drag
  const overlay = captureOverlay;
  overlay.addEventListener('mousedown', (e) => {
    if (e.target.closest('.btn')) return;
    overlay.classList.add('hidden');
  });

  // Color swatches
  $$('.swatch').forEach((sw) => {
    sw.addEventListener('click', () => setColor(sw.dataset.color));
  });

  // Font select
  $('#fontSelect').addEventListener('change', (e) => {
    state.fontFamily = e.target.value;
    if (state.selectedLayerIdx >= 0) {
      state.layers[state.selectedLayerIdx].fontFamily = state.fontFamily;
      redraw();
    }
  });

  // Font size
  $('#fontSize').addEventListener('change', (e) => {
    state.fontSize = parseInt(e.target.value, 10);
    if (state.selectedLayerIdx >= 0) {
      state.layers[state.selectedLayerIdx].fontSize = state.fontSize;
      redraw();
    }
  });

  // Text color
  $('#textColor').addEventListener('change', (e) => {
    state.textColor = e.target.value;
    if (state.selectedLayerIdx >= 0) {
      state.layers[state.selectedLayerIdx].textColor = state.textColor;
      redraw();
    }
  });

  // Text background
  $('#textBg').addEventListener('change', (e) => {
    state.textBg = e.target.value;
    if (state.selectedLayerIdx >= 0) {
      state.layers[state.selectedLayerIdx].textBg = state.textBg;
      redraw();
    }
  });

  // Capture overlay drag (area mode)
  if (state.mode === 'area') {
    overlay.addEventListener('mousedown', (e) => {
      if (e.target.closest('.btn')) return;
      overlay.classList.add('hidden');
    });
  }

  // ---------- Keyboard shortcuts ----------
  document.addEventListener('keydown', (e) => {
    if (!state.editing) return;
    if (e.ctrlKey || e.metaKey) {
      if (e.key === 'z') {
        e.preventDefault();
        undo();
      } else if (e.key === 'y' && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        redo();
      }
    }
  });

  // ---------- Init ----------
  const init = () => {
    state.canvas = makeCanvas(1, 1);
    state.canvas.style.display = 'none';
    previewInner.appendChild(state.canvas);
    redraw();
    setMode('area');
    setTool('box');
    setEditing(true);
    updateUndoRedo();
  };

  return { init };
})();

// Boot
app.init();
```

Creating a **sandbox-style shooting game editor** involves several components:

1. **Scene Editor UI** — drag-and-drop tools, object palette, grid, snap-to-grid, undo/redo.
2. **Entity System** — enemies, obstacles, props, objectives, spawn points, pickups.
3. **Property Inspector** — adjust stats, behavior, tags, and triggers.
4. **Level Saving** — JSON schema for level serialization.
5. **Testing Mode** — run the level with a player-controlled avatar.
6. **Sharing / Export** — export to a shareable format (e.g., `.json`, `.zip` with assets).
7. **Optional**: Keyboard shortcuts, multiplayer preview, asset library.

---

Below is a **web-based prototype** using vanilla JavaScript, HTML, and CSS. It simulates a 2D sandbox editor with:

- A grid-based level.
- Drag-and-drop entities (enemies, obstacles, props).
- Property inspector with editable fields.
- Save/load as JSON.
- Test mode with keyboard controls.

> ⚠️ This is a **single-file prototype** for educational purposes. A production editor would require a framework (like Phaser, Three.js, or a custom canvas engine) and a backend for sharing.

