```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Dynamic Sticker Tool</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<div class="app">
  <header class="topbar">
    <h1>✨ Dynamic Sticker Tool</h1>
    <div class="topbar-right">
      <span class="pill" id="formatPill">Format: GIF</span>
      <button id="exportBtn" class="btn btn-primary">Export</button>
      <button id="clearBtn" class="btn btn-ghost">Clear</button>
    </div>
  </header>

  <div class="workspace">
    <div class="panel panel-left">
      <h3>Canvas</h3>
      <div id="canvasContainer" class="canvas-wrap">
        <canvas id="canvas" width="1200" height="800"></canvas>
        <div id="emptyState" class="empty-state">
          <div class="emoji">🎉</div>
          <p>Upload an image to start</p>
        </div>
      </div>
    </div>

    <div class="panel panel-right">
      <h3>Stickers</h3>
      <div id="stickersList" class="stickers-list"></div>
      <div class="panel-section">
        <h4>Add Sticker</h4>
        <div class="add-sticker">
          <label class="radio">
            <input type="radio" name="stickerType" value="emoji" checked>
            <span>Emoji</span>
          </label>
          <label class="radio">
            <input type="radio" name="stickerType" value="text">
            <span>Text</span>
          </label>
          <label class="radio">
            <input type="radio" name="stickerType" value="image">
            <span>Image</span>
          </label>
          <label class="radio">
            <input type="radio" name="stickerType" value="shape">
            <span>Shape</span>
          </label>
        </div>
        <div id="emojiPicker" class="picker" hidden>
          <div class="picker-grid" id="emojiGrid"></div>
        </div>
        <div id="textInput" class="picker" hidden>
          <input type="text" id="textValue" value="Hello!" placeholder="Text" maxlength="20">
          <div class="picker-grid" id="textEffectGrid">
            <button data-effect="bounce">Bounce</button>
            <button data-effect="pulse">Pulse</button>
            <button data-effect="trail">Trail</button>
            <button data-effect="wave">Wave</button>
            <button data-effect="fade">Fade</button>
          </div>
        </div>
        <div id="imageInput" class="picker" hidden>
          <input type="file" id="fileInput" accept="image/*">
        </div>
        <div id="shapeInput" class="picker" hidden>
          <div class="picker-grid" id="shapeGrid">
            <button data-shape="circle">Circle</button>
            <button data-shape="star">Star</button>
            <button data-shape="heart">Heart</button>
            <button data-shape="square">Square</button>
            <button data-shape="triangle">Triangle</button>
            <button data-shape="diamond">Diamond</button>
          </div>
        </div>
        <button id="addStickerBtn" class="btn btn-primary">Add</button>
      </div>

      <div class="panel-section">
        <h4>Controls</h4>
        <div class="control-group">
          <label for="xInput">X</label>
          <input id="xInput" type="number" value="0" min="-100" max="100">
        </div>
        <div class="control-group">
          <label for="yInput">Y</label>
          <input id="yInput" type="number" value="0" min="-100" max="100">
        </div>
        <div class="control-group">
          <label for="sizeInput">Size</label>
          <input id="sizeInput" type="number" value="100" min="10" max="500">
        </div>
        <div class="control-group">
          <label for="angleInput">Angle (deg)</label>
          <input id="angleInput" type="number" value="0" min="-180" max="180">
        </div>
        <div class="control-group">
          <label for="opacityInput">Opacity</label>
          <input id="opacityInput" type="number" value="1" min="0" max="1" step="0.05">
        </div>
        <div class="control-group">
          <label for="speedInput">Speed</label>
          <input id="speedInput" type="number" value="1" min="0.1" max="5" step="0.1">
        </div>
        <div class="control-group">
          <label for="durationInput">Duration (s)</label>
          <input id="durationInput" type="number" value="3" min="0.5" max="10" step="0.5">
        </div>
        <div class="control-group">
          <label for="loopInput">Loop</label>
          <input id="loopInput" type="checkbox" checked>
        </div>
      </div>
    </div>
  </div>

  <div class="toast" id="toast" role="status" aria-live="polite"></div>
</div>

<script src="https://cdn.jsdelivr.net/npm/gif.js@0.2.0/build/gif.js"></script>
<script src="main.js"></script>
</body>
</html>
