  flex-direction: column;
  gap: 8px;
  max-height: 280px;
  overflow-y: auto;
}
.sticker-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
  background: #273449;
  border: 1px solid #334155;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s;
}
.sticker-item:hover { background: #334155; border-color: #475569; }
.sticker-item.removing { opacity: 0.35; }
.sticker-item .sticker-preview {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1e293b;
  border-radius: 8px;
  flex-shrink: 0;
  font-size: 22px;
}
.sticker-item .sticker-info { flex: 1; min-width: 0; }
.sticker-item .sticker-name {
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sticker-item .sticker-meta {
  font-size: 11px;
  color: #94a3b8;
}
.sticker-item .sticker-actions { display: flex; gap: 4px; }
.sticker-actions button {
  width: 20px;
  height: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid #334155;
  color: #cbd5e1;
  border-radius: 4px;
  cursor: pointer;
  font-size: 10px;
  transition: all 0.2s;
}
.sticker-actions button:hover { background: #334155; color: #fff; }
.sticker-actions button.delete:hover { background: #ef4444; color: #fff; }

.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: #1e293b;
  color: #fff;
  padding: 12px 20px;
  border-radius: 10px;
  border: 1px solid #334155;
  box-shadow: 0 10px 30px rgba(0,0,0,0.4);
  opacity: 0;
  pointer-events: none;
  transition: all 0.3s;
  z-index: 100;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  20% { transform: translateX(-6px); }
  40% { transform: translateX(6px); }
  60% { transform: translateX(-4px); }
  80% { transform: translateX(4px); }
}
.shake { animation: shake 0.4s; }
