  // ---------- Draw ----------
  function draw() {
    const dpr = window.devicePixelRatio || 1;
    canvas.width = canvas.offsetWidth * dpr;
    canvas.height = canvas.offsetHeight * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    // Background
    ctx.fillStyle = '#0b1220';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Image
    if (state.image) {
      const iw = state.imageW;
      const ih = state.imageH;
      const ratio = canvas.width / canvas.height;
      const targetW = canvas.width;
      const targetH = canvas.height;
      const scale = Math.min(targetW / iw, targetH / ih);
      const sw = iw * scale;
      const sh = ih * scale;
      const sx = (targetW - sw) / 2;
      const sy = (targetH - sh) / 2;
      ctx.drawImage(state.image, sx, sy, sw, sh);
    }

    // Stickers
    state.stickers.forEach(s => drawSticker(s));
  }

  function drawSticker(s) {
    ctx.save();
    ctx.globalAlpha = s.opacity;

    // Position
    ctx.translate(s.x, s.y);
    ctx.rotate(s.angle * Math.PI / 180);

    if (s.type === 'emoji') {
      drawEmoji(s.emoji, s.size, s.rotation, s.phase, s.speed);
    } else if (s.type === 'text') {
      drawText(s.text, s.size, s.rotation, s.phase, s.speed, s.textEffect);
    } else if (s.type === 'image') {
      drawImage(s.image, s.size, s.rotation, s.phase, s.speed);
    } else if (s.type === 'shape') {
      drawShape(s.shape, s.size, s.rotation, s.phase, s.speed, s.color);
    }

    ctx.restore();
  }

  // ---------- Emoji ----------
  function drawEmoji(emoji, size, rotation, phase, speed) {
    const r = size / 2;
    const cx = r;
    const cy = r;
    const t = phase * speed;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(rotation + t * 0.1);
    ctx.font = `bold ${size}px "Segoe UI", "Noto Color Emoji", "Apple Color Emoji", "Segoe UI Emoji", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(emoji, 0, 0);
    ctx.restore();
  }

  // ---------- Text ----------
  const TEXT_EFFECTS_IMPL = {
    bounce: (t, size, rotation, phase, speed) => {
      const amp = 40;
      const cx = size / 2;
      const cy = size / 2;
      const t0 = phase * speed;
      const tx = cx + Math.sin(t0) * amp;
      const ty = cy + Math.cos(t0) * amp;
      return { x: tx, y: ty };
    },
    pulse: (t, size, rotation, phase, speed) => {
      const base = size;
      const amp = 20;
      const t0 = phase * speed;
      const s = 0.5 + 0.5 * Math.sin(t0);
      return { x: 0, y: 0, size: base + s * amp };
    },
    trail: (t, size, rotation, phase, speed) => {
      const steps = 5;
      const cx = size / 2;
      const cy = size / 2;
      const t0 = phase * speed;
      const pts = [];
      for (let i = 0; i < steps; i++) {
        const a = (i / steps) * Math.PI * 2;
        const x = cx + Math.sin(t0 + a) * 10;
        const y = cy + Math.cos(t0 + a) * 10;
        pts.push({ x, y });
      }
      return { pts };
    },
    wave: (t, size, rotation, phase, speed) => {
      const cx = size / 2;
      const cy = size / 2;
      const t0 = phase * speed;
      const x = cx + Math.sin(t0) * 40;
      const y = cy + Math.cos(t0) * 40;
      return { x, y };
    },
    fade: (t, size, rotation, phase, speed) => {
      const t0 = phase * speed;
      const alpha = 0.5 + 0.5 * Math.sin(t0);
      return { alpha };
    },
  };

  function drawText(text, size, rotation, phase, speed, effect) {
    const impl = TEXT_EFFECTS_IMPL[effect] || TEXT_EFFECTS_IMPL.bounce;
    const opts = impl(t, size, rotation, phase, speed);
    const r = size / 2;
    const cx = r;
    const cy = r;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(rotation);
    ctx.font = `bold ${size}px "Segoe UI", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    if (opts.pts) {
      opts.pts.forEach(p => {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.fillText(text, 0, 0);
        ctx.restore();
      });
    } else if (opts.x !== undefined && opts.y !== undefined) {
      ctx.translate(opts.x, opts.y);
      ctx.fillText(text, 0, 0);
    } else if (opts.alpha !== undefined) {
      ctx.globalAlpha = opts.alpha;
      ctx.fillText(text, 0, 0);
      ctx.globalAlpha = 1;
    } else {
      ctx.fillText(text, 0, 0);
    }
    ctx.restore();
  }

  // ---------- Image ----------
  function drawImage(src, size, rotation, phase, speed) {
    const r = size / 2;
    const cx = r;
    const cy = r;
    const t = phase * speed;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(rotation + t * 0.1);
    ctx.drawImage(src, -r, -r, size, size);
    ctx.restore();
  }

  // ---------- Shape ----------
  function drawShape(shape, size, rotation, phase, speed, color) {
    const r = size / 2;
    const cx = r;
    const cy = r;
    const t = phase * speed;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(rotation + t * 0.1);
    ctx.fillStyle = color;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (shape === 'circle') {
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, Math.PI * 2);
      ctx.fill();
    } else if (shape === 'star') {
      ctx.beginPath();
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * Math.PI * 2;
        const x = r * Math.cos(a);
        const y = r * Math.sin(a);
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.fill();
    } else if (shape === 'heart') {
      const x1 = -r * 0.5, y1 = r * 0.5;
      const x2 = r * 0.5, y2 = r * 0.5;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.quadraticCurveTo(0, -r, x2, y2);
      ctx.closePath();
      ctx.fill();
    } else if (shape === 'square') {
      ctx.fillRect(-r, -r, r * 2, r * 2);
    } else if (shape === 'triangle') {
      ctx.beginPath();
      ctx.moveTo(-r, 0);
      ctx.lineTo(0, -r);
      ctx.lineTo(r, 0);
      ctx.closePath();
      ctx.fill();
    } else if (shape === 'diamond') {
      ctx.beginPath();
      ctx.moveTo(0, -r);
      ctx.lineTo(r, 0);
      ctx.lineTo(0, r);
      ctx.lineTo(-r, 0);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  // ---------- Stickers list ----------
  function renderStickersList() {
    stickersList.innerHTML = '';
    state.stickers.forEach((s, i) => {
