  }

  function selectSticker(id) {
    const s = state.stickers.find(x => x.id === id);
    if (!s) return;
    xInput.value = s.x;
    yInput.value = s.y;
    sizeInput.value = s.size;
    angleInput.value = s.angle;
    opacityInput.value = s.opacity;
    speedInput.value = s.speed;
    durationInput.value = s.duration;
    loopInput.checked = s.loop;
    stickerType.value = s.type;
    textValue.value = s.type === 'text' ? s.text : s.type === 'emoji' ? s.emoji : s.text;
    textEffectGrid.querySelectorAll('button').forEach(b => b.classList.toggle('active', b.dataset.effect === s.textEffect));
    textEffectGrid.hidden = false;
    imageInput.hidden = false;
    shapeInput.hidden = false;
    emojiGrid.hidden = false;
    addStickerBtn.textContent = 'Update';
    addStickerBtn.classList.add('btn-primary');
    addStickerBtn.disabled = false;
    addStickerBtn.addEventListener('click', () => {
      s.x = parseFloat(xInput.value) || 0;
      s.y = parseFloat(yInput.value) || 0;
      s.size = parseFloat(sizeInput.value) || 100;
      s.angle = parseFloat(angleInput.value) || 0;
      s.opacity = parseFloat(opacityInput.value) || 1;
      s.speed = parseFloat(speedInput.value) || 1;
      s.duration = parseFloat(durationInput.value) || 3;
      s.loop = loopInput.checked;
      s.text = textValue.value || 'Sticker';
      s.emoji = textValue.value || '🎉';
      s.shape = 'circle';
      s.color = '#ff6b6b';
      s.rotation = 0;
      s.phase = 0;
      s.frame = 0;
      s.textEffect = 'bounce';
      state.undoStack.push(JSON.stringify(state.stickers));
      state.redoStack = [];
      draw();
      renderStickersList();
      addStickerBtn.textContent = 'Add';
      addStickerBtn.classList.remove('btn-primary');
      addStickerBtn.disabled = true;
      addStickerBtn.removeEventListener('click', arguments.callee);
      toast.textContent = `Updated sticker`;
      showToast();
    });
  }

  function deleteSticker(id) {
    const idx = state.stickers.findIndex(x => x.id === id);
    if (idx === -1) return;
    state.stickers.splice(idx, 1);
    state.undoStack.push(JSON.stringify(state.stickers));
    state.redoStack = [];
    draw();
    renderStickersList();
    toast.textContent = `Deleted sticker`;
    showToast();
  }

  // ---------- Export ----------
  exportBtn.addEventListener('click', async () => {
    const format = formatPill.textContent.split(':')[1].trim().toLowerCase();
    const stickers = state.stickers.filter(s => s.type !== 'image' || s.image);

    if (stickers.length === 0) {
      toast.textContent = 'No stickers to export';
      showToast();
      return;
    }

    const w = canvas.width;
    const h = canvas.height;
    const duration = parseFloat(durationInput.value) || 3;
    const fps = 12;
    const totalFrames = Math.max(1, Math.round(duration * fps));

    const frames = [];
    for (let f = 0; f < totalFrames; f++) {
      const frameCanvas = document.createElement('canvas');
      frameCanvas.width = w;
      frameCanvas.height = h;
      const fc = frameCanvas.getContext('2d');
      fc.fillStyle = '#0b1220';
      fc.fillRect(0, 0, w, h);
      if (state.image) {
        const iw = state.imageW;
        const ih = state.imageH;
        const ratio = w / h;
        const targetW = w;
        const targetH = h;
        const scale = Math.min(targetW / iw, targetH / ih);
        const sw = iw * scale;
        const sh = ih * scale;
        const sx = (targetW - sw) / 2;
        const sy = (targetH - sh) / 2;
        fc.drawImage(state.image, sx, sy, sw, sh);
      }
      stickers.forEach(s => {
        fc.save();
        fc.globalAlpha = s.opacity;
        fc.translate(s.x, s.y);
        fc.rotate(s.angle * Math.PI / 180);
        if (s.type === 'emoji') {
          const r = s.size / 2;
          const cx = r;
          const cy = r;
          const t = (f / totalFrames) * s.duration;
          fc.save();
          fc.translate(cx, cy);
          fc.rotate(s.rotation + t * 0.1);
          fc.font = `bold ${s.size}px "Segoe UI", "Noto Color Emoji", "Apple Color Emoji", "Segoe UI Emoji", sans-serif`;
          fc.textAlign = 'center';
          fc.textBaseline = 'middle';
          fc.fillText(s.emoji, 0, 0);
          fc.restore();
        } else if (s.type === 'text') {
          const impl = TEXT_EFFECTS_IMPL[s.textEffect] || TEXT_EFFECTS_IMPL.bounce;
          const opts = impl(t, s.size, s.rotation, 0, s.speed);
          const r = s.size / 2;
          const cx = r;
          const cy = r;
          fc.save();
          fc.translate(cx, cy);
          fc.rotate(s.rotation);
          fc.font = `bold ${s.size}px "Segoe UI", sans-serif`;
          fc.textAlign = 'center';
          fc.textBaseline = 'middle';
          if (opts.pts) {
            opts.pts.forEach(p => {
              fc.save();
              fc.translate(p.x, p.y);
              fc.fillText(s.text, 0, 0);
              fc.restore();
            });
          } else if (opts.x !== undefined && opts.y !== undefined) {
            fc.translate(opts.x, opts.y);
            fc.fillText(s.text, 0, 0);
          } else if (opts.alpha !== undefined) {
            fc.globalAlpha = opts.alpha;
            fc.fillText(s.text, 0, 0);
            fc.globalAlpha = 1;
          } else {
            fc.fillText(s.text, 0, 0);
          }
          fc.restore();
        } else if (s.type === 'shape') {
          const r = s.size / 2;
          const cx = r;
          const cy = r;
          const t = (f / totalFrames) * s.duration;
          fc.save();
          fc.translate(cx, cy);
          fc.rotate(s.rotation + t * 0.1);
          fc.fillStyle = s.color;
          fc.strokeStyle = s.color;
          fc.lineWidth = 2;
          fc.lineCap = 'round';
          fc.lineJoin = 'round';
          if (s.shape === 'circle') {
            fc.beginPath();
            fc.arc(0, 0, r, 0, Math.PI * 2);
            fc.fill();
          } else if (s.shape === 'star') {
            fc.beginPath();
            for (let i = 0; i < 5; i++) {
              const a = (i / 5) * Math.PI * 2;
              const x = r * Math.cos(a);
              const y = r * Math.sin(a);
              if (i === 0) fc.moveTo(x, y); else fc.lineTo(x, y);
            }
            fc.closePath();
            fc.fill();
          } else if (s.shape === 'heart') {
            const x1 = -r * 0.5, y1 = r * 0.5;
            const x2 = r * 0.5, y2 = r * 0.5;
            fc.beginPath();
            fc.moveTo(x1, y1);
            fc.quadraticCurveTo(0, -r, x2, y2);
            fc.closePath();
            fc.fill();
          } else if (s.shape === 'square') {
            fc.fillRect(-r, -r, r * 2, r * 2);
          } else if (s.shape === 'triangle') {
            fc.beginPath();
            fc.moveTo(-r, 0);
            fc.lineTo(0, -r);
            fc.lineTo(r, 0);
            fc.closePath();
            fc.fill();
          } else if (s.shape === 'diamond') {
            fc.beginPath();
            fc.moveTo(0, -r);
            fc.lineTo(r, 0);
            fc.lineTo(0, r);
            fc.lineTo(-r, 0);
            fc.closePath();
            fc.fill();
          }
          fc.restore();
        }
        fc.restore();
      });
      frames.push(frameCanvas);
    }

    if (format === 'gif') {
      const gif = gifEncode(frames, w, h, fps);
      download(gif, 'sticker-output.gif');
      toast.textContent = `Exported GIF`;
      showToast();
    } else {
      // WebM via WebCodecs (fallback to GIF if unsupported)
      try {
        const encoder = new ImageWriter({ width: w, height: h, frameRate: fps });
        await Promise.all(frames.map((f, i) => encoder.writeFrame(f, i)));
        const blob = await encoder.close();
        download(blob, 'sticker-output.webm');
        toast.textContent = `Exported WebM`;
        showToast();
      } catch (e) {
        // Fallback to GIF
        const gif = gifEncode(frames, w, h, fps);
        download(gif, 'sticker-output.gif');
        toast.textContent = `WebM export failed, exported GIF instead`;
        showToast();
      }
    }
  });

  function gifEncode(frames, w, h, fps) {
    const gif = new GIF({
      workers: 2,
      quality: 10,
      width: w,
      height: h,
      fps,
      repeat: 0,
    });
    frames.forEach((frame, i) => {
      gif.addFrame(frame, { copy: true, delay: 1000 / fps });
    });
    return new Promise((resolve) => {
      gif.on('finished', resolve);
      gif.render();
    });
  }

  function download(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  // ---------- GIF.js fallback ----------
  // We use gif.js for GIF export (it's lightweight and widely supported)
  // WebM export via WebCodecs is not universally supported, so we use gif.js for both formats
  // For WebM, we'll use a simple frame-by-frame PNG stitch + gif.js (since gif.js supports WebM-like formats via `format: 'webm'` in newer versions).
  // But gif.js doesn't natively support WebM. So we'll use a different approach for WebM: record frames as data URL, then stitch into a GIF via gif.js (which supports WebM-like output).
  // Actually, gif.js supports WebM via `format: 'webm'` (as of v0.2.0+). Let's use that.

  // ---------- Helpers ----------
  function uid() {
    return Math.random().toString(36).slice(2, 10);
  }

  function showToast() {
    toast.classList.add('show');
    clearTimeout(showToast._t);
    showToast._t = setTimeout(() => toast.classList.remove('show'), 2400);
  }

  // ---------- Resize ----------
  window.addEventListener('resize', () => {
    if (state.image) draw();
  });

  // ---------- Keyboard shortcuts ----------
  document.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT') return;
    if (e.key === 'z' && (e.ctrlKey || e.metaKey) && !e.shiftKey) {
      e.preventDefault();
      undoBtn.click();
    } else if (e.key === 'y' && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      redoBtn.click();
    } else if (e.key === 'u') {
      clearBtn.click();
    }
  });

  // ---------- Init ----------
  function init() {
    if (!state.image) {
      const defaultImg = new Image();
      defaultImg.src = 'https://picsum.photos/seed/sticker/1200/800';
      defaultImg.onload = () => {
        state.image = defaultImg;
        state.imageW = defaultImg.naturalWidth;
        state.imageH = defaultImg.naturalHeight;
        state.imageRatio = state.imageW / state.imageH;
        draw();
      };
    } else {
      draw();
    }
  }

  init();
})();
```

