  const player = $('player');
  const playerTitle = $('playerTitle');
  const playBtn = $('playBtn');
  const pauseBtn = $('pauseBtn');
  const stopBtn = $('stopBtn');
  const resetBtn = $('resetBtn');
  const offsetInput = $('offsetInput');
  const offsetValue = $('offsetValue');
  const speedInput = $('speedInput');
  const speedValue = $('speedValue');
  const progressFill = $('progressFill');
  const progressBuffer = $('progressBuffer');
  const lyricsInner = $('lyricsInner');
  const exportBtn = $('exportBtn');

  // ---------- State ----------
  let audioCtx = null;
  let audioBuffer = null;
  let audioSource = null;
  let audioTimer = null;
  let currentTime = 0;
  let duration = 0;
  let playing = false;
  let speed = 1;
  let offset = 0;
  let lyrics = [];
  let wordMap = new Map(); // time -> [word objects]
  let highlightedWords = new Set();
  let exportData = null;

  // ---------- Utilities ----------
  const formatTime = (s) => {
    if (s < 0) s = 0;
    const m = Math.floor(s / 60);
    const sec = Math.floor(s % 60);
    const ms = Math.floor((s - Math.floor(s)) * 100);
    return `${m}:${String(sec).padStart(2, '0')}.${String(ms).padStart(2, '0')}`;
  };

  const parseLrc = (text) => {
    const lines = text.trim().split('\n').filter(Boolean);
    const result = [];
    let currentLine = null;
    for (const line of lines) {
      const m = line.match(/^\[(\d{1,2}):(\d{2})\.(\d{2})\] (.+)$/);
      if (!m) continue;
      const mm = parseInt(m[1], 10);
      const ss = parseInt(m[2], 10);
      const ms = parseInt(m[3], 10);
      const time = mm * 60 + ss + ms / 100;
      const text = m[4].trim();
      if (text) {
        currentLine = { time, text, words: [] };
        result.push(currentLine);
      }
    }
    return result;
  };

  const splitWords = (line) => {
    const words = [];
    const parts = line.split(/([^\p{L}\p{N}]+)/u);
    for (const part of parts) {
      if (/^[^\p{L}\p{N}]+$/.test(part)) {
        // punctuation — keep as single unit
        words.push({ text: part, time: null, length: 0 });
      } else {
        const trimmed = part.trim();
        if (trimmed) {
          // split into individual word tokens
          const tokens = trimmed.split(/\s+/);
          let i = 0;
          while (i < tokens.length) {
            const token = tokens[i];
            if (token) {
              words.push({ text: token, time: null, length: 0 });
            }
            i++;
          }
        }
      }
    }
    return words;
  };

  const buildWordMap = (lyrics) => {
    wordMap.clear();
    lyrics.forEach((line) => {
      const words = splitWords(line.text);
      const lineWords = words.map((w) => ({ ...w, time: line.time }));
      wordMap.set(line.time, lineWords);
    });
  };

  const getWordAtTime = (t) => {
    for (const [lineTime, words] of wordMap.entries()) {
      if (lineTime <= t) {
        for (const w of words) {
          if (w.time === null) continue;
          if (w.time <= t) {
            highlightedWords.add(w);
          } else {
            highlightedWords.delete(w);
          }
        }
      } else {
        for (const w of words) {
          if (w.time === null) continue;
          if (w.time > t) {
            highlightedWords.delete(w);
          }
        }
      }
    }
  };

  // ---------- Audio ----------
  const loadAudio = async (file) => {
    const url = URL.createObjectURL(file);
    try {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const resp = await fetch(url);
      const arrayBuffer = await resp.arrayBuffer();
      audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);
      duration = audioBuffer.duration;
      playerTitle.textContent = file.name || 'Audio';
      renderLyrics();
    } catch (err) {
      showError('Failed to load audio: ' + err.message);
    } finally {
      URL.revokeObjectURL(url);
    }
  };

  const loadLrc = async (file) => {
    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const text = reader.result;
        lyrics = parseLrc(text);
        buildWordMap(lyrics);
        renderLyrics();
      } catch (err) {
        showError('Failed to parse LRC: ' + err.message);
      }
    };
    reader.onerror = () => showError('Failed to read LRC file.');
    reader.readAsText(file);
  };

  const renderLyrics = () => {
    if (!lyrics.length) {
      lyricsInner.innerHTML = '<div class="error">No lyrics loaded. Upload an LRC file.</div>';
      return;
    }
    lyricsInner.innerHTML = '';
    lyrics.forEach((line) => {
      const div = document.createElement('div');
      div.className = 'lyric-line';
      div.dataset.lineTime = line.time;
      const timeEl = document.createElement('span');
      timeEl.className = 'lyric-time';
      timeEl.textContent = formatTime(line.time);
      div.appendChild(timeEl);

      const textEl = document.createElement('span');
      textEl.className = 'lyric-text';
      const words = splitWords(line.text);
      textEl.appendChild(renderWords(words));
      div.appendChild(textEl);
      lyricsInner.appendChild(div);
    });
  };

  const renderWords = (words) => {
    const frag = document.createDocumentFragment();
    words.forEach((w) => {
      const span = document.createElement('span');
      span.className = 'lyric-word';
      span.textContent = w.text;
      span.dataset.time = w.time;
      span.dataset.word = w.text;
      frag.appendChild(span);
    });
    return frag;
  };

  const updateHighlight = () => {
    // Remove active class from all
    document.querySelectorAll('.lyric-word').forEach((el) => {
      el.classList.remove('active', 'past', 'future');
    });
    if (!lyrics.length) return;

    const t = currentTime + offset;
    const lineTime = lyrics[0].time;
    const lineTimeEnd = lyrics[lyrics.length - 1].time;

    // Highlight current line
    const currentLine = lyrics.find((l) => l.time <= t);
    if (currentLine) {
      const lineWords = wordMap.get(currentLine.time);
      if (lineWords) {
        for (const w of lineWords) {
          const el = document.querySelector(`.lyric-word[data-time="${w.time}"][data-word="${w.text}"]`);
          if (el) {
            if (w.time <= t) el.classList.add('active');
            else el.classList.add('future');
          }
        }
      }
    }

    // Highlight previous line (past words)
    if (lyrics.length > 1) {
      const prevLine = lyrics[lyrics.length - 1];
      const prevLineWords = wordMap.get(prevLine.time);
      if (prevLineWords) {
        for (const w of prevLineWords) {
          const el = document.querySelector(`.lyric-word[data-time="${w.time}"][data-word="${w.text}"]`);
          if (el) el.classList.add('past');
        }
      }
    }
  };

  const updateProgress = () => {
    if (!duration) return;
    const pct = (currentTime / duration) * 100;
    progressFill.style.width = pct + '%';
    progressBuffer.style.width = pct + '%';
  };

  // ---------- Playback ----------
  const play = () => {
    if (!audioBuffer) return;
    if (!playing) {
      audioSource = audioCtx.createBufferSource();
      audioSource.buffer = audioBuffer;
      audioSource.playbackRate.value = speed;
      audioSource.connect(audioCtx.destination);
      audioTimer = setInterval(updatePlayback, 20);
      playing = true;
      playBtn.disabled = true;
      pauseBtn.disabled = false;
    }
  };

  const pause = () => {
    if (audioSource) {
      audioSource.stop();
      audioSource = null;
    }
    if (audioTimer) {
      clearInterval(audioTimer);
      audioTimer = null;
    }
    playing = false;
    playBtn.disabled = false;
    pauseBtn.disabled = true;
  };

  const stop = () => {
    pause();
    currentTime = 0;
    offset = 0;
    offsetInput.value = 0;
    offsetValue.textContent = '0.0 s';
    updateHighlight();
    updateProgress();
  };

  const updatePlayback = () => {
    if (!audioSource) return;
    currentTime += speed * 0.02;
    if (currentTime >= duration) {
      currentTime = duration;
      pause();
    }
    updateProgress();
    updateHighlight();
  };

  // ---------- Export ----------
  const exportLrc = () => {
    if (!exportData) return;
    const lines = exportData.map((l) => {
      const time = l.time.toFixed(2);
      return `[${String(Math.floor(l.time / 60)).padStart(2, '0')}:${String(Math.floor(l.time % 60)).padStart(2, '0')}.${String(Math.floor((l.time - Math.floor(l.time)) * 100)).padStart(2, '0')}] ${l.text}`;
    });
    const blob = new Blob([lines.join('\n')], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'karaoke.lrc';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  // ---------- Events ----------
  audioInput.addEventListener('change', (e) => {
    const file = e.target.files && e.target.files[0];
    if (file) loadAudio(file);
  });
  lrcInput.addEventListener('change', (e) => {
    const file = e.target.files && e.target.files[0];
    if (file) loadLrc(file);
  });

  uploadBtn.addEventListener('click', () => {
    audioInput.click();
    lrcInput.click();
  });

  offsetInput.addEventListener('input', () => {
    offset = parseFloat(offsetInput.value);
    offsetValue.textContent = offset.toFixed(1) + ' s';
  });
  speedInput.addEventListener('input', () => {
    speed = parseFloat(speedInput.value);
    speedValue.textContent = speed.toFixed(1) + '×';
  });

  playBtn.addEventListener('click', play);
  pauseBtn.addEventListener('click', pause);
  stopBtn.addEventListener('click', stop);
  resetBtn.addEventListener('click', () => {
    stop();
    if (audioCtx) audioCtx.close();
    audioCtx = null;
    audioBuffer = null;
    audioSource = null;
    currentTime = 0;
    duration = 0;
    playing = false;
    lyrics = [];
    wordMap.clear();
    highlightedWords.clear();
    exportData = null;
    player.hidden = true;
    controls.hidden = true;
    uploadArea.hidden = false;
    lyricsInner.innerHTML = '';
    playerTitle.textContent = 'No audio loaded';
    offsetInput.value = 0;
    offsetValue.textContent = '0.0 s';
    speedInput.value = 1;
    speedValue.textContent = '1.0×';
    playBtn.disabled = false;
    pauseBtn.disabled = true;
    stopBtn.disabled = true;
    resetBtn.disabled = true;
  });

  exportBtn.addEventListener('click', () => {
    if (!exportData) {
      exportData = [...lyrics];
      exportData.forEach((l) => {
        l.time = l.time + offset;
      });
    }
    exportLrc();
  });

  // Keyboard shortcuts
  document.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT') return;
    if (e.code === 'Space') {
      if (playing) pause();
      else play();
      e.preventDefault();
    } else if (e.key === 'r' || e.key === 'R') {
      stop();
    } else if (e.key === 's' || e.key === 'S') {
      if (audioSource) audioSource.stop();
    }
  });

  // ---------- Init ----------
  uploadArea.hidden = false;
  controls.hidden = true;
  player.hidden = true;
  playBtn.disabled = true;
  pauseBtn.disabled = true;
  stopBtn.disabled = true;
  resetBtn.disabled = true;
})();
```

