        <label for="count">Beats</label>
        <input type="number" id="count" min="5" max="20" value="10" />
      </div>
    </div>

    <div class="panel">
      <h3 class="panel-title">Status</h3>
      <div class="status" id="status">
        <span class="status-dot idle" id="statusDot"></span>
        <span id="statusText">Idle — press Start to begin</span>
      </div>
      <div class="row">
        <label for="startBtn">Start</label>
        <button class="btn btn-primary" id="startBtn">Start</button>
      </div>
      <div class="row">
        <label for="resetBtn">Reset</label>
        <button class="btn btn-info" id="resetBtn">Reset</button>
      </div>
    </div>

    <div class="panel">
      <h3 class="panel-title">Timeline</h3>
      <div id="timeline">
        <div class="bar"></div>
        <div class="marker" id="marker1"></div>
        <div class="marker" id="marker2"></div>
        <div class="marker" id="marker3"></div>
        <div class="marker" id="marker4"></div>
        <div class="marker" id="marker5"></div>
        <div class="marker" id="marker6"></div>
        <div class="marker" id="marker7"></div>
        <div class="marker" id="marker8"></div>
      </div>
      <div class="row">
        <label for="beatBtn">Click the beat</label>
        <button id="beatBtn" class="btn btn-primary" disabled>Beat</button>
      </div>
    </div>

    <div class="panel">
      <h3 class="panel-title">Score</h3>
      <div class="score" id="scoreBox">0%</div>
      <div class="log" id="log"></div>
    </div>
  </div>

  <script>
    const bpmEl = document.getElementById('bpm');
    const windowEl = document.getElementById('window');
    const countEl = document.getElementById('count');
    const startBtn = document.getElementById('startBtn');
    const resetBtn = document.getElementById('resetBtn');
    const beatBtn = document.getElementById('beatBtn');
    const statusDot = document.getElementById('statusDot');
    const statusText = document.getElementById('statusText');
    const scoreBox = document.getElementById('scoreBox');
    const logEl = document.getElementById('log');
    const timeline = document.getElementById('timeline');
    const markers = [
      document.getElementById('marker1'), document.getElementById('marker2'),
      document.getElementById('marker3'), document.getElementById('marker4'),
      document.getElementById('marker5'), document.getElementById('marker6'),
      document.getElementById('marker7'), document.getElementById('marker8')
    ];

    const state = {
      bpm: 120,
      window: 120,
      count: 10,
      beats: [],
      current: 0,
      startTime: 0,
      elapsed: 0,
      lastBeat: 0,
      clicks: [],
      score: 0,
      accuracy: 0,
      perfect: 0,
      started: false,
      running: false,
      paused: false,
      finished: false,
      beatInterval: null,
      nextBeatAt: 0,
    };

    function setBpm(v) { state.bpm = Math.max(60, Math.min(200, parseInt(v, 10) || 120)); }
    function setWindow(v) { state.window = Math.max(50, Math.min(300, parseInt(v, 10) || 120)); }
    function setCount(v) { state.count = Math.max(5, Math.min(20, parseInt(v, 10) || 10)); }

    bpmEl.addEventListener('input', (e) => setBpm(e.target.value));
    windowEl.addEventListener('input', (e) => setWindow(e.target.value));
    countEl.addEventListener('input', (e) => setCount(e.target.value));

    function setStatus(text, cls) {
      statusText.textContent = text;
      statusDot.className = 'status-dot ' + cls;
    }

    function updateTimeline() {
      const beats = state.beats;
      if (beats.length === 0) return;
      const totalMs = beats[beats.length - 1].time;
      const bar = timeline.querySelector('.bar');
      bar.style.height = totalMs + 'px';

      markers.forEach((m, i) => {
        const t = beats[i].time;
        m.style.left = (t / totalMs * 100) + '%';
      });
    }

    function generateBeats() {
      const beats = [];
      const totalMs = 60000 / state.bpm * state.count;
      for (let i = 0; i < state.count; i++) {
        const t = (i + 1) * (60000 / state.bpm);
        beats.push({ time: t, index: i });
      }
      state.beats = beats;
      state.current = 0;
      state.elapsed = 0;
      state.lastBeat = 0;
      state.clicks = [];
      state.score = 0;
      state.accuracy = 0;
      state.perfect = 0;
      state.finished = false;
      updateTimeline();
    }

    function log(msg, cls) {
      const now = new Date().toLocaleTimeString();
      logEl.innerHTML += `[${now}] ${msg}\n`;
      logEl.scrollTop = logEl.scrollHeight;
    }

    function evaluateClick(time) {
      const beat = state.beats[state.current];
      if (!beat) return;
      const diff = Math.abs(time - beat.time);
      const ok = diff <= state.window;
      if (ok) {
        const perfect = diff <= 10;
        state.perfect += perfect ? 1 : 0;
        state.score += perfect ? 2 : 1;
        state.accuracy += 1;
        log(`Click at ${time.toFixed(1)}ms — Perfect ${perfect ? '✓' : ''}`, 'ok');
      } else {
        log(`Click at ${time.toFixed(1)}ms — Miss (window: ${state.window}ms)`, 'bad');
      }
      state.clicks.push({ time, beat });
      state.current++;
    }

    function updateScore() {
      if (state.finished) {
        state.accuracy = Math.max(0, state.accuracy);
        const pct = state.accuracy / state.count * 100;
        const perfectPct = state.perfect / state.count * 100;
        scoreBox.textContent = `${pct.toFixed(1)}%`;
        scoreBox.className = 'score';
        if (pct >= 90) scoreBox.classList.add('high');
        else if (pct >= 70) scoreBox.classList.add('medium');
        else if (pct >= 50) scoreBox.classList.add('low');
        else scoreBox.classList.add('none');
        beatBtn.disabled = true;
        startBtn.disabled = false;
        setStatus('Finished — your score', 'stopped');
      } else if (state.current >= state.count) {
        state.finished = true;
        updateScore();
      } else {
        scoreBox.textContent = `${(state.accuracy / state.current * 100).toFixed(1)}%`;
        scoreBox.className = 'score';
        if (state.accuracy / state.current >= 0.9) scoreBox.classList.add('high');
        else if (state.accuracy / state.current >= 0.7) scoreBox.classList.add('medium');
        else if (state.accuracy / state.current >= 0.5) scoreBox.classList.add('low');
        else scoreBox.classList.add('none');
      }
    }

    function start() {
      if (state.running || state.started) return;
      state.started = true;
      state.running = true;
      state.paused = false;
      state.finished = false;
      state.current = 0;
      state.elapsed = 0;
      state.lastBeat = 0;
      state.clicks = [];
      state.score = 0;
      state.accuracy = 0;
      state.perfect = 0;
      state.nextBeatAt = 0;
      generateBeats();
      state.startTime = performance.now();
      updateTimeline();
      updateScore();
      setStatus('Playing — click within window', 'running');
      beatBtn.disabled = false;
      startBtn.disabled = true;
      state.beatInterval = setInterval(() => {
        if (!state.running || state.finished) return;
        const now = performance.now();
        if (now >= state.nextBeatAt) {
          const beat = state.beats[state.current];
          if (beat) {
            const elapsed = now - state.startTime;
            const marker = markers[state.current];
            marker.classList.add('active');
            marker.style.transition = 'height 0.2s, background 0.2s';
            setTimeout(() => {
              marker.classList.remove('active');
            }, 150);
            log(`Beat ${beat.index + 1} at ${elapsed.toFixed(1)}s`);
          }
          state.nextBeatAt = now + (60000 / state.bpm);
        }
      }, 10);
    }

    function pause() {
      if (!state.running) return;
      state.running = false;
      state.paused = true;
      setStatus('Paused', 'paused');
    }

    function resume() {
      if (!state.running || state.paused) {
        state.running = true;
        state.paused = false;
        setStatus('Playing — click within window', 'running');
      }
    }

    function reset() {
      if (state.beatInterval) clearInterval(state.beatInterval);
      state.beatInterval = null;
      state.running = false;
      state.paused = false;
      state.finished = false;
      state.current = 0;
      state.elapsed = 0;
      state.lastBeat = 0;
      state.clicks = [];
      state.score = 0;
      state.accuracy = 0;
      state.perfect = 0;
      state.nextBeatAt = 0;
      state.startTime = 0;
      state.started = false;
      state.beats = [];
      updateTimeline();
      updateScore();
      setStatus('Idle — press Start to begin', 'idle');
      beatBtn.disabled = true;
      startBtn.disabled = false;
      logEl.innerHTML = '';
    }

    startBtn.addEventListener('click', start);
    resetBtn.addEventListener('click', reset);
    beatBtn.addEventListener('click', () => {
      if (!state.running || state.finished) return;
      evaluateClick(performance.now());
      updateScore();
    });

    // Keyboard shortcut: Space to start/pause
    document.addEventListener('keydown', (e) => {
      if (e.code === 'Space') {
        e.preventDefault();
        if (state.running && !state.finished) {
          if (state.paused) resume();
          else pause();
        } else {
          start();
        }
      }
    });

    // Initial render
    updateTimeline();
    updateScore();
    setStatus('Idle — press Start to begin', 'idle');
  </script>
</body>
</html>
```

---

### 🔧 How It Works

- **BPM** controls how fast the beats come.
- **Window** is the time range (in ms) within which a click is considered correct.
- **Count** is the number of beats to play.
- The **timeline** visually represents each beat with a marker that flashes when it's due.
- When a beat is due, the marker turns **blue**. If you click the **Beat** button within the window, the marker turns **green** (perfect) or **yellow** (close). If too late, it turns **red**.
- The **score** is calculated as:
  - 2 points for a perfect click (within 10ms)
  - 1 point for a good click (within window)
  - 0 for a miss
  - Accuracy = (correct clicks / total clicks) × 100
- **Log** records every click with timing feedback.

---

### 💡 Tips for Users

- Try **lower BPM** (e.g., 80) and **wider window** (e.g., 200ms) for beginners.
- Try **higher BPM** (e.g., 160) and **narrower window** (e.g., 80ms) for advanced.
- Use **Space** to pause/resume while playing.
- **Reset** clears your session and starts fresh.

