  // ---------- GROUND ----------
  const groundGeo = new THREE.CircleGeometry(20, 64);
  const groundMat = new THREE.MeshStandardMaterial({ color: 0x1a1a2e, roughness: 0.8, metalness: 0.1 });
  const ground = new THREE.Mesh(groundGeo, groundMat);
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);

  // ---------- STAR FIELD ----------
  function makeStars() {
    const geo = new THREE.BufferGeometry();
    const pos = new Float32Array(CONFIG.stars.count * 3);
    const color = new Float32Array(CONFIG.stars.count * 3);
    for (let i = 0; i < CONFIG.stars.count; i++) {
      const r = 20 + Math.random() * 30;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      pos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
      pos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
      pos[i * 3 + 2] = r * Math.cos(phi);
      const hue = Math.random();
      color[i * 3] = hue;
      color[i * 3 + 1] = hue + 0.1;
      color[i * 3 + 2] = hue + 0.2;
    }
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(color, 3));
    const mat = new THREE.PointsMaterial({ size: 0.08, sizeAttenuation: true, vertexColors: true, transparent: true, opacity: 0.8 });
    return new THREE.Points(geo, mat);
  }
  state.stars = makeStars();
  scene.add(state.stars);

  // ---------- PARTICICLES SYSTEM ----------
  const particleGeo = new THREE.BufferGeometry();
  const particleCount = CONFIG.particles.count;
  const positions = new Float32Array(particleCount * 3);
  const velocities = new Float32Array(particleCount * 3);
  const sizes = new Float32Array(particleCount);
  const colors = new Float32Array(particleCount * 3);
  for (let i = 0; i < particleCount; i++) {
    positions[i * 3] = (Math.random() - 0.5) * 10;
    positions[i * 3 + 1] = (Math.random() - 0.5) * 10;
    positions[i * 3 + 2] = (Math.random() - 0.5) * 10;
    velocities[i * 3] = (Math.random() - 0.5) * 0.3;
    velocities[i * 3 + 1] = (Math.random() - 0.5) * 0.3;
    velocities[i * 3 + 2] = (Math.random() - 0.5) * 0.3;
    sizes[i] = 0.08 + Math.random() * 0.12;
    const hue = Math.random();
    colors[i * 3] = hue;
    colors[i * 3 + 1] = hue + 0.1;
