  particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  particleGeo.setAttribute('velocity', new THREE.BufferAttribute(velocities, 3));
  particleGeo.setAttribute('size', new THREE.BufferAttribute(sizes, 1));
  particleGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));

  const particleMat = new THREE.PointsMaterial({
    size: 0.1,
    sizeAttenuation: true,
    vertexColors: true,
    transparent: true,
    opacity: 0.8,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const particleSystem = new THREE.Points(particleGeo, particleMat);
  scene.add(particleSystem);
  state.particleSystem = particleSystem;

  // ---------- SHIP ----------
  const shipGeo = new THREE.DodecahedronGeometry(1, 0);
  const shipMat = new THREE.MeshStandardMaterial({ color: 0x00ff88, roughness: 0.4, metalness: 0.6 });
  const ship = new THREE.Mesh(shipGeo, shipMat);
  ship.castShadow = true;
  ship.receiveShadow = true;
  ship.position.y = 0.5;
  scene.add(ship);

  // Shield ring
  const shieldRingGeo = new THREE.RingGeometry(1.1, 1.3, 64);
  const shieldMat = new THREE.MeshBasicMaterial({ color: 0xff6600, transparent: true, opacity: 0.4, side: THREE.DoubleSide });
  const shieldRing = new THREE.Mesh(shieldRingGeo, shieldMat);
  shieldRing.position.y = 0.5;
  scene.add(shieldRing);

  // Shield indicator
  const shieldIndicatorGeo = new THREE.RingGeometry(0.3, 0.4, 64);
  const shieldIndicatorMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.8, side: THREE.DoubleSide });
  const shieldIndicator = new THREE.Mesh(shieldIndicatorGeo, shieldIndicatorMat);
  shieldIndicator.position.y = 0.5;
  scene.add(shieldIndicator);

  // ---------- UI ----------
  const ui = document.createElement('div');
  ui.style.cssText = `
    position: fixed;
    top: 10px; left: 10px;
    font-family: monospace;
    color: white;
    background: rgba(0,0,0,0.5);
    padding: 10px 14px;
    border: 2px solid #fff;
    border-radius: 8px;
    font-size: 14px;
    pointer-events: none;
    z-index: 100;
  `;
  ui.innerHTML = `
    <div>SCORE: <b id="score">0</b></div>
    <div>SHIELD: <b id="shield">100</b></div>
  `;
  document.body.appendChild(ui);

  const scoreEl = document.getElementById('score');
  const shieldEl = document.getElementById('shield');

  // ---------- INPUT ----------
  const keys = {};
  window.addEventListener('keydown', (e) => {
    keys[e.code] = true;
    if (e.code === 'Space') {
      e.preventDefault();
      fire();
    }
  });
  window.addEventListener('keyup', (e) => { keys[e.code] = false; });

  // ---------- SPAWN POOLS ----------
  function createAsteroid(size, speed) {
    const geo = new THREE.IcosahedronGeometry(size, 0);
    const mat = new THREE.MeshStandardMaterial({ color: 0x885522, roughness: 0.9, metalness: 0.2 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    mesh.position.set(
      (Math.random() - 0.5) * 30,
      0.5,
      (Math.random() - 0.5) * 30
    );
    mesh.velocity = new THREE.Vector3(
      (Math.random() - 0.5) * speed,
      (Math.random() - 0.5) * speed * 0.4,
      (Math.random() - 0.5) * speed
    );
    mesh.rotation.set(
      Math.random() * Math.PI * 2,
      Math.random() * Math.PI * 2,
      Math.random() * Math.PI * 2
    );
    return mesh;
  }

  function createBullet() {
    const geo = new THREE.ConeGeometry(0.08, 0.6, 8);
    const mat = new THREE.MeshBasicMaterial({ color: 0xff00ff, transparent: true, opacity: 0.9 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.y = 0.5;
    mesh.rotation.z = Math.random() * Math.PI * 2;
    return mesh;
  }

  function createParticle() {
    const geo = new THREE.SphereGeometry(0.08, 16, 16);
    const mat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.8, depthWrite: false });
    return new THREE.Mesh(geo, mat);
  }

  // ---------- GAME LOOP ----------
  function loop() {
    state.time += 1 / 60;

    // Regenerate shield
    state.regen += CONFIG.player.shieldRegen;
    if (state.regen >= 1) {
      state.shield = Math.min(state.maxShield, state.shield + 1);
      state.regen -= 1;
    }

    // Ship movement
    const forward = new THREE.Vector3();
    const right = new THREE.Vector3();
    ship.getWorldDirection(forward);
    forward.y = 0;
    forward.normalize();
    ship.getWorldDirection(right);
    right.y = 0;
    right.normalize();
    right.crossVectors(forward, new THREE.Vector3(0, 1, 0));

    const move = new THREE.Vector3();
    if (keys['KeyW'] || keys['ArrowUp']) move.add(forward);
    if (keys['KeyS'] || keys['ArrowDown']) move.sub(forward);
    if (keys['KeyA'] || keys['ArrowLeft']) move.sub(right);
    if (keys['KeyD'] || keys['ArrowRight']) move.add(right);
    if (move.lengthSq() > 0) move.normalize();

    const turn = new THREE.Vector3(0, 0, 1);
    if (keys['KeyQ'] || keys['ArrowLeft']) turn.x -= 1;
    if (keys['KeyE'] || keys['ArrowRight']) turn.x += 1;
    if (turn.x !== 0) {
      ship.rotateY(turn.x * CONFIG.player.turnSpeed * 0.016);
    }

    if (move.lengthSq() > 0) {
      ship.position.addScaledVector(move, CONFIG.player.speed * 0.016);
    }

    // Keep ship in bounds
    const half = 10;
    if (ship.position.x < -half) ship.position.x = -half;
    if (ship.position.x > half) ship.position.x = half;
    if (ship.position.z < -half) ship.position.z = -half;
    if (ship.position.z > half) ship.position.z = half;

    // Aim camera
    const target = ship.position.clone().add(new THREE.Vector3(0, 1, 0));
    controls.target.copy(target);
    controls.update();

    // Spawn asteroids
    if (Math.random() < CONFIG.asteroids.spawnRate) {
      if (state.asteroids.length < CONFIG.asteroids.maxSpawn) {
        const size = CONFIG.asteroids.minSize + Math.random() * (CONFIG.asteroids.maxSize - CONFIG.asteroids.minSize);
        const speed = CONFIG.asteroids.minSpeed + Math.random() * CONFIG.asteroids.maxSpeed;
        const a = createAsteroid(size, speed);
        state.asteroids.push(a);
