    }

    // Update asteroids
    for (let i = state.asteroids.length - 1; i >= 0; i--) {
      const a = state.asteroids[i];
      a.position.addScaledVector(a.velocity, 0.016);
      a.rotation.y += 0.016;
      a.rotation.x += 0.008;

      // Check collisions with bullets
      for (let b = state.bullets.length - 1; b >= 0; b--) {
        const bullet = state.bullets[b];
        const d = bullet.position.distanceTo(a.position);
        if (d < a.geometry.boundingSphere.radius + bullet.geometry.boundingSphere.radius + 0.1) {
          a.position.copy(bullet.position);
          a.velocity.copy(bullet.velocity);
          state.bullets.splice(b, 1);
          bullet.geometry.dispose();
          bullet.material.dispose();
          bullet.parent.remove(bullet);
          bullet.geometry = null;
          bullet.material = null;
          bullet.position.set(0, 0, 0);
          bullet.velocity.set(0, 0, 0);
          bullet.rotation.set(0, 0, 0);
          bullet.scale.set(0, 0, 0);
          state.bullets.push(bullet);
          spawnAsteroidFragmentation(a, bullet);
          state.score += 10 * Math.round(a.geometry.parameters.radius);
          break;
        }
      }

      // Check collisions with ship
      if (a.position.distanceTo(ship.position) < a.geometry.boundingSphere.radius + 1) {
        hitShield(a);
        a.geometry.dispose();
        a.material.dispose();
        a.parent.remove(a);
        a.geometry = null;
        a.material = null;
        a.position.set(0, 0, 0);
        a.velocity.set(0, 0, 0);
        a.rotation.set(0, 0, 0);
        a.scale.set(0, 0, 0);
        state.asteroids.push(a);
      }
    }

    // Update bullets
    for (let i = state.bullets.length - 1; i >= 0; i--) {
      const b = state.bullets[i];
      b.position.addScaledVector(b.velocity, 0.016);
      b.life -= 0.016;
      if (b.life <= 0) {
        b.geometry.dispose();
        b.material.dispose();
        b.parent.remove(b);
        b.geometry = null;
        b.material = null;
        b.position.set(0, 0, 0);
        b.velocity.set(0, 0, 0);
        b.rotation.set(0, 0, 0);
        b.scale.set(0, 0, 0);
        state.bullets.push(b);
      }
    }

    // Update particles
    for (let i = state.particles.length - 1; i >= 0; i--) {
      const p = state.particles[i];
      p.position.addScaledVector(p.velocity, 0.016);
      p.velocity.y -= 0.005;
      p.scale.x += 0.002;
      p.scale.y += 0.002;
      p.scale.z += 0.002;
      if (p.scale.x > 0.25) {
        p.geometry.dispose();
        p.material.dispose();
        p.parent.remove(p);
        p.geometry = null;
        p.material = null;
        p.position.set(0, 0, 0);
        p.velocity.set(0, 0, 0);
        p.scale.set(0, 0, 0);
        state.particles.push(p);
      }
    }

    // Update star positions
    for (let i = 0; i < CONFIG.stars.count; i++) {
      state.stars.geometry.attributes.position.array[i * 3] = (state.stars.geometry.attributes.position.array[i * 3] + 0.05) % 60;
    }
    state.stars.geometry.attributes.position.needsUpdate = true;

    // Update shield ring
    const ratio = state.shield / state.maxShield;
    shieldRing.scale.setScalar(ratio);
    shieldIndicator.scale.setScalar(ratio);

    // Update UI
    scoreEl.textContent = state.score;
    shieldEl.textContent = Math.round(state.shield);

    // Render
    renderer.render(scene, camera);

    requestAnimationFrame(loop);
  }

  // ---------- FIRE BULLET ----------
  function fire() {
    const b = createBullet();
    b.position.set(ship.position.x, ship.position.y, ship.position.z);
    b.rotation.y = ship.rotation.y;
    const forward = new THREE.Vector3();
    ship.getWorldDirection(forward);
    forward.y = 0;
    forward.normalize();
    b.velocity.copy(forward).multiplyScalar(CONFIG.bullets.speed);
    b.life = CONFIG.bullets.life;
    scene.add(b);
    state.bullets.push(b);
  }

  // ---------- ASTEROID FRAGMENTATION ----------
  function spawnAsteroidFragmentation(asteroid, bullet) {
    const size = asteroid.geometry.parameters.radius;
    const fragments = 3 + Math.floor(size / 0.3);
    for (let i = 0; i < fragments; i++) {
      const f = createAsteroid(size * 0.5, 8 + Math.random() * 6);
      f.position.copy(asteroid.position);
      f.rotation.set(
        Math.random() * Math.PI * 2,
        Math.random() * Math.PI * 2,
        Math.random() * Math.PI * 2
      );
      f.velocity.set(
        (Math.random() - 0.5) * 12,
        (Math.random() - 0.5) * 6,
        (Math.random() - 0.5) * 12
      );
      scene.add(f);
      state.asteroids.push(f);
    }
  }

  // ---------- SHIELD HIT ----------
  function hitShield(asteroid) {
    state.shield = Math.max(0, state.shield - 10);
    spawnShieldSparks(asteroid.position);
  }

  function spawnShieldSparks(position) {
    for (let i = 0; i < 15; i++) {
      const p = createParticle();
      const angle = Math.random() * Math.PI * 2;
      const speed = 2 + Math.random() * 8;
      p.position.copy(position);
      p.position.x += Math.cos(angle) * 0.5;
      p.position.z += Math.sin(angle) * 0.5;
      p.velocity.set(
        Math.cos(angle) * speed,
        0.5 + Math.random() * 1.5,
        Math.sin(angle) * speed
      );
      p.scale.setScalar(0.15 + Math.random() * 0.25);
      p.material.color.setHSL(0.6 + Math.random() * 0.4, 0.9, 0.6 + Math.random() * 0.3);
      scene.add(p);
      state.particles.push(p);
    }
  }

  // ---------- RESIZE ----------
  window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  });

  // ---------- START ----------
  loop();
})();
```

Creating a fully-featured task scheduler with system notifications and JavaScript execution requires careful consideration of security, platform constraints, and the limitations of web-based environments. Since modern browsers and web workers cannot directly trigger system notifications or execute arbitrary JavaScript snippets (like `location.reload()`) outside the context of a webpage, we must design this scheduler as a **web application** that:

1. Runs in a browser (or a desktop app built on Electron, NW.js, or similar).
2. Uses the **Web Notifications API** for desktop notifications.
3. Uses **localStorage** or **IndexedDB** to persist tasks.
4. Uses **service workers** (in Chrome/Firefox) or **background threads** to trigger tasks at the right time.
5. Executes custom JavaScript snippets **only within the context of the current page** (not system-wide).

⚠️ **Important Limitation**: You cannot execute arbitrary JavaScript snippets like `location.reload()` from outside the page context in a secure browser environment. The scheduler can only trigger page reloads *on the page where it is loaded*. If you want to trigger actions across multiple pages, you need a central control page.

---

## ✅ Recommended Architecture

We'll build a **single-page web application** that:

- Lets users add tasks with a schedule (e.g., "daily at 9:00 AM", "every hour").
- Uses a **service worker** to listen for scheduled events (via `setTimeout` or `setInterval`).
- Triggers a notification via the **Web Notifications API**.
- Executes a custom JavaScript snippet **only on the current page** via an injected script.

