// =========================================================
// Interactive Geometric Proof System
// =========================================================
// This system lets users draw geometric figures (points, lines, circles),
// add known conditions (angles, equal sides, parallel lines, etc.),
// and automatically generates a proof step tree.
// Users can expand each step to see the derivation explanation.
// A "Verify" button checks if the proof is complete.
// =========================================================

(function () {
  'use strict';

  // ---------- Canvas & Drawing ----------
  const canvas = document.getElementById('geometryCanvas');
  const ctx = canvas.getContext('2d');
  const zoom = 1.0;
  const scale = () => zoom * 20; // pixels per unit
  const center = { x: canvas.width / 2, y: canvas.height / 2 };

  let points = [];
  let lines = [];
  let circles = [];
  let conditions = []; // { type, label, value, explanation }
  let proofSteps = []; // generated proof steps

  function resizeCanvas() {
    canvas.width = canvas.clientWidth;
    canvas.height = canvas.clientHeight;
    drawAll();
  }

  function drawAll() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawGrid();
    drawPoints();
    drawLines();
    drawCircles();
    drawConditions();
    drawProofSteps();
  }

  function drawGrid() {
    ctx.strokeStyle = '#e0e0e0';
    ctx.lineWidth = 1;
    const step = 20;
    const maxX = canvas.width / scale();
    const maxY = canvas.height / scale();
    for (let x = -maxX; x <= maxX; x += step) {
      ctx.beginPath();
      ctx.moveTo(x * scale() + center.x, 0);
      ctx.lineTo(x * scale() + center.x, canvas.height);
      ctx.stroke();
    }
    for (let y = -maxY; y <= maxY; y += step) {
      ctx.beginPath();
      ctx.moveTo(0, y * scale() + center.y);
      ctx.lineTo(canvas.width, y * scale() + center.y);
      ctx.stroke();
    }
  }

  function drawPoints() {
    ctx.fillStyle = '#ff5555';
    ctx.beginPath();
    for (const p of points) {
      ctx.arc(p.x * scale() + center.x, p.y * scale() + center.y, 5, 0, Math.PI * 2);
    }
    ctx.fill();
    ctx.strokeStyle = '#ff5555';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (const p of points) {
      ctx.arc(p.x * scale() + center.x, p.y * scale() + center.y, 6, 0, Math.PI * 2);
    }
    ctx.stroke();
  }

  function drawLines() {
    ctx.strokeStyle = '#0077cc';
    ctx.lineWidth = 2;
    for (const l of lines) {
      ctx.beginPath();
      ctx.moveTo(l.a.x * scale() + center.x, l.a.y * scale() + center.y);
      ctx.lineTo(l.b.x * scale() + center.x, l.b.y * scale() + center.y);
      ctx.stroke();
    }
  }

  function drawCircles() {
    ctx.strokeStyle = '#55aa55';
    ctx.lineWidth = 2;
    for (const c of circles) {
      ctx.beginPath();
      ctx.arc(c.center.x * scale() + center.x, c.center.y * scale() + center.y, c.radius * scale(), 0, Math.PI * 2);
      ctx.stroke();
    }
  }

  function drawConditions() {
    ctx.fillStyle = '#333';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    for (const c of conditions) {
      const x = c.x * scale() + center.x;
      const y = c.y * scale() + center.y;
      ctx.fillText(c.label + ': ' + c.value, x + 10, y - 5);
    }
  }

  function drawProofSteps() {
    const proofPanel = document.getElementById('proofPanel');
    proofPanel.innerHTML = '';
    for (const step of proofSteps) {
      const el = document.createElement('div');
      el.className = 'proof-step';
      el.innerHTML = `
        <div class="proof-step-label">${step.index}. ${step.label}</div>
        <div class="proof-step-value">${step.value}</div>
        <button class="proof-step-toggle" data-step="${step.index}">+</button>
      `;
      el.addEventListener('click', () => {
        const toggle = el.querySelector('.proof-step-toggle');
        toggle.textContent = toggle.textContent === '+' ? '−' : '+';
        el.querySelector('.proof-step-explanation').style.display = toggle.textContent === '−' ? 'block' : 'none';
      });
      const explanation = document.createElement('div');
      explanation.className = 'proof-step-explanation';
      explanation.style.display = 'none';
      explanation.textContent = step.explanation;
      el.appendChild(explanation);
      proofPanel.appendChild(el);
    }
  }

  // ---------- Interaction ----------
  const drawingMode = {
    point: 'point',
    line: 'line',
    circle: 'circle',
    condition: 'condition'
  };

  let currentMode = drawingMode.point;
  let drawingLineFrom = null;

  function resetDrawing() {
    drawingLineFrom = null;
    canvas.style.cursor = 'crosshair';
  }

  function setMode(mode) {
    currentMode = mode;
    canvas.style.cursor = mode === drawingMode.line ? 'crosshair' : 'default';
  }

  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / scale() - center.x / scale();
    const y = (e.clientY - rect.top) / scale() - center.y / scale();

    if (currentMode === drawingMode.point) {
      points.push({ x, y });
    } else if (currentMode === drawingMode.line) {
      if (drawingLineFrom === null) {
        drawingLineFrom = { x, y };
      } else {
        lines.push({ a: drawingLineFrom, b: { x, y } });
        drawingLineFrom = null;
      }
    } else if (currentMode === drawingMode.circle) {
      circles.push({ center: { x, y }, radius: 0 });
    } else if (currentMode === drawingMode.condition) {
      conditions.push({ x, y, label: 'Angle', value: '30°' });
    }
    drawAll();
  });

  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / scale() - center.x / scale();
    const y = (e.clientY - rect.top) / scale() - center.y / scale();
    canvas.style.cursor = currentMode === drawingMode.line && drawingLineFrom !== null ? 'crosshair' : 'default';
  });

  // ---------- Generate Proof ----------
  function generateProof() {
    proofSteps = [];
    const stepIndex = 0;
    const stepLabel = 'Given';
    const stepValue = conditions.map(c => `${c.label}: ${c.value}`).join(', ');
    const stepExplanation = 'Initial conditions provided by the user.';
    proofSteps.push({ index: stepIndex, label: stepLabel, value: stepValue, explanation: stepExplanation });

    // Generate additional steps based on conditions
    const steps = generateStepsFromConditions(conditions);
    for (const s of steps) {
      proofSteps.push(s);
    }

    drawAll();
    updateVerifyButton();
  }

  function generateStepsFromConditions(conds) {
    const steps = [];
    // Angle chasing
    const angles = conds.filter(c => c.label === 'Angle');
    if (angles.length >= 2) {
      const a1 = angles[0];
      const a2 = angles[1];
      if (Math.abs(a1.value - a2.value) < 0.5) {
        steps.push({
          index: proofSteps.length,
          label: 'Angles on a straight line',
          value: '180°',
          explanation: 'The sum of angles on a straight line is 180°. Subtracting known angles gives the remaining angle.'
        });
      }
    }
    // Triangle angle sum
    if (conds.filter(c => c.label === 'Angle').length >= 2) {
      steps.push({
        index: proofSteps.length,
        label: 'Triangle angle sum',
        value: '180°',
        explanation: 'The sum of interior angles in a triangle is always 180°. Remaining angle = 180° − sum of known angles.'
      });
    }
    // Isosceles triangle
    const sides = conds.filter(c => c.label === 'Side');
    if (sides.length >= 2) {
      const s1 = sides[0];
      const s2 = sides[1];
      if (Math.abs(s1.value - s2.value) < 0.1) {
        steps.push({
          index: proofSteps.length,
          label: 'Isosceles triangle property',
          value: 'Base angles equal',
          explanation: 'In an isosceles triangle, the angles opposite equal sides are equal.'
        });
      }
    }
    // Parallel lines
    const parallels = conds.filter(c => c.label === 'Parallel');
    if (parallels.length >= 1) {
      steps.push({
        index: proofSteps.length,
        label: 'Corresponding angles',
        value: 'Equal',
        explanation: 'When a transversal intersects parallel lines, corresponding angles are equal.'
      });
    }
    return steps;
  }

  // ---------- Verify ----------
  function verifyProof() {
    const incomplete = proofSteps.some(s => s.value === '');
    if (incomplete) {
      alert('Proof is incomplete. Please fill in all required values.');
      return false;
    }
    // Check logical consistency (simple)
    const angles = conditions.filter(c => c.label === 'Angle');
    if (angles.length >= 3) {
      const sum = angles.reduce((a, b) => a + parseFloat(b.value.replace(/[^0-9.]/g, '')), 0);
      if (sum > 180) {
        alert('Angle sum exceeds 180° — check your conditions.');
        return false;
      }
    }
    alert('Proof is complete and logically consistent.');
    return true;
  }

  // ---------- UI ----------
  function buildUI() {
    const toolbar = document.getElementById('toolbar');
    const btnPoint = document.createElement('button');
    btnPoint.textContent = 'Point';
    btnPoint.addEventListener('click', () => setMode(drawingMode.point));
    toolbar.appendChild(btnPoint);

    const btnLine = document.createElement('button');
    btnLine.textContent = 'Line';
    btnLine.addEventListener('click', () => setMode(drawingMode.line));
    toolbar.appendChild(btnLine);

    const btnCircle = document.createElement('button');
    btnCircle.textContent = 'Circle';
    btnCircle.addEventListener('click', () => setMode(drawingMode.circle));
    toolbar.appendChild(btnCircle);

    const btnCondition = document.createElement('button');
    btnCondition.textContent = 'Condition';
    btnCondition.addEventListener('click', () => setMode(drawingMode.condition));
    toolbar.appendChild(btnCondition);

    const btnVerify = document.createElement('button');
    btnVerify.id = 'verifyBtn';
    btnVerify.textContent = 'Verify Proof';
    btnVerify.addEventListener('click', verifyProof);
    toolbar.appendChild(btnVerify);

    const btnReset = document.createElement('button');
    btnReset.textContent = 'Reset';
    btnReset.addEventListener('click', () => {
      points = [];
      lines = [];
      circles = [];
      conditions = [];
      proofSteps = [];
      drawAll();
      updateVerifyButton();
    });
    toolbar.appendChild(btnReset);

    const btnGenerate = document.createElement('button');
    btnGenerate.textContent = 'Generate Proof';
    btnGenerate.addEventListener('click', generateProof);
    toolbar.appendChild(btnGenerate);

    updateVerifyButton();
  }

  function updateVerifyButton() {
    const btn = document.getElementById('verifyBtn');
    if (!btn) return;
    const canVerify = conditions.length > 0;
    btn.disabled = !canVerify;
    btn.textContent = canVerify ? 'Verify Proof' : 'Add conditions first';
  }

  // ---------- Init ----------
  window.addEventListener('resize', resizeCanvas);
  buildUI();
  resizeCanvas();
})();
```

Creating a full terrain destruction shooting game with Perlin noise, fluid simulation, and WebGL is a substantial project. Below is a **professional, production-ready code structure** in **JavaScript (WebGL + Three.js)** that demonstrates:

- Perlin-noise generated terrain
- Bullet impact deformation (with realistic crater physics)
- Water containers that break and release fluid (simple Navier-Stokes-inspired)
- Players/enemies with movement affected by water
- Advanced WebGL rendering (normal maps, water reflections, ambient occlusion)

---

## 🌍 Game Overview

- **Controls**: WASD / Arrow keys to move, Space to shoot
- **Terrain**: Perlin noise + heightmap + vertex displacement on impact
- **Bullets**: Fast projectiles that deform terrain on hit
- **Water**: Fluid particles released when containers break, affecting movement
- **Enemies**: AI patrolling, hiding behind terrain
- **Graphics**: Three.js with post-processing, water reflections, shadows

