## 💥 JavaScript: `game.js`

```javascript
/* =========================================================
   Destruction: Terrain Shooter
   ========================================================= */

(() => {
  'use strict';

  // ---------- Config ----------
  const CONFIG = {
    GRAVITY: 0.0018,
    BULLET_SPEED: 22,
    BULLET_LIFE: 2.2,
    BULLET_RADIUS: 0.04,
    CRATER_MAX: 0.45,
    CRATER_DECAY: 0.012,
    WATER_DENSITY: 0.18,
    WATER_SLOW: 0.65,
    WATER_RESTORE: 0.002,
    MAX_WATER: 1.0,
    WATER_DROP: 0.0035,
    MAX_PLAYERS: 2,
    ENEMY_SPAWN: 4.5,
    ENEMY_SPEED: 0.4,
    ENEMY_HEALTH: 30,
    ENEMY_RELOAD: 2.2,
    ENEMY_RELOAD_VARIANCE: 0.6,
  };

  // ---------- Utilities ----------
  const $ = (s, p = document) => p.querySelector(s);
  const fmt = (n) => Math.round(n * 100) / 100;

  // ---------- Three.js Setup ----------
  const scene = new THREE.Scene();
  scene.fog = new THREE.Fog(0x0a0e1a, 40, 120);
  scene.background = new THREE.Color(0x0a0e1a);

  const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 200);
  camera.position.set(0, 15, 22);
  camera.lookAt(0, 0, 0);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;

  const container = $('#app');
  container.appendChild(renderer.domElement);

  // ---------- Orbit Controls ----------
  const controls = new THREE.OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.12;
  controls.minDistance = 8;
  controls.maxDistance = 50;
  controls.target.set(0, 1, 0);

  // ---------- Post Processing ----------
  const composer = new THREE.EffectComposer(renderer);
  composer.addPass(new THREE.RenderPass(scene, camera));

  const bloomPass = new THREE.UnrealBloomPass(
    new THREE.Vector2(window.innerWidth, window.innerHeight),
    0.55, 0.9, 0.55
  );
  composer.addPass(bloomPass);

  const ssaoPass = new THREE.SSAORenderPass(scene, camera);
  composer.addPass(ssaoPass);

  const outputPass = new THREE.OutputPass();
  composer.addPass(outputPass);

  // ---------- Lights ----------
  const ambient = new THREE.AmbientLight(0x405060, 0.35);
  scene.add(ambient);

  const keyLight = new THREE.DirectionalLight(0xffffff, 0.85);
  keyLight.position.set(15, 25, 10);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.set(2048, 2048);
  keyLight.shadow.camera.left = -20; keyLight.shadow.camera.right = 20;
  keyLight.shadow.camera.top = 20;  keyLight.shadow.camera.bottom = -20;
  keyLight.shadow.bias = -0.0005;
  scene.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0x88ccff, 0.4);
  rimLight.position.set(-15, 20, -10);
  scene.add(rimLight);

  // ---------- Terrain ----------
  const terrain = new Terrain();
  scene.add(terrain.mesh);

  // ---------- Water ----------
  const water = new Water();
  scene.add(water.mesh);

  // ---------- Players ----------
  const players = [];
  const spawnPoints = [
    [-12, 0, -10],
    [12, 0, -10],
    [-12, 0, 10],
    [12, 0, 10],
  ];

  function spawnPlayer(i) {
    const p = new Player(i);
    p.mesh.position.set(...spawnPoints[i]);
    p.mesh.rotation.y = (i * Math.PI) / 2;
    scene.add(p.mesh);
    players.push(p);
  }
  for (let i = 0; i < CONFIG.MAX_PLAYERS; i++) spawnPlayer(i);

  // ---------- Enemies ----------
  const enemies = [];
  const enemyCount = 12;
  for (let i = 0; i < enemyCount; i++) {
    const p = new Enemy(i);
    p.mesh.position.set(
      (Math.random() - 0.5) * 24,
      0,
      (Math.random() - 0.5) * 24
    );
    p.mesh.rotation.y = Math.random() * Math.PI * 2;
    scene.add(p.mesh);
    enemies.push(p);
  }

  // ---------- UI ----------
  const scoreEl = $('#score');
  const ammoEl = $('#ammo');
  const waterEl = $('#water');

  function updateHUD() {
    scoreEl.textContent = fmt(game.score);
    ammoEl.textContent = players[0] ? fmt(players[0].ammo) : '∞';
    waterEl.textContent = fmt(game.water * 100) + '%';
  }

  // ---------- Game State ----------
  const game = {
    score: 0,
    water: 0,
    started: false,
    gameOver: false,
  };

  // ---------- Input ----------
  const keys = {};
  window.addEventListener('keydown', (e) => {
    keys[e.code] = true;
    if (e.code === 'Space' && !game.gameOver) shoot();
    if (e.key === 'Enter' && !game.started) startGame();
  });
  window.addEventListener('keyup', (e) => { keys[e.code] = false; });

  function startGame() {
    game.started = true;
    game.gameOver = false;
    game.score = 0;
    game.water = 0;
    updateHUD();
    players.forEach(p => p.reset());
    enemies.forEach(e => e.reset());
    terrain.reset();
    water.reset();
  }

  function shoot() {
    if (!game.started || game.gameOver) return;
    if (!players[0]) return;
    players[0].shoot();
  }

  // ---------- Camera Follow ----------
  function updateCamera() {
    const p = players[0];
    if (!p) return;
    const target = p.mesh.position.clone();
    target.y = 2.5;
    camera.position.lerp(target, 0.12);
    controls.target.copy(target);
  }

  // ---------- Main Loop ----------
  let lastTime = performance.now();
  function loop(now) {
    const dt = Math.min((now - lastTime) / 1000, 0.05);
    lastTime = now;

    // Players
    players.forEach(p => p.update(dt));
    // Enemies
    enemies.forEach(e => e.update(dt));
    // Terrain
    terrain.update(dt);
    // Water
    water.update(dt);
    // Composer
    composer.render();

    updateCamera();
    updateHUD();

    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  // ---------- Resize ----------
  window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
    composer.setSize(window.innerWidth, window.innerHeight);
  });

  // ---------- Objects ----------
  class Terrain {
    constructor() {
      this.mesh = new THREE.Mesh(
        this.generateGeometry(),
        this.generateMaterial()
      );
      this.mesh.receiveShadow = true;
      this.mesh.castShadow = true;
      this.mesh.position.y = 0;
      this.mesh.scale.set(1, 1, 1);

      // Seed for reproducibility
      this.seed = Math.random();
      this.heights = [];
      this.vertices = [];
      this.indices = [];
      this.craters = []; // {pos, life}
    }

    generateGeometry() {
      const size = 120;
      const divisions = 60;
      const step = size / divisions;

      // Vertices
      const vertices = [];
      const indices = [];
      for (let i = 0; i <= divisions; i++) {
        for (let j = 0; j <= divisions; j++) {
          const x = (i - divisions / 2) * step;
          const z = (j - divisions / 2) * step;
          const h = this.noise(x, z);
          vertices.push(x, h, z);
        }
      }

      // Indices (triangles)
      for (let i = 0; i < divisions; i++) {
        for (let j = 0; j < divisions; j++) {
          const a = i + j * (divisions + 1);
          const b = a + 1;
          const c = a + (divisions + 1);
          const d = c + 1;
          indices.push(a, b, d);
          indices.push(b, c, d);
        }
      }

      const geom = new THREE.BufferGeometry();
      geom.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
      geom.setIndex(indices);
      geom.computeVertexNormals();
      return geom;
    }

    noise(x, z) {
      // Simplex noise via Perlin approximation
      const nx = Math.floor(x + this.seed * 1000);
      const nz = Math.floor(z + this.seed * 1000);
      const fx = x - Math.floor(x);
      const fz = z - Math.floor(z);
      const u = fx * fx * (3 - 2 * fx);
      const v = fz * fz * (3 - 2 * fz);
      const a = this.grad3(nx + 0, nz + 0, fx, fz);
      const b = this.grad3(nx + 1, nz + 0, fx - 1, fz);
      const c = this.grad3(nx + 0, nz + 1, fx, fz - 1);
      const d = this.grad3(nx + 1, nz + 1, fx - 1, fz - 1);
      const x1 = a * u + b * (u - 1) + c * v + d * (v - 1);
      const nx2 = nx + 1;
      const nz2 = nz + 1;
      const a2 = this.grad3(nx2 + 0, nz2 + 0, fx - 1, fz);
      const b2 = this.grad3(nx2 + 1, nz2 + 0, fx - 2, fz);
      const c2 = this.grad3(nx2 + 0, nz2 + 1, fx - 1, fz - 1);
      const d2 = this.grad3(nx2 + 1, nz2 + 1, fx - 2, fz - 1);
      const x2 = a2 * (u - 1) + b2 * (u - 2) + c2 * (v - 1) + d2 * (v - 2);
      return x1 + (x2 - x1) * u * v * 60;
    }

    grad3(i, j, x, y) {
      const g = (i + j) % 4;
      const r = g === 0 ? x : g === 1 ? y : g === 2 ? x * 0.5 + y * 0.5 : x * 0.5 - y * 0.5;
      return (i & 1 ? -1 : 1) * (j & 1 ? -1 : 1) * r;
    }

    generateMaterial() {
      const mat = new THREE.MeshStandardMaterial({
        color: 0x6b8e73,
        roughness: 0.85,
        metalness: 0.1,
        flatShading: false,
      });
      return mat;
    }

    reset() {
      this.craters = [];
    }

    update(dt) {
      // Crater decay
      for (let i = this.craters.length - 1; i >= 0; i--) {
        const c = this.craters[i];
        c.life -= dt * CONFIG.CRATER_DECAY;
        if (c.life <= 0) this.craters.splice(i, 1);
      }

      // Update geometry
      const geo = this.mesh.geometry;
      const positions = geo.attributes.position.array;
      const vertices = this.vertices;
      const indices = this.indices;

      for (let i = 0; i < positions.length; i += 3) {
        const x = positions[i];
        const z = positions[i + 2];
        const h = this.noise(x, z);
        vertices.push(x, h, z);
      }

      // Apply craters
      for (const c of this.craters) {
        const { x, z } = c;
        const idx = Math.floor((x + 100) / 1.5) + Math.floor((z + 100) / 1.5) * (121);
        if (idx >= 0 && idx < positions.length / 3) {
          positions[idx * 3 + 1] = Math.max(-0.5, positions[idx * 3 + 1] - c.life * 0.05);
        }
      }

      // Update geometry
      geo.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
      geo.setIndex(indices);
      geo.computeVertexNormals();
    }

    crater(x, z, radius) {
      this.craters.push({ x, z, life: 1.0, radius });
    }
  }

  class Water {
    constructor() {
      this.mesh = new THREE.Mesh(
        this.generateGeometry(),
        this.generateMaterial()
      );
      this.mesh.receiveShadow = true;
      this.mesh.castShadow = true;
      this.mesh.position.y = 0;
      this.mesh.scale.set(1, 1, 1);

      this.particles = [];
      this.particleCount = 4000;
      this.particlePositions = new Float32Array(this.particleCount * 3);
      this.particleVelocities = new Float32Array(this.particleCount * 3);
      this.particleLives = new Float32Array(this.particleCount);
      this.particleDensity = new Float32Array(this.particleCount);
      this.particleIndices = new Uint16Array(this.particleCount);

      this.generateParticles();
      this.reset();
    }

    generateGeometry() {
      const size = 120;
      const divisions = 60;
      const step = size / divisions;
      const vertices = [];
      for (let i = 0; i <= divisions; i++) {
        for (let j = 0; j <= divisions; j++) {
          const x = (i - divisions / 2) * step;
          const z = (j - divisions / 2) * step;
          vertices.push(x, 0, z);
        }
      }
      const indices = [];
      for (let i = 0; i < divisions; i++) {
        for (let j = 0; j < divisions; j++) {
          const a = i + j * (divisions + 1);
          const b = a + 1;
          const c = a + (divisions + 1);
          const d = c + 1;
          indices.push(a, b, d);
          indices.push(b, c, d);
        }
      }
      const geom = new THREE.BufferGeometry();
      geom.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
      geom.setIndex(indices);
      geom.computeVertexNormals();
      return geom;
    }

    generateMaterial() {
      const mat = new THREE.ShadowMaterial();
      mat.opacity = 0.55;
      return mat;
    }

    generateParticles() {
      const geo = this.mesh.geometry;
      const positions = geo.attributes.position.array;
      const count = this.particleCount;
      const positionsArr = this.particlePositions;
      const velArr = this.particleVelocities;
      const livesArr = this.particleLives;
      const densityArr = this.particleDensity;
      const indicesArr = this.particleIndices;

      for (let i = 0; i < count; i++) {
        const idx = i % positions.length / 3;
        positionsArr[i * 3] = positions[idx * 3];
        positionsArr[i * 3 + 1] = positions[idx * 3 + 1];
        positionsArr[i * 3 + 2] = positions[idx * 3 + 2];
        velArr[i * 3] = (Math.random() - 0.5) * 0.15;
        velArr[i * 3 + 1] = (Math.random() - 0.5) * 0.15 + 0.04;
        velArr[i * 3 + 2] = (Math.random() - 0.5) * 0.15;
        livesArr[i] = 1.0;
        densityArr[i] = 0;
        indicesArr[i] = idx;
      }
    }

    reset() {
      this.particles = [];
      this.particlePositions.set(this.particlePositions);
      this.particleVelocities.set(this.particleVelocities);
      this.particleLives.fill(1.0);
      this.particleDensity.fill(0);
      this.particleIndices.set(this.particleIndices);
    }

    update(dt) {
      const positions = this.particlePositions;
      const vel = this.particleVelocities;
      const lives = this.particleLives;
      const density = this.particleDensity;
      const indices = this.particleIndices;
      const count = this.particleCount;

      // Velocity: gravity + water slow
      for (let i = 0; i < count; i++) {
        vel[i * 3] += CONFIG.GRAVITY * dt;
        vel[i * 3 + 2] += CONFIG.GRAVITY * dt;
        vel[i * 3 + 1] *= 0.995;
        vel[i * 3 + 2] *= 0.995;
      }

      // Move
      for (let i = 0; i < count; i++) {
        positions[i * 3] += vel[i * 3] * dt;
        positions[i * 3 + 1] += vel[i * 3 + 1] * dt;
        positions[i * 3 + 2] += vel[i * 3 + 2] * dt;
        lives[i] -= dt * CONFIG.WATER_RESTORE;
        if (lives[i] <= 0) {
          this.particles.push({
            x: positions[i * 3],
            y: positions[i * 3 + 1],
            z: positions[i * 3 + 2],
            age: 0,
          });
        }
      }

      // Density
      for (let i = 0; i < count; i++) {
        let sum = 0;
        for (let j = 0; j < count; j++) {
          const dx = positions[i * 3] - positions[j * 3];
          const dy = positions[i * 3 + 1] - positions[j * 3 + 1];
          const dz = positions[i * 3 + 2] - positions[j * 3 + 2];
          const d = Math.sqrt(dx * dx + dy * dy + dz * dz);
          if (d < 0.8) sum += 1 / (d + 0.001);
        }
        density[i] = sum;
      }

      // Fluid simulation (simple Navier-Stokes)
      for (let i = 0; i < count; i++) {
        const x = positions[i * 3];
        const y = positions[i * 3 + 1];
        const z = positions[i * 3 + 2];
        const d = density[i];
        if (d > 0.05) {
          // Pressure gradient
          vel[i * 3] += (d - 0.05) * 0.02;
          vel[i * 3 + 2] += (d - 0.05) * 0.02;
        }
      }

      // Update geometry
      const geo = this.mesh.geometry;
      const posAttr = geo.attributes.position;
      for (let i = 0; i < count; i++) {
        posAttr.array[i * 3] = positions[i * 3];
        posAttr.array[i * 3 + 1] = positions[i * 3 + 1];
        posAttr.array[i * 3 + 2] = positions[i * 3 + 2];
      }
      posAttr.needsUpdate = true;
      geo.computeVertexNormals();
    }
  }

  // ---------- Player ----------
  class Player {
    constructor(id) {
      this.id = id;
      this.mesh = new THREE.Mesh(
        new THREE.BoxGeometry(0.8, 1.6, 0.8),
        new THREE.MeshStandardMaterial({
          color: id === 0 ? 0xff4444 : 0x44ff44,
          roughness: 0.7,
          metalness: 0.3,
        })
      );
      this.mesh.castShadow = true;
      this.mesh.receiveShadow = true;
      this.mesh.position.set(0, 0, 0);
      this.mesh.userData = { player: true };

      this.ammo = 120;
      this.fireTimer = 0;
      this.shootCooldown = 0;
    }

    shoot() {
      if (this.shootCooldown > 0) return;
      this.shootCooldown = 0.4;
      const p = this.mesh.position.clone();
      const dir = new THREE.Vector3();
      dir.subVectors(camera.position, p).normalize();
      const bullet = new Bullet(p, dir);
      scene.add(bullet.mesh);
      game.score += 5;
      updateHUD();
    }

    update(dt) {
      const p = this.mesh;
      const c = keys;
      const speed = 4.5;

      if (c['KeyW'] || c['ArrowUp']) p.position.y += speed * dt;
      if (c['KeyS'] || c['ArrowDown']) p.position.y -= speed * dt;
      if (c['KeyA'] || c['ArrowLeft']) p.position.x -= speed * dt;
      if (c['KeyD'] || c['ArrowRight']) p.position.z += speed * dt;

      // Water slowdown
      const waterLevel = water.mesh.geometry.attributes.position.array[0];
      const waterZ = water.mesh.geometry.attributes.position.array[2];
      const waterY = water.mesh.geometry.attributes.position.array[1];
      const playerY = p.position.y;
      const waterAt = waterY + waterZ * 0.01;
      const waterSlow = 1.0 - (playerY - waterAt) * CONFIG.WATER_SLOW;
      p.position.y = playerY * waterSlow;

      // Caps
      p.position.y = Math.max(0.1, Math.min(2.5, p.position.y));
      p.position.x = Math.max(-10, Math.min(10, p.position.x));
      p.position.z = Math.max(-10, Math.min(10, p.position.z));

      // Fire cooldown
      if (this.shootCooldown > 0) this.shootCooldown -= dt;
      if (this.fireTimer > 0) this.fireTimer -= dt;
      if (this.fireTimer <= 0 && this.ammo > 0) {
        this.ammo--;
        this.fireTimer = 0.2;
      }
    }

    reset() {
      this.mesh.position.set(0, 0, 0);
      this.ammo = 120;
      this.shootCooldown = 0;
      this.fireTimer = 0;
    }
  }

  // ---------- Bullet ----------
  class Bullet {
    constructor(pos, dir) {
      this.mesh = new THREE.Mesh(
        new THREE.SphereGeometry(CONFIG.BULLET_RADIUS, 16, 16),
        new THREE.MeshStandardMaterial({
          color: 0xff8800,
          emissive: 0xffaa00,
          emissiveIntensity: 0.6,
          roughness: 0.2,
          metalness: 0.8,
        })
      );
      this.mesh.castShadow = true;
      this.mesh.position.copy(pos);
      this.mesh.userData = { bullet: true };
      scene.add(this.mesh);

      this.dir = dir.clone();
      this.dir.normalize();
      this.life = CONFIG.BULLET_LIFE;
      this.speed = CONFIG.BULLET_SPEED;
      this.hit = false;
      this.crater = null;
    }

    update(dt) {
      if (this.hit) return;
      this.mesh.position.addScaledVector(this.dir, this.speed * dt);
      this.life -= dt;
      if (this.life <= 0) {
        scene.remove(this.mesh);
        this.mesh.geometry.dispose();
        this.mesh.material.dispose();
        this.mesh = null;
      }
    }

    destroy() {
      if (!this.crater) return;
      terrain.crater(this.mesh.position.x, this.mesh.position.z, CONFIG.BULLET_RADIUS * 1.5);
      water.releaseWater(this.mesh.position.x, this.mesh.position.z, 3);
      game.water += CONFIG.WATER_DROP;
      game.score += 10;
      updateHUD();
      scene.remove(this.mesh);
      this.mesh.geometry.dispose();
      this.mesh.material.dispose();
      this.mesh = null;
    }
  }

  // ---------- Enemy ----------
  class Enemy {
    constructor(id) {
      this.id = id;
      this.mesh = new THREE.Mesh(
        new THREE.BoxGeometry(0.9, 1.8, 0.9),
        new THREE.MeshStandardMaterial({
          color: 0x8844aa,
          roughness: 0.7,
          metalness: 0.3,
        })
      );
      this.mesh.castShadow = true;
      this.mesh.receiveShadow = true;
      this.mesh.position.set(0, 0, 0);
      this.mesh.userData = { enemy: true };

      this.health = CONFIG.ENEMY_HEALTH;
      this.reloading = false;
      this.reloadTimer = 0;
      this.targetX = 0;
      this.targetZ = 0;
      this.speed = CONFIG.ENEMY_SPEED;
      this.shootTimer = 0;
    }

    update(dt) {
      const p = this.mesh;
      const tx = this.targetX;
      const tz = this.targetZ;

      // Move toward target
      const dx = tx - p.position.x;
      const dz = tz - p.position.z;
      const dist = Math.sqrt(dx * dx + dz * dz);
      if (dist > 0.05) {
        p.position.x += (dx / dist) * this.speed * dt;
        p.position.z += (dz / dist) * this.speed * dt;
      }

      // Water slowdown
      const waterLevel = water.mesh.geometry.attributes.position.array[0];
      const waterZ = water.mesh.geometry.attributes.position.array[2];
      const waterY = water.mesh.geometry.attributes.position.array[1];
      const waterAt = waterY + waterZ * 0.01;
      const playerY = p.position.y;
      const waterSlow = 1.0 - (playerY - waterAt) * CONFIG.WATER_SLOW;
      p.position.y = playerY * waterSlow;

      // Shoot
      if (!this.reloading && this.shootTimer <= 0) {
        this.shootTimer = CONFIG.ENEMY_RELOAD + (Math.random() - 0.5) * CONFIG.ENEMY_RELOAD_VARIANCE;
        this.shootAtPlayer();
      } else {
        this.shootTimer -= dt;
      }

      // Reload
      if (this.reloading) {
        this.reloading = false;
        this.reloadTimer -= dt;
        if (this.reloadTimer <= 0) {
          this.health = CONFIG.ENEMY_HEALTH;
        }
      }
    }

    shootAtPlayer() {
      const p = this.mesh;
      const target = players[0].mesh.position;
      const dir = new THREE.Vector3();
      dir.subVectors(target, p.position).normalize();
      const bullet = new Bullet(p.position, dir);
      scene.add(bullet.mesh);
      bullet.destroy = () => {
        if (bullet.crater) terrain.crater(bullet.mesh.position.x, bullet.mesh.position.z, CONFIG.BULLET_RADIUS * 1.5);
        if (bullet.crater) water.releaseWater(bullet.mesh.position.x, bullet.mesh.position.z, 3);
        game.score += 5;
        updateHUD();
        scene.remove(bullet.mesh);
        bullet.mesh.geometry.dispose();
        bullet.mesh.material.dispose();
        bullet.mesh = null;
      };
    }

    takeDamage() {
      this.health -= 10;
      if (this.health <= 0) {
        game.score += 20;
        updateHUD();
        scene.remove(this.mesh);
        this.mesh.geometry.dispose();
        this.mesh.material.dispose();
        this.mesh = null;
      }
    }

    reset() {
      this.mesh.position.set(0, 0, 0);
      this.health = CONFIG.ENEMY_HEALTH;
      this.reloading = false;
      this.reloadTimer = 0;
      this.targetX = (Math.random() - 0.5) * 24;
      this.targetZ = (Math.random() - 0.5) * 24;
      this.shootTimer = 0;
    }
  }

  // ---------- Water Release ----------
  function releaseWater(x, z, count) {
    const positions = water.particlePositions;
    const vel = water.particleVelocities;
    const lives = water.particleLives;
    const density = water.particleDensity;
    const indices = water.particleIndices;
    const countArr = water.particleCount;

    const step = 1.5;
    const start = countArr;
    for (let i = 0; i < count; i++) {
      const idx = (x + 100) / step + (z + 100) / step * (121);
      if (idx >= 0 && idx < positions.length / 3) {
        positions[start * 3] = positions[idx * 3];
        positions[start * 3 + 1] = positions[idx * 3 + 1];
        positions[start * 3 + 2] = positions[idx * 3 + 2];
        vel[start * 3] = (Math.random() - 0.5) * 0.3;
        vel[start * 3 + 1] = (Math.random() - 0.5) * 0.3 + 0.08;
        vel[start * 3 + 2] = (Math.random() - 0.5) * 0.3;
        lives[start] = 1.0;
        density[start] = 0;
        indices[start] = idx;
        start++;
      }
    }
    water.particleCount = start;
  }

  // ---------- Start ----------
  startGame();
})();
```

