from flask import Flask, render_template, request, redirect, url_for, flash, jsonify
from flask_login import LoginManager, login_user, logout_user, current_user, login_required
from flask_wtf.csrf import CSRFProtect
from models import db, Room, Reservation, AdminUser, RoomForm, AdminLoginForm
from datetime import datetime, timedelta
import secrets

app = Flask(__name__)
app.config['SECRET_KEY'] = secrets.token_urlsafe(32)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///meeting_rooms.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

db.init_app(app)
csrf = CSRFProtect(app)

login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = 'admin_login'

@login_manager.user_loader
def load_user(user_id):
    return AdminUser.query.get(int(user_id))

def get_available_slots(room_id, date):
    """Return available time slots for a room on a given date."""
    occupied = Reservation.query.filter(
        Reservation.room_id == room_id,
        Reservation.date == date,
        Reservation.status.in_(['confirmed', 'pending'])
    ).all()
    slots = []
    for r in occupied:
        slots.append((r.start_time, r.end_time))
    return slots

@app.route('/')
def index():
    rooms = Room.query.all()
    return render_template('index.html', rooms=rooms)

@app.route('/reserve', methods=['GET', 'POST'])
def reserve():
    form = RoomForm()
    if request.method == 'GET':
        form.room.choices = [(r.id, r.name) for r in Room.query.all()]
    else:
        form.room.choices = [(r.id, r.name) for r in Room.query.all()]
        if form.validate_on_submit():
            room = Room.query.get(form.room.data)
            date = form.date.data
            start_time = form.start_time.data
            end_time = form.end_time.data

            # Validate end time > start time
            if end_time <= start_time:
                flash('End time must be later than start time.', 'error')
                return render_template('reserve.html', form=form)

            # Check overlap
            existing = Reservation.query.filter(
                Reservation.room_id == room.id,
                Reservation.date == date,
                Reservation.status.in_(['confirmed', 'pending'])
            ).all()

            conflict = False
            for r in existing:
                if not (end_time <= r.start_time or start_time >= r.end_time):
                    conflict = True
                    break

            if conflict:
                flash(f'Room {room.name} is already reserved for this time.', 'error')
                return render_template('reserve.html', form=form)

            reservation = Reservation(
                room_id=room.id,
                user_name=form.room.data,
                user_email=form.room.data,
                date=date,
                start_time=start_time,
                end_time=end_time,
                status='confirmed'
            )
            db.session.add(reservation)
            db.session.commit()
            flash(f'Successfully reserved {room.name} from {start_time} to {end_time}.', 'success')
            return redirect(url_for('success', id=reservation.id))

    return render_template('reserve.html', form=form)

@app.route('/success/<int:id>')
def success(id):
    res = Reservation.query.get(id)
    if not res:
        flash('Reservation not found.', 'error')
        return redirect(url_for('index'))
    return render_template('success.html', reservation=res)

@app.route('/admin')
