@app.route('/admin/edit/<int:id>', methods=['GET', 'POST'])
def edit(id):
    if not current_user.is_authenticated:
        return redirect(url_for('admin_login'))
    res = Reservation.query.get(id)
    if not res:
        flash('Reservation not found.', 'error')
