@app.route('/api/available-slots/<int:room_id>/<string:date>')
def api_available_slots(room_id, date):
    """Return available time slots as list of time ranges."""
    date_obj = datetime.strptime(date, '%Y-%m-%d').date()
    occupied = Reservation.query.filter(
        Reservation.room_id == room_id,
        Reservation.date == date_obj,
        Reservation.status.in_(['confirmed', 'pending'])
    ).all()
    occupied_times = set()
    for r in occupied:
        occupied_times.add(r.start_time)
        occupied_times.add(r.end_time)
    occupied_times = sorted(occupied_times)

    available = []
    start = datetime.combine(date_obj, datetime.min.time())
    for end in occupied_times:
        if end > start:
            available.append((start, end))
        start = end
    if start < datetime.combine(date_obj, datetime.max.time()):
        available.append((start, datetime.combine(date_obj, datetime.max.time())))
    return jsonify(available)

