<!-- Toast -->
<div id="toast" class="fixed bottom-6 right-6 bg-gray-800 text-white px-4 py-2 rounded-lg shadow-lg z-50 hidden" role="status">
  <span id="toastMsg"></span>
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/pdf-lib/1.18.1/pdf-lib.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script>

<script>
/* =========================================================
   Academic Conference Submission System
   ========================================================= */

const STORAGE_KEY = 'conf_submissions_v1';
const MAX_FILE_SIZE = 20 * 1024 * 1024; // 20MB
const ALLOWED_TYPES = ['application/pdf'];

const state = {
  file: null,
  fileName: '',
  format: { ok: false, font: '—', margin: '—', pages: 0 },
  blind: false,
  plag: { similarity: '—', matched: '—', source: '—', status: 'idle', percent: 0 },
  history: [],
  stage: 0, // 0: upload, 1: format, 2: blind, 3: plag, 4: submit
};

// ---------- Helpers ----------
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];

function showToast(msg) {
  const t = $('#toast');
  $('#toastMsg').textContent = msg;
  t.classList.remove('hidden');
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => t.classList.add('hidden'), 2500);
}

function loadHistory() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) state.history = JSON.parse(raw);
  } catch { state.history = []; }
}

function saveHistory() {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state.history)); } catch {}
}

function formatNumber(n) { return n.toLocaleString(); }

// ---------- File Handling ----------
$('#fileInput').addEventListener('change', (e) => {
  const f = e.target.files && e.target.files[0];
  if (!f) return;
  if (!ALLOWED_TYPES.includes(f.type) && !f.name.toLowerCase().endsWith('.pdf')) {
    showToast('Please upload a PDF file.');
    e.target.value = '';
    return;
  }
  if (f.size > MAX_FILE_SIZE) {
    showToast('File exceeds 20MB limit.');
    e.target.value = '';
    return;
  }
  handleFile(f);
});

$('#dropZone').addEventListener('click', () => $('#fileInput').click());
$('#dropZone').addEventListener('dragover', (e) => { e.preventDefault(); $('#dropZone').classList.add('border-blue-500'); });
$('#dropZone').addEventListener('dragleave', () => $('#dropZone').classList.remove('border-blue-500'));
$('#dropZone').addEventListener('drop', (e) => {
  e.preventDefault();
  $('#dropZone').classList.remove('border-blue-500');
  const f = e.dataTransfer.files && e.dataTransfer.files[0];
  if (f) handleFile(f);
});

function handleFile(file) {
  state.file = file;
  state.fileName = file.name;
  $('#fileName').textContent = file.name;
  $('#formatStatus').textContent = 'Checking…';
  $('#formatStatus').classList.remove('text-green-700');
  $('#formatStatus').classList.add('text-blue-700');

  // Simulate async analysis
  setTimeout(() => {
    const font = Math.random() < 0.7 ? 'Times New Roman' : 'Arial';
    const margin = Math.random() < 0.6 ? '✓ OK' : '⚠ Off';
    const pages = Math.floor(Math.random() * 10) + 4;
    state.format = { ok: true, font, margin, pages };
    renderFormat();
    showToast(`Format analysis complete: ${pages} pages, ${font} font, ${margin} margins.`);
  }, 1200);
}

// ---------- Format Checker ----------
function renderFormat() {
  $('#formatStatus').textContent = state.format.ok ? '✓ OK' : '⚠ Needs attention';
  $('#formatStatus').classList.toggle('text-green-700', state.format.ok);
  $('#formatStatus').classList.toggle('text-red-700', !state.format.ok);
  $('#formatStatus').classList.toggle('text-blue-700', !state.format.ok);
  $('#preview').innerHTML = `
    <div class="font-sans text-sm">
      <p><strong>Authors:</strong> <span id="previewAuthors"></span></p>
      <p><strong>Title:</strong> <span id="previewTitle"></span></p>
      <p><strong>Abstract:</strong> <span id="previewAbstract"></span></p>
      <p><strong>Track:</strong> <span id="previewTrack"></span></p>
      <p><strong>Pages:</strong> ${formatNumber(state.format.pages)}</p>
      <p><strong>Font:</strong> ${state.format.font}</p>
      <p><strong>Margins:</strong> ${state.format.margin}</p>
    </div>
  `;
  $('#previewAuthors').textContent = state.blind ? '[REDACTED]' : (state.authors || '—');
  $('#previewTitle').textContent = state.title || 'Untitled';
  $('#previewAbstract').textContent = state.abstract || 'No abstract provided.';
  $('#previewTrack').textContent = state.track || '—';

  // Progress
  const pct = Math.round((state.stage / 4) * 100);
  $('#progressPercent').textContent = `${pct}%`;
  $('#progressBar').style.width = `${pct}%`;

  // Stage indicators
  $$('.progress-step').forEach((el, i) => {
    el.classList.toggle('bg-blue-600', i <= state.stage);
    el.classList.toggle('text-blue-600', i <= state.stage);
  });
}

// ---------- Double-Blind ----------
$('#toggleBlindBtn').addEventListener('click', () => {
  state.blind = !state.blind;
  const icon = $('#blindIcon');
  const label = $('#toggleBlindBtn');
  if (state.blind) {
    icon.className = 'fa-solid fa-eye-slash';
    label.textContent = 'Toggle Double-Blind <i class="fa-solid fa-eye-slash"></i>';
    $('#blindStatus').textContent = 'On';
    $('#blindStatus').classList.add('text-green-700');
    $('#blindStatus').classList.remove('text-purple-700');
    showToast('Double-blind mode enabled.');
  } else {
    icon.className = 'fa-solid fa-eye';
    label.textContent = 'Toggle Double-Blind <i class="fa-solid fa-eye"></i>';
    $('#blindStatus').textContent = 'Off';
    $('#blindStatus').classList.remove('text-green-700');
    $('#blindStatus').classList.add('text-purple-700');
    showToast('Double-blind mode disabled.');
  }
});

// ---------- Turnitin Simulation ----------
function runPlagiarism() {
  if (!state.file) {
    showToast('Please upload a PDF first.');
    return;
  }
  if (state.plag.status !== 'idle') {
    showToast('Plagiarism check already running.');
    return;
  }
  state.plag.status = 'running';
  $('#plagStatus').innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Running…';
  $('#plagSimilarity').textContent = '—';
  $('#plagMatched').textContent = '—';
  $('#plagSource').textContent = '—';
  $('#plagBar').style.width = '0%';

  // Simulate progress
  const steps = 6;
  const delay = 120;
  let i = 0;
  const interval = setInterval(() => {
    i++;
    const p = Math.min(100, (i / steps) * 100);
    state.plag.percent = p;
    $('#plagBar').style.width = `${p}%`;
    $('#plagSimilarity').textContent = `${Math.round(p)}%`;

    if (i >= steps) {
      clearInterval(interval);
      const similarity = Math.round(Math.random() * 40) + 15;
      const matched = Math.round(Math.random() * 12) + 3;
      const source = ['Journal of Machine Learning Research', 'ACM Transactions on Computer Systems', 'IEEE Transactions on Neural Networks', 'Springer LNCS', 'Elsevier Pattern Recognition Letters'][Math.floor(Math.random() * 5)];
      state.plag.similarity = `${similarity}%`;
      state.plag.matched = `${matched} matches`;
      state.plag.source = source;
      state.plag.status = 'complete';

      const color = similarity < 15 ? 'text-green-600' : similarity < 25 ? 'text-yellow-600' : 'text-red-600';
      const label = similarity < 15 ? 'Excellent' : similarity < 25 ? 'Good' : 'Needs attention';

      $('#plagSimilarity').textContent = `${similarity}%`;
      $('#plagMatched').textContent = `${matched} matches`;
      $('#plagSource').textContent = source;
      $('#plagStatus').innerHTML = `<i class="fa-solid fa-check"></i> ${label}`;
      $('#plagStatus').classList.remove('bg-gray-100', 'text-gray-500');
      $('#plagStatus').classList.add('bg-green-100', color, 'text-sm', 'font-semibold', 'px-2', 'py-1', 'rounded');

      showToast(`Plagiarism check complete: ${similarity}% similarity.`);
    }
  }, delay);
}

$('#runPlagBtn').addEventListener('click', runPlagiarism);

// ---------- Submission ----------
$('#submitForm').addEventListener('submit', (e) => {
  e.preventDefault();
  const title = $('#title').value.trim();
  const authors = $('#authors').value.trim();
  const abstract = $('#abstract').value.trim();
  const track = $('#track').value;

  if (!title || !authors || !abstract) {
    showToast('Please fill in all fields.');
    return;
  }

  state.title = title;
  state.authors = authors;
  state.track = track;

  // Final progress
  state.stage = 4;
  renderFormat();

  // Simulate submission
  setTimeout(() => {
    const submission = {
      id: Date.now(),
      title,
      authors,
      abstract,
      track,
      file: state.fileName,
      status: 'submitted',
      date: new Date().toISOString(),
      format: state.format,
      blind: state.blind,
      plag: state.plag,
    };
    state.history.unshift(submission);
    saveHistory();
    showToast('Submission successful!');

    // Reset for next submission
    state.stage = 0;
    state.file = null;
    state.fileName = '';
    state.format = { ok: false, font: '—', margin: '—', pages: 0 };
    state.blind = false;
    state.plag = { similarity: '—', matched: '—', source: '—', status: 'idle', percent: 0 };
    $('#fileInput').value = '';
    $('#fileName').textContent = '—';
    $('#formatStatus').textContent = 'Not checked';
    $('#preview').innerHTML = `<p class="text-sm text-gray-500 italic">Preview area — content will appear here after upload.</p>`;
    $('#plagSimilarity').textContent = '—';
    $('#plagMatched').textContent = '—';
    $('#plagSource').textContent = '—';
    $('#plagStatus').innerHTML = '<i class="fa-solid fa-sparkles"></i> Simulated';
    $('#plagStatus').classList.remove('bg-green-100', 'text-green-600');
    $('#plagStatus').classList.add('bg-gray-100', 'text-gray-500');
    $('#plagBar').style.width = '0%';
    $('#progressPercent').textContent = '0%';
    $('#progressBar').style.width = '0%';
    $$('.progress-step').forEach(el => el.classList.remove('bg-blue-600', 'text-blue-600'));
  }, 1400);
});

// ---------- Progress Steps (visual) ----------
const steps = $$('.progress-step');
steps.forEach((el, i) => {
  el.dataset.index = i;
  el.addEventListener('click', () => {
    if (i < state.stage) return;
    state.stage = i;
    renderFormat();
  });
});

// ---------- History ----------
function renderHistory() {
  const list = $('#historyList');
  if (!state.history.length) {
    list.innerHTML = '<p class="text-sm text-gray-500 text-center py-4">No submissions yet.</p>';
    return;
  }
  list.innerHTML = state.history.map(s => `
    <div class="border rounded-lg p-3 mb-2">
      <div class="flex justify-between items-start">
        <div>
          <p class="font-semibold text-sm">${s.title}</p>
          <p class="text-xs text-gray-500">${s.track} · ${s.date.split('T')[0]}</p>
        </div>
        <span class="inline-flex items-center gap-1 px-2 py-1 rounded text-xs font-semibold ${s.status === 'submitted' ? 'bg-blue-100 text-blue-700' : 'bg-gray-100 text-gray-700'}">
          <i class="fa-solid fa-paper-plane"></i> ${s.status}
        </span>
      </div>
    </div>
  `).join('');
}

$('#historyBtn').addEventListener('click', () => {
  $('#historyPanel').classList.toggle('hidden');
});

// ---------- Logout ----------
$('#logoutBtn').addEventListener('click', () => {
  state.history = [];
  saveHistory();
  showToast('Logged out.');
});

// ---------- Init ----------
loadHistory();
renderHistory();
renderFormat();
</script>

</body>
</html>
