  <script>
    const API_KEY = 'YOUR_WEBSHOT_API_KEY'; // Get free key at https://webshot.io
    const form = document.getElementById('screenshotForm');
    const urlInput = document.getElementById('urlInput');
    const captureBtn = document.getElementById('captureBtn');
    const result = document.getElementById('result');
    const success = document.getElementById('success');
    const error = document.getElementById('error');
    const spinner = document.getElementById('spinner');
    const thumbnail = document.getElementById('thumbnail');
    const downloadBtn = document.getElementById('downloadBtn');

    function capture() {
      const url = urlInput.value.trim();
      if (!url) {
        urlInput.focus();
        return;
      }

      captureBtn.disabled = true;
      result.hidden = false;
      success.hidden = true;
      error.hidden = true;

      fetch(`https://api.webshot.io/v1/screenshot?api_key=${API_KEY}&url=${encodeURIComponent(url)}`)
        .then(res => {
          if (!res.ok) throw new Error('Network response was not ok');
          return res.json();
        })
        .then(data => {
          if (data.error) throw new Error(data.error);

          const img = document.createElement('img');
          img.src = data.url;
          img.alt = `Screenshot of ${url}`;
          thumbnail.src = img.src;
          thumbnail.onload = () => {
            success.hidden = false;
            result.hidden = true;
            downloadBtn.disabled = false;
          };
        })
        .catch(err => {
          error.hidden = false;
          result.hidden = false;
          console.error(err);
        })
        .finally(() => {
          captureBtn.disabled = false;
        });
    }

    downloadBtn.addEventListener('click', () => {
      const img = thumbnail;
      const link = document.createElement('a');
      link.href = img.src;
      link.download = 'screenshot.png';
      link.click();
    });

    // Allow Enter key in input
    urlInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        capture();
      }
    });
  </script>
