## 🛠️ Option 2: Server-Side Proxy (Node.js + Puppeteer)

If you want **full control**, **no rate limits**, and **no third-party dependency**, you can run a local proxy:

### ✅ Install Puppeteer

```bash
npm init -y
npm install puppeteer
```

### ✅ Server (Express + Puppeteer)

```javascript
// server.js
const express = require('express');
const puppeteer = require('puppeteer');
const app = express();
const PORT = process.env.PORT || 3001;

app.use(express.json());

app.post('/api/screenshot', async (req, res) => {
  const { url } = req.body;
  if (!url) return res.status(400).json({ error: 'URL required' });

  try {
    const browser = await puppeteer.launch({ args: ['--no-sandbox', '--disable-setuid-sandbox'] });
    const page = await browser.newPage();
    await page.setViewport({ width: 1200, height: 800 });
    await page.goto(url, { waitUntil: 'networkidle2' });

    const data = await page.screenshot({ encoding: 'base64' });
    await browser.close();

    res.setHeader('Content-Type', 'image/png');
    res.send(Buffer.from(data, 'base64'));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Screenshot failed' });
  }
});

app.listen(PORT, () => {
  console.log(`Screenshot server running at http://localhost:${PORT}`);
});
```

