## 🔧 Utilities

### `utils.py`

```python
import re
import os
import uuid
from datetime import datetime
from markdown import markdown
from markdown.extensions import toc
from markdown.extensions.toc import TocExtension

def slugify(text):
    """Generate a clean slug from a title."""
    text = re.sub(r'[^a-zA-Z0-9\s-]', '', text).strip()
    return re.sub(r'\s+', '-', text).lower()

def generate_slug(title, existing_slugs):
    """Generate unique slug."""
    slug = slugify(title)
    counter = 1
    while slug in existing_slugs:
        slug = f"{slug}-{counter}"
        counter += 1
    return slug

def render_markdown(text):
    """Render Markdown to HTML with TOC."""
    extensions = ['toc', 'tables', 'fenced_code', 'codehilite']
    return markdown(text, extensions=extensions, output_format='html5')

def get_document_versions(document_id):
    """Get all versions of a document."""
    return DocumentVersion.query.filter_by(document_id=document_id).order_by(DocumentVersion.created_at.desc()).all()

def get_document_history(document_id):
    """Get history of actions on a document."""
    return DocumentHistory.query.filter_by(document_id=document_id).order_by(DocumentHistory.created_at.desc()).all()

def get_project_members(project_id):
    """Get members of a project."""
    return ProjectMember.query.filter_by(project_id=project_id).all()

def get_project_documents(project_id):
    """Get documents in a project."""
    return Document.query.filter_by(project_id=project_id).order_by(Document.created_at.desc()).all()

def get_api_endpoints(document_id):
    """Get API endpoints for a document."""
    return APIEndpoint.query.filter_by(document_id=document_id).order_by(APIEndpoint.path.asc()).all()
```

