    """Swagger JSON spec."""
    documents = Document.query.filter_by(is_api_spec=True).all()
    endpoints = []
    for doc in documents:
        for ep in get_api_endpoints(doc.id):
            endpoints.append({
                'path': ep.path,
                'method': ep.method,
                'description': ep.description,
                'tags': ep.tags.split(',') if ep.tags else [],
                'request': ep.request,
                'response': ep.response,
                'status': ep.status
            })
    return jsonify({
        'swagger': '2.0',
        'info': {'title': 'Documentation API', 'version': '1.0'},
        'paths': {ep['path']: {
            ep['method'].lower(): {
                'summary': ep['description'] or ep['path'],
                'parameters': [],
                'responses': {200: {'description': 'OK'}}
            } for ep in endpoints
        }}
    })

