## ⚙️ JavaScript (app.js)

```javascript
/* =========================================================
   Video Timeline Marking Tool
   ========================================================= */

const STORAGE_KEY = 'video-marking-tool-v1';
const DEFAULT_VIDEO = 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4';

const state = {
  bookmarks: [],
  currentBookmarkId: null,
  nextId: 1,
  videoId: null,
  videoDuration: 0,
  videoLoaded: false,
};

/* ---------- DOM ---------- */
const $ = (sel) => document.querySelector(sel);
const video = $('#video');
const playhead = $('#playhead');
const progress = $('#progress');
const bookmarkList = $('#bookmark-list');
const emptyState = $('#empty-state');
const addBookmarkBtn = $('#add-bookmark');
const exportBtn = $('#export-btn');
const importBtn = $('#import-btn');
const modal = $('#modal');
const modalTitle = $('#modal-title');
const noteInput = $('#note-input');
const thumbInput = $('#thumb-upload');
const thumbPreview = $('#thumb-preview');
const thumbImg = $('#thumb-img');
const removeThumbBtn = $('#remove-thumb');
const saveBookmarkBtn = $('#save-bookmark');
const fileInput = $('#thumb-upload');

/* ---------- Utilities ---------- */
function uid() { return 'b' + (state.nextId++); }
function pad(n) { return String(n).padStart(2, '0'); }
function formatTime(sec) {
  if (!isFinite(sec) || sec < 0) sec = 0;
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = Math.floor(sec % 60);
  const ms = Math.floor((sec - Math.floor(sec)) * 100);
  if (h > 0) return `${h}:${pad(m)}:${pad(s)}.${ms}`;
  return `${m}:${pad(s)}.${ms}`;
}
function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));
}

/* ---------- Storage ---------- */
function loadFromStorage() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        state.bookmarks = parsed;
        state.nextId = Math.max(1, ...parsed.map(b => parseInt(b.id, 10) || 0)) + 1;
      }
    }
  } catch (e) { /* ignore */ }
}
function saveToStorage() {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state.bookmarks)); } catch (e) { /* ignore */ }
}

/* ---------- Video ---------- */
function setupVideo() {
  video.addEventListener('loadedmetadata', () => {
    state.videoDuration = video.duration;
    state.videoLoaded = true;
    renderProgress();
  });
  video.addEventListener('timeupdate', renderProgress);
  video.addEventListener('ended', () => {
    if (state.bookmarks.length) {
      const next = state.bookmarks.find(b => b.time >= video.currentTime);
      if (next) video.currentTime = next.time;
    }
  });
  video.addEventListener('progress', () => {
    if (video.buffered.length && video.buffered.end(video.buffered.length - 1) >= video.currentTime) {
      renderProgress();
    }
  });
}

function renderProgress() {
  const pct = video.duration ? (video.currentTime / video.duration) * 100 : 0;
  progress.style.width = pct + '%';
  playhead.style.left = pct + '%';
}

/* ---------- Bookmarks ---------- */
function findBookmark(id) {
  return state.bookmarks.find(b => b.id === id);
}
function getCurrentBookmark() {
  return state.bookmarks.find(b => b.time >= video.currentTime);
}

function createBookmarkItem(bookmark) {
  const li = document.createElement('li');
  li.className = 'bookmark-item';
  li.dataset.id = bookmark.id;
  li.setAttribute('draggable', 'true');
  li.tabIndex = 0;
  li.setAttribute('role', 'button');
  li.setAttribute('aria-label', `Bookmark at ${formatTime(bookmark.time)}: ${escapeHtml(bookmark.note || 'Untitled')}`);

  const dragHandle = document.createElement('span');
  dragHandle.className = 'bookmark-drag-handle';
  dragHandle.setAttribute('aria-hidden', 'true');
  dragHandle.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>';

  const info = document.createElement('div');
  info.className = 'bookmark-info';
  info.innerHTML = `
    <span class="bookmark-time">${formatTime(bookmark.time)}</span>
    <span class="bookmark-note">${escapeHtml(bookmark.note || 'Untitled')}</span>
  `;

  const thumb = document.createElement('img');
  thumb.className = 'bookmark-thumb';
  thumb.src = bookmark.thumb || 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><rect width="32" height="32" fill="#e5e9f0"/><circle cx="16" cy="16" r="8" fill="#cbd5e1"/><text x="16" y="22" text-anchor="middle" font-size="10" fill="#64748b">No Thumb</text></svg>';
  thumb.alt = 'Thumbnail';

  const actions = document.createElement('div');
  actions.className = 'bookmark-actions';
  actions.innerHTML = `
    <button class="icon-btn" aria-label="Edit" title="Edit">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg>
    </button>
    <button class="icon-btn danger" aria-label="Delete" title="Delete">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6"></path><path d="M10 11v6M14 11v6"></path></svg>
    </button>
  `;

  dragHandle.addEventListener('click', (e) => e.stopPropagation());
  info.addEventListener('click', () => openBookmarkModal(bookmark.id));
  actions.querySelector('.icon-btn').addEventListener('click', (e) => {
    e.stopPropagation();
    if (confirm('Delete this bookmark?')) removeBookmark(bookmark.id);
  });
  thumb.addEventListener('click', () => openBookmarkModal(bookmark.id));

  li.appendChild(dragHandle);
  li.appendChild(info);
  li.appendChild(thumb);
  li.appendChild(actions);

  return li;
}

function renderBookmarks() {
  bookmarkList.innerHTML = '';
  if (!state.bookmarks.length) {
    emptyState.hidden = false;
    return;
  }
  emptyState.hidden = true;
  state.bookmarks.forEach(b => bookmarkList.appendChild(createBookmarkItem(b)));
  attachDragHandlers();
}

function attachDragHandlers() {
  bookmarkList.querySelectorAll('.bookmark-item').forEach(item => {
    item.addEventListener('dragstart', (e) => {
      item.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', item.dataset.id);
    });
    item.addEventListener('dragend', () => item.classList.remove('dragging'));
  });
  bookmarkList.addEventListener('dragover', (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  });
  bookmarkList.addEventListener('drop', (e) => {
    e.preventDefault();
    const id = e.dataTransfer.getData('text/plain');
    const targetId = e.target.closest('.bookmark-item')?.dataset.id;
    if (!id || !targetId) return;
    const ids = [...bookmarkList.querySelectorAll('.bookmark-item')].map(el => el.dataset.id);
    const idx = ids.indexOf(targetId);
    const b = state.bookmarks.find(x => x.id === id);
    if (b && idx >= 0) {
      state.bookmarks.splice(state.bookmarks.indexOf(b), 1);
      state.bookmarks.splice(idx, 0, b);
      renderBookmarks();
    }
  });
}

/* ---------- Modal ---------- */
function openBookmarkModal(id) {
  const b = findBookmark(id);
  if (!b) return;
  state.currentBookmarkId = id;
  modalTitle.textContent = b.note || 'Bookmark Details';
  noteInput.value = b.note || '';
  thumbImg.src = b.thumb || '';
  thumbImg.alt = 'Thumbnail';
  thumbPreview.hidden = false;
  removeThumbBtn.hidden = false;
  modal.hidden = false;
  document.body.style.overflow = 'hidden';
  noteInput.focus();
}
function closeBookmarkModal() {
  modal.hidden = true;
  document.body.style.overflow = '';
  state.currentBookmarkId = null;
}
function saveBookmark() {
  const id = state.currentBookmarkId;
  const b = findBookmark(id);
  if (!b) return;
  b.note = noteInput.value.trim() || 'Untitled';
  if (thumbImg.src) b.thumb = thumbImg.src;
  renderBookmarks();
  closeBookmarkModal();
  saveToStorage();
}
function removeThumbnail() {
  thumbImg.src = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><rect width="32" height="32" fill="#e5e9f0"/><circle cx="16" cy="16" r="8" fill="#cbd5e1"/><text x="16" y="22" text-anchor="middle" font-size="10" fill="#64748b">No Thumb</text></svg>';
  thumbImg.alt = 'No thumbnail';
  thumbPreview.hidden = true;
  removeThumbBtn.hidden = true;
}

/* ---------- Add / Remove ---------- */
function addBookmark() {
  const time = video.currentTime;
  const b = { id: uid(), time, note: '', thumb: '' };
  state.bookmarks.push(b);
  renderBookmarks();
  if (state.bookmarks.length === 1) {
    state.currentBookmarkId = b.id;
    openBookmarkModal(b.id);
  } else if (state.currentBookmarkId) {
    const current = findBookmark(state.currentBookmarkId);
    if (current && current.time < time) {
      state.currentBookmarkId = b.id;
      openBookmarkModal(b.id);
    }
  }
  saveToStorage();
}
function removeBookmark(id) {
  state.bookmarks = state.bookmarks.filter(b => b.id !== id);
  if (state.currentBookmarkId === id) state.currentBookmarkId = null;
  renderBookmarks();
  saveToStorage();
}

/* ---------- Export / Import ---------- */
function exportProject() {
  const data = {
    version: 1,
    bookmarks: state.bookmarks.map(b => ({
      id: b.id,
      time: b.time,
      note: b.note,
      thumb: b.thumb
    })),
    videoId: state.videoId
  };
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `video-marking-${Date.now()}.json`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
function importProject(raw) {
  try {
    const data = JSON.parse(raw);
    if (data.version !== 1) {
      alert('Unsupported project format. Please export from the latest version.');
      return;
    }
    state.bookmarks = data.bookmarks.map(b => ({
      id: uid(),
      time: b.time,
      note: b.note || '',
      thumb: b.thumb || ''
    }));
    renderBookmarks();
    saveToStorage();
  } catch (e) {
    alert('Failed to parse import file. Please ensure it is a valid JSON.');
  }
}

/* ---------- Events ---------- */
addBookmarkBtn.addEventListener('click', addBookmark);
exportBtn.addEventListener('click', exportProject);
importBtn.addEventListener('click', () => {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'application/json';
  input.hidden = true;
  document.body.appendChild(input);
  input.click();
  input.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) importProject(file);
    document.body.removeChild(input);
  });
});

thumbInput.addEventListener('change', (e) => {
  const file = e.target.files[0];
  if (file) {
    const reader = new FileReader();
    reader.onload = (ev) => {
      thumbImg.src = ev.target.result;
      thumbImg.alt = 'Uploaded thumbnail';
      thumbPreview.hidden = false;
      removeThumbBtn.hidden = false;
    };
    reader.readAsDataURL(file);
  }
});
thumbInput.addEventListener('dragover', (e) => { e.preventDefault(); });
thumbInput.addEventListener('drop', (e) => {
  e.preventDefault();
  const file = e.dataTransfer.files[0];
  if (file) {
    const reader = new FileReader();
    reader.onload = (ev) => {
      thumbImg.src = ev.target.result;
      thumbImg.alt = 'Uploaded thumbnail';
      thumbPreview.hidden = false;
      removeThumbBtn.hidden = false;
    };
    reader.readAsDataURL(file);
  }
});
removeThumbBtn.addEventListener('click', removeThumbnail);

modal.addEventListener('click', (e) => {
  if (e.target.hasAttribute('data-close')) closeBookmarkModal();
});
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && !modal.hidden) closeBookmarkModal();
});

/* ---------- Keyboard shortcuts ---------- */
document.addEventListener('keydown', (e) => {
  if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
  if (e.key === 'Enter' && !modal.hidden) {
    e.preventDefault();
    saveBookmark();
  }
  if (e.key === 'Delete' && state.currentBookmarkId) {
    if (confirm('Delete this bookmark?')) removeBookmark(state.currentBookmarkId);
  }
});

/* ---------- Init ---------- */
function init() {
  loadFromStorage();
  if (state.bookmarks.length === 0) {
    const b = { id: uid(), time: 0, note: 'Start', thumb: '' };
    state.bookmarks.push(b);
  }
  renderBookmarks();
  setupVideo();
  if (video.src === '') video.src = DEFAULT_VIDEO;
  if (video.readyState > 0) {
    video.play().catch(() => { /* autoplay blocked */ });
  }
}

document.addEventListener('DOMContentLoaded', init);
```

