          v-if="drone.status === 'on-ground'"
          class="btn btn-primary"
          @click="takeoff"
          :disabled="isTakingOff"
        >
          <i class="fa-solid fa-plane-take-off"></i> Take Off
        </button>
        <button
          v-if="drone.status === 'in-flight' || drone.status === 'landing'"
          class="btn btn-danger"
          @click="land"
          :disabled="isLanding"
        >
          <i class="fa-solid fa-plane-arrival"></i> Land
        </button>
        <button
          v-if="drone.status === 'malfunction'"
          class="btn btn-warning"
          @click="reset"
        >
          <i class="fa-solid fa-arrows-rotate"></i> Reset
        </button>
      </div>
    </div>
  </article>
