<script setup>
import StatusBadge from './StatusBadge.vue';
import { ref } from 'vue';

const props = defineProps({
  drone: {
    type: Object,
    required: true
  }
});

const emit = defineEmits(['takeoff', 'land', 'reset']);

const isTakingOff = ref(false);
const isLanding = ref(false);

const takeoff = () => {
  if (props.drone.status !== 'on-ground') return;
  isTakingOff.value = true;
  setTimeout(() => {
    emit('takeoff', props.drone.id);
    isTakingOff.value = false;
  }, 1200);
};

const land = () => {
  if (props.drone.status !== 'in-flight' && props.drone.status !== 'landing') return;
  isLanding.value = true;
  setTimeout(() => {
    emit('land', props.drone.id);
    isLanding.value = false;
  }, 1400);
};

const reset = () => {
  emit('reset', props.drone.id);
};
</script>

