<script setup>
import DroneCard from './DroneCard.vue';
import { ref } from 'vue';

const droneList = ref([]);

const handleTakeoff = (id) => {
  const d = droneList.value.find(x => x.id === id);
  if (!d) return;
  d.status = 'in-flight';
  d.location = 'Sky';
};

const handleLand = (id) => {
  const d = droneList.value.find(x => x.id === id);
  if (!d) return;
  d.status = 'landing';
  d.location = 'Runway';
  setTimeout(() => {
    d.status = 'on-ground';
    d.location = '';
  }, 1600);
};

const handleReset = (id) => {
  const d = droneList.value.find(x => x.id === id);
  if (!d) return;
  d.status = 'malfunction';
  d.location = 'Maintenance';
  setTimeout(() => {
    d.status = 'on-ground';
    d.location = '';
  }, 2000);
};
</script>

