const express = require('express');
const cors = require('cors');
const app = express();
const PORT = process.env.PORT || 5000;

app.use(cors());
app.use(express.json());

// In-memory store
const drones = [];

// Auth middleware
function requireAdmin(req, res, next) {
  if (req.headers['authorization'] !== 'Bearer uavadmin') {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

// Seed
function seed() {
  const now = Date.now();
  drones.push({
    id: String(now + 1),
    name: 'SkyHawk-01',
    model: 'DJI Mavic 3',
    serial: 'SN-123456',
    status: 'on-ground',
    location: ''
  });
  drones.push({
    id: String(now + 2),
    name: 'AeroRaptor-02',
    model: 'Autel EVO Lite+',
    serial: 'SN-234567',
    status: 'on-ground',
    location: ''
  });
  drones.push({
    id: String(now + 3),
    name: 'Orbit-03',
    model: 'DJI Mini 4 Pro',
    serial: 'SN-345678',
    status: 'on-ground',
    location: ''
  });
}

// Routes
app.get('/api/drones', (req, res) => {
  res.json(drones);
});

app.post('/api/drones', requireAdmin, (req, res) => {
  const { name, model, serial } = req.body;
  if (!name || !model || !serial) {
    return res.status(400).json({ error: 'Name, model, and serial are required' });
  }
  const id = Date.now().toString();
  drones.push({ id, name, model, serial, status: 'on-ground', location: '' });
  res.status(201).json({ id, message: 'Drone added successfully' });
});

app.put('/api/drones/:id/takeoff', (req, res) => {
  const id = req.params.id;
  const d = drones.find(x => x.id === id);
  if (!d) return res.status(404).json({ error: 'Drone not found' });
  d.status = 'in-flight';
  d.location = 'Sky';
  res.json({ id, status: d.status, location: d.location });
});

app.put('/api/drones/:id/land', (req, res) => {
  const id = req.params.id;
  const d = drones.find(x => x.id === id);
  if (!d) return res.status(404).json({ error: 'Drone not found' });
  d.status = 'landing';
  d.location = 'Runway';
  setTimeout(() => {
    d.status = 'on-ground';
    d.location = '';
  }, 1600);
  res.json({ id, status: d.status, location: d.location });
});

app.put('/api/drones/:id/reset', (req, res) => {
  const id = req.params.id;
  const d = drones.find(x => x.id === id);
  if (!d) return res.status(404).json({ error: 'Drone not found' });
  d.status = 'malfunction';
  d.location = 'Maintenance';
  setTimeout(() => {
    d.status = 'on-ground';
    d.location = '';
  }, 2000);
  res.json({ id, status: d.status, location: d.location });
});

app.delete('/api/drones/:id', requireAdmin, (req, res) => {
  const id = req.params.id;
  drones.splice(drones.findIndex(x => x.id === id), 1);
  res.json({ message: 'Drone removed' });
});

// Health
app.get('/api/health', (req, res) => {
