```python
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy import func
from sqlalchemy.dialects.postgresql import ARRAY
from sqlalchemy.ext.hybrid import hybrid_property
from datetime import datetime
import numpy as np
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics.pairwise import cosine_similarity

db = SQLAlchemy()

class User(db.Model):
    __tablename__ = 'users'
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    first_name = db.Column(db.String(50))
    last_name = db.Column(db.String(50))
    goals = db.Column(db.Text)  # comma-separated string of goals
    interests = db.Column(db.Text)  # comma-separated string of interests
    schedule = db.Column(db.Text)  # JSON-like string of {day: [slots]}
    bio = db.Column(db.Text)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

    def __repr__(self):
        return f'<User {self.username}>'

    @hybrid_property
    def goals_list(self):
        return self.goals.split(',') if self.goals else []

    @hybrid_property
    def interests_list(self):
        return self.interests.split(',') if self.interests else []

    @hybrid_property
    def schedule_dict(self):
        import json
        try:
            return json.loads(self.schedule)
        except:
            return {}

    @staticmethod
    def goals_vector(user):
        """TF-IDF vector for goals."""
        goals = user.goals_list
        if not goals:
            return np.zeros(5)
        vectorizer = TfidfVectorizer(ngram_range=(1, 2), stop_words='english', max_features=5)
        return vectorizer.fit_transform(goals).toarray()

    @staticmethod
    def schedule_vector(user):
        """Vector of available slots."""
        slots = set()
        for day in user.schedule_dict:
            for slot in user.schedule_dict[day]:
                slots.add(slot)
        return np.array([1 if s in slots else 0 for s in ALL_SLOTS])

    @staticmethod
    def similarity(user1, user2):
        """Weighted cosine + Jaccard similarity."""
        # Goals
        v1, v2 = user1.goals_vector(user1), user2.goals_vector(user2)
        if v1.shape[0] == 0 or v2.shape[0] == 0:
            cos_goals = 0
        else:
            cos_goals = cosine_similarity(v1, v2)[0][0]

        # Interests (Jaccard)
        set1, set2 = set(user1.interests_list), set(user2.interests_list)
        jaccard_interests = len(set1 & set2) / len(set1 | set2) if set1 | set2 else 0

        # Schedule (Jaccard)
        slots1, slots2 = set(user1.schedule_list), set(user2.schedule_list)
        jaccard_schedule = len(slots1 & slots2) / len(slots1 | slots2) if slots1 | slots2 else 0

        # Weighted average
        return 0.4 * cos_goals + 0.3 * jaccard_interests + 0.3 * jaccard_schedule

    def top_matches(self, n=5):
        """Return top n matches excluding self."""
        others = User.query.filter(User.id != self.id).all()
        scores = [(u, self.similarity(self, u)) for u in others]
        scores.sort(key=lambda x: x[1], reverse=True)
        return scores[:n]

class Invitation(db.Model):
    __tablename__ = 'invitations'
    id = db.Column(db.Integer, primary_key=True)
    from_user_id = db.Column(db.Integer, db.ForeignKey('users.id'), nullable=False)
    to_user_id = db.Column(db.Integer, db.ForeignKey('users.id'), nullable=False)
    message = db.Column(db.Text)
    status = db.Column(db.String(20), default='pending')  # pending, accepted, rejected
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    accepted_at = db.Column(db.DateTime)
    rejected_at = db.Column(db.DateTime)

    def __repr__(self):
        return f'<Invitation {self.from_user.username} -> {self.to_user.username}>'

class Pairing(db.Model):
    __tablename__ = 'pairings'
    id = db.Column(db.Integer, primary_key=True)
    user1_id = db.Column(db.Integer, db.ForeignKey('users.id'), nullable=False)
    user2_id = db.Column(db.Integer, db.ForeignKey('users.id'), nullable=False)
    start_date = db.Column(db.Date)
    end_date = db.Column(db.Date)
    status = db.Column(db.String(20), default='active')  # active, completed, cancelled
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

    def __repr__(self):
        return f'<Pairing {self.user1.username} + {self.user2.username}>'

class Feedback(db.Model):
    __tablename__ = 'feedback'
    id = db.Column(db.Integer, primary_key=True)
    pairing_id = db.Column(db.Integer, db.ForeignKey('pairings.id'), nullable=False)
    from_user_id = db.Column(db.Integer, db.ForeignKey('users.id'), nullable=False)
    rating = db.Column(db.Integer)  # 1-5
    comment = db.Column(db.Text)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

    def __repr__(self):
        return f'<Feedback {self.rating} for pairing {self.pairing_id}>'
