## 🧱 Database Schema (Prisma)

```prisma
// schema.prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model User {
  id            Int     @id @default(autoincrement())
  email         String  @unique
  password      String
  name          String
  role          String  @default("buyer")
  avatarUrl     String?
  createdAt     DateTime @default(now())
  updatedAt     DateTime @updatedAt
  listings      Listing[]
  reviews       Review[]
  cartItems     CartItem[]
}

model Listing {
  id          Int      @id @default(autoincrement())
  title       String
  category    String
  price       Float
  description String
  images      String[] // Cloudinary URLs
  sellerId    Int
  buyerId     Int?     // null if not purchased
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt
  seller      User     @relation(fields: [sellerId], references: [id])
  buyer       User?    @relation(fields: [buyerId], references: [id])
  reviews     Review[]
  cartItems   CartItem[]
}

model Review {
  id       Int      @id @default(autoincrement())
  rating   Int      // 1-5
  comment  String?
  userId   Int
  listingId Int
  user     User     @relation(fields: [userId], references: [id])
  listing  Listing  @relation(fields: [listingId], references: [id])
}

model CartItem {
  id         Int      @id @default(autoincrement())
  listingId  Int
  listing    Listing @relation(fields: [listingId], references: [id])
  buyerId    Int
  buyer      User?   @relation(fields: [buyerId], references: [id])
  negotiator String  // "buyer" | "seller"
  price      Float
  status     String  @default("pending") // pending | accepted | rejected
  createdAt  DateTime @default(now())
}
