## 📦 Cart & Negotiation

```javascript
// services/cart.js
import { db } from '../db';

export const addToCart = async (listingId, userId, negotiator) => {
  const existing = await db.cartItem.findFirst({
    where: { listingId, buyerId: userId }
  });
  if (existing) return existing;
  return await db.cartItem.create({
    data: { listingId, buyerId: userId, negotiator }
  });
};

export const getCartItems = async (userId) => {
  return await db.cartItem.findMany({
    where: { buyerId: userId },
    include: { listing: true }
  });
};

export const negotiate = async (cartItemId, newPrice, message) => {
  const item = await db.cartItem.findUnique({ where: { id: cartItemId } });
  if (!item || item.status !== 'pending') throw new Error('Cannot negotiate');
  await db.cartItem.update({
    where: { id: cartItemId },
    data: { price: newPrice, status: 'pending' }
  });
  return { success: true, message };
};

export const acceptNegotiation = async (cartItemId) => {
  const item = await db.cartItem.findUnique({ where: { id: cartItemId } });
  if (!item || item.status !== 'pending') throw new Error('Cannot accept');
  await db.cartItem.update({
    where: { id: cartItemId },
    data: { status: 'accepted' }
  });
  // Simulate payment
  await db.listing.update({
    where: { id: item.listingId },
    data: { buyerId: item.buyerId }
  });
  return { success: true, message: 'Deal accepted! Payment simulated.' };
};

export const rejectNegotiation = async (cartItemId) => {
  await db.cartItem.update({
    where: { id: cartItemId },
    data: { status: 'rejected' }
  });
  return { success: true, message: 'Negotiation rejected.' };
};
