## 🛒 Cart Page

```javascript
// pages/Cart.js
import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import { api } from '../services/api';
import NegotiationModal from '../components/cart/NegotiationModal';

export default function Cart() {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const { user } = useAuth();
  const [negotiation, setNegotiation] = useState({ price: 0, message: '' });

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    const fetch = async () => {
      try {
        const res = await api.get('/cart');
        setItems(res.data);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetch();
  }, [user, navigate]);

  const handleNegotiate = (e) => {
    e.preventDefault();
    if (!negotiation.price || negotiation.price <= 0) return;
    // Simulate negotiation
    setNegotiation({ price: 0, message: '' });
  };

  if (loading) return <div className="p-8 text-center">Loading cart...</div>;

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-3xl font-bold mb-4">Your Cart</h1>
      {items.length === 0 ? (
        <div className="text-center p-16">
          <p className="text-lg">Your cart is empty.</p>
          <button onClick={() => navigate('/listings')} className="mt-4 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
            Browse listings
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div>
            {items.map((item) => (
              <div key={item.id} className="border p-4 rounded mb-4">
                <div className="flex items-center gap-3 mb-2">
                  <img src={item.listing.images[0]} alt={item.listing.title} className="w-20 h-20 object-cover rounded" />
                  <div>
                    <p className="font-bold">{item.listing.title}</p>
                    <p className="text-sm text-gray-500">${item.listing.price.toFixed(2)}</p>
                  </div>
                </div>
                <p className="text-sm text-gray-600">{item.listing.description}</p>
                <div className="mt-4 flex justify-between items-center">
                  <div>
                    <span className="font-bold">Status</span>
                    <p className="text-sm text-gray-500">{item.status}</p>
                  </div>
                  <button
                    onClick={() => setNegotiation({ price: item.listing.price, message: '' })}
                    className="px-3 py-1 bg-gray-200 text-gray-700 rounded hover:bg-gray-300"
                  >
                    Negotiate
                  </button>
                </div>
              </div>
            ))}
          </div>

          <div className="space-y-4">
            <div className="p-4 border rounded">
              <h3 className="font-bold">Negotiation</h3>
              <form onSubmit={handleNegotiate} className="mt-2">
                <label className="block text-sm font-medium">New Price ($)</label>
                <input
                  type="number"
                  value={negotiation.price}
                  onChange={(e) => setNegotiation({ ...negotiation, price: parseFloat(e.target.value) || 0 })}
                  className="mt-1 w-full p-2 border rounded"
                  min="0"
                />
                <label className="block text-sm font-medium mt-2">Message</label>
                <textarea
                  value={negotiation.message}
                  onChange={(e) => setNegotiation({ ...negotiation, message: e.target.value })}
                  className="mt-1 w-full p-2 border rounded"
                  rows="2"
                />
                <button type="submit" className="w-full mt-2 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
                  Send Negotiation
                </button>
              </form>
            </div>
            <div className="p-4 border rounded">
              <h3 className="font-bold">Payment</h3>
              <p className="text-sm text-gray-600">Complete payment after negotiation acceptance.</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
