  const statuses = {
    pending: { label: '待支付', color: 'pending' },
    success:  { label: '支付成功', color: 'success' },
    cancelled:{ label: '已取消', color: 'cancelled' },
    delivered:{ label: '已送达', color: 'delivered' },
    expired:  { label: '已过期', color: 'expired' }
  };

  function updateCard(cardId, newStatus) {
    const el = document.getElementById(cardId);
    const statusEl = document.getElementById(cardId + 'Status');
    const statusText = document.getElementById(cardId + 'StatusText');
    const amountEl = document.getElementById(cardId + 'Amount');
    const jumpBtn = document.getElementById(cardId + 'Jump');

    const state = statuses[newStatus];
    statusEl.dataset.status = newStatus;
    statusEl.className = 'status ' + state.color;
    statusText.textContent = state.label;

    // Amount animation
    const current = parseFloat(amountEl.textContent.replace('¥', '').replace(',', ''));
    const target = newStatus === 'success' ? 0 : current;
    amountEl.textContent = '¥ ' + target.toFixed(2);

    // Jump button
    const isJumpable = newStatus === 'success' || newStatus === 'delivered';
    jumpBtn.disabled = !isJumpable;

    // Update all cards' jump buttons
    ['meituan', 'jd', 'pdd', 'didi', 'ctrip'].forEach(id => {
      const btn = document.getElementById(id + 'Jump');
      const stateId = document.getElementById(id + 'Status').dataset.status;
      btn.disabled = stateId !== 'success' && stateId !== 'delivered';
    });
  }

  function simulateJump(cardId) {
    const btn = document.getElementById(cardId + 'Jump');
    const originalText = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-circle-check jump-icon"></i> <span>跳转中…</span>';

    setTimeout(() => {
      btn.innerHTML = '<i class="fa-solid fa-arrow-up-right-from-square jump-icon"></i> <span>跳转官方页面</span>';
      btn.disabled = false;
    }, 1200);
  }

  // Event listeners
  document.getElementById('meituanStatus').addEventListener('click', () => {
    const current = document.getElementById('meituanStatus').dataset.status;
    const next = current === 'pending' ? 'success' : 'cancelled';
    updateCard('meituan', next);
  });
  document.getElementById('jdStatus').addEventListener('click', () => {
    const current = document.getElementById('jdStatus').dataset.status;
    const next = current === 'pending' ? 'success' : 'cancelled';
    updateCard('jd', next);
  });
  document.getElementById('pddStatus').addEventListener('click', () => {
    const current = document.getElementById('pddStatus').dataset.status;
    const next = current === 'pending' ? 'success' : 'cancelled';
    updateCard('pdd', next);
  });
  document.getElementById('didiStatus').addEventListener('click', () => {
    const current = document.getElementById('didiStatus').dataset.status;
    const next = current === 'pending' ? 'delivered' : 'cancelled';
    updateCard('didi', next);
  });
  document.getElementById('ctripStatus').addEventListener('click', () => {
    const current = document.getElementById('ctripStatus').dataset.status;
    const next = current === 'pending' ? 'success' : 'cancelled';
    updateCard('ctrip', next);
  });

  document.getElementById('meituanJump').addEventListener('click', () => simulateJump('meituan'));
  document.getElementById('jdJump').addEventListener('click', () => simulateJump('jd'));
  document.getElementById('pddJump').addEventListener('click', () => simulateJump('pdd'));
  document.getElementById('didiJump').addEventListener('click', () => simulateJump('didi'));
  document.getElementById('ctripJump').addEventListener('click', () => simulateJump('ctrip'));

  // Keyboard accessibility: Enter/Space on status
  document.querySelectorAll('.status').forEach(el => {
    el.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        el.click();
      }
    });
  });
</script>

