## 🧩 `server.js`

```javascript
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs').promises;
const app = express();
const PORT = process.env.PORT || 3000;

// Ensure file folder exists
const FILE_DIR = path.join(__dirname, 'file');
try {
  fs.accessSync(FILE_DIR);
} catch {
  fs.mkdirSync(FILE_DIR, { recursive: true });
}

// ---------- Multer setup ----------
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, FILE_DIR);
  },
  filename: (req, file, cb) => {
    // Use a unique chunk name based on file name + chunk index
    const ext = path.extname(file.originalname);
    const name = path.basename(file.originalname, ext);
    const index = req.body.chunkIndex;
    const count = req.body.chunkCount;
    const chunkName = `${name}_${index}_${count}${ext}`;
    cb(null, chunkName);
  }
});

const upload = multer({ storage });

// ---------- API ----------
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

app.post('/api/upload', upload.single('file'), async (req, res) => {
  const { chunkIndex, chunkCount, fileName } = req.body;

  // If this is the last chunk, reassemble file
  if (chunkIndex === chunkCount - 1) {
    try {
      const chunks = [];
      for (let i = 0; i < chunkCount; i++) {
        const chunkPath = path.join(FILE_DIR, `${fileName}_${i}_${chunkCount}`);
        const chunkData = await fs.readFile(chunkPath);
        chunks.push(chunkData);
      }
      const finalPath = path.join(FILE_DIR, `${fileName}.final`);
      await fs.writeFile(finalPath, Buffer.concat(chunks));
      await fs.promises.rm(FILE_DIR, { recursive: true, force: true });
      res.json({ success: true, message: 'File uploaded and reassembled successfully.' });
    } catch (err) {
      console.error(err);
      res.status(500).json({ success: false, message: 'Failed to reassemble file.' });
    }
  } else {
    // Just store the chunk
    res.json({ success: true, message: `Chunk ${chunkIndex} stored.` });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

