## 💡 `public/script.js`

```javascript
(function () {
  'use strict';

  const CHUNK_SIZE = 2 * 1024 * 1024; // 2 MB
  const MAX_CHUNKS = 100;

  const dropzone = document.getElementById('dropzone');
  const fileInput = document.getElementById('fileInput');
  const chunkSizeInput = document.getElementById('chunkSize');
  const chunkCountEl = document.getElementById('chunkCount');
  const progress = document.getElementById('progress');
  const progressBar = document.getElementById('progressBar');
  const progressText = document.getElementById('progressText');
  const progressFile = document.getElementById('progressFile');
  const statusEl = document.getElementById('status');
  const startBtn = document.getElementById('startBtn');
  const resetBtn = document.getElementById('resetBtn');

  let file = null;
  let totalChunks = 0;
  let currentChunk = 0;
  let isUploading = false;
  let totalBytes = 0;
  let uploadedBytes = 0;

  function getChunkCount(file) {
    const size = file.size;
    if (size <= CHUNK_SIZE) return 1;
    return Math.min(Math.ceil(size / CHUNK_SIZE), MAX_CHUNKS);
  }

  function formatBytes(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    if (bytes < 1024 * 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
    return (bytes / (1024 * 1024 * 1024)).toFixed(2) + ' GB';
  }

  function updateProgress() {
    if (totalBytes === 0) return;
    const pct = Math.round((uploadedBytes / totalBytes) * 100);
    progressBar.style.width = pct + '%';
    progressText.textContent = pct + '%';
    progressFile.textContent = `${formatBytes(uploadedBytes)} / ${formatBytes(totalBytes)}`;
  }

  function setStatus(text, type) {
    statusEl.textContent = text;
    statusEl.className = 'status ' + (type || '');
  }

  function resetUI() {
    file = null;
    totalChunks = 0;
    currentChunk = 0;
    isUploading = false;
    totalBytes = 0;
    uploadedBytes = 0;
    updateProgress();
    setStatus('Ready. Drag and drop a file to begin.', '');
    startBtn.disabled = true;
    progress.classList.add('hidden');
    resetBtn.disabled = true;
  }

  // Dropzone events
  ['dragenter', 'dragover'].forEach(evt => {
    dropzone.addEventListener(evt, (e) => {
      e.preventDefault();
      e.stopPropagation();
      dropzone.classList.add('dragover');
    });
  });
  ['dragleave', 'drop'].forEach(evt => {
    dropzone.addEventListener(evt, (e) => {
      e.preventDefault();
      e.stopPropagation();
      dropzone.classList.remove('dragover');
    });
  });
  dropzone.addEventListener('drop', (e) => {
    const files = e.dataTransfer.files;
    if (files && files.length) handleFile(files[0]);
  });

  dropzone.addEventListener('click', () => fileInput.click());
  dropzone.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      fileInput.click();
    }
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files && e.target.files.length) handleFile(e.target.files[0]);
    fileInput.value = '';
  });

  function handleFile(f) {
    if (f.size === 0) {
      setStatus('Invalid file. Please select a non-empty file.', 'error');
      return;
    }
    file = f;
    totalChunks = getChunkCount(f);
    totalBytes = f.size;
    currentChunk = 0;
    uploadedBytes = 0;
    updateProgress();
    chunkCountEl.textContent = totalChunks + ' chunks';
    setStatus(`Selected: ${f.name} (${formatBytes(f.size)})`, '');
    startBtn.disabled = false;
    resetBtn.disabled = false;
    progress.classList.remove('hidden');
  }

  async function uploadChunk() {
    if (!file || isUploading) return;
    isUploading = true;
    setStatus('Uploading chunk…', '');

    const chunkSize = parseInt(chunkSizeInput.value, 10) * 1024 * 1024;
    const start = currentChunk * chunkSize;
    const end = Math.min(start + chunkSize, file.size);
    const chunk = file.slice(start, end);

    const formData = new FormData();
    formData.append('file', chunk);
    formData.append('chunkIndex', currentChunk);
    formData.append('chunkCount', totalChunks);
    formData.append('fileName', file.name);

    try {
      const res = await fetch('/api/upload', {
        method: 'POST',
        body: formData
      });
      const data = await res.json();
      if (!data.success) {
        setStatus('Upload failed: ' + (data.message || 'Unknown error'), 'error');
        isUploading = false;
        return;
      }
      uploadedBytes = end;
      currentChunk++;
      updateProgress();
      setStatus(`Uploaded ${formatBytes(uploadedBytes)} of ${formatBytes(totalBytes)}`, 'success');
    } catch (err) {
      setStatus('Network error during upload.', 'error');
      isUploading = false;
      return;
    } finally {
      isUploading = false;
    }
  }

  startBtn.addEventListener('click', () => {
    if (!file) return;
    if (currentChunk >= totalChunks) {
      setStatus('All chunks uploaded. Reassembling…', 'success');
      setTimeout(() => {
        setStatus('Upload complete! File reassembled successfully.', 'success');
      }, 1500);
    } else {
      uploadChunk();
    }
  });

  resetBtn.addEventListener('click', resetUI);

  // Auto-upload on file change
  fileInput.addEventListener('change', () => {
    if (fileInput.files && fileInput.files.length) handleFile(fileInput.files[0]);
  });
})();
```

